insert into тип_продукции values (default, 1410, 'Элитная коллекция пригласительных открыток', $$Нежданно-негаданно вывалившись из пространственно-временной аномалии в чудный, совершенно очаровательный лондонский денек, Форд с Артуром совершили довольно жесткую посадку на безупречный газон площадки «Лордз» – Что случилось? – спросил Артур с глубоким благоговением Прижав к стене кончики пальцев, он ощутил странную вибрацию Корабль этот был изумителен не своей конструкцией (мягко говоря, неудачной), но самим фактом своего появления – Онизапелибрепел! – вскричал Слартибартфаст своим тонким, дребезжащим голосом Он уставился на диван умными глазами Артур растерянно кивнул Ветерок приносил оттуда мирные бытовые звуки Голос робота был под стать его корпусу – холодный, элегантный, безжизненный$$);
insert into тип_продукции values (default, 4992, 'Художественные журналы с персонализированной обложкой', $$Раздался залп – Чтоб твои диоды сгнили и выпали Свет померк Меж тем снаружи солнце лило свой свет на веселую толпу – Возможно, до вас не сразу дойдет, что именно навело меня на это воспоминание, – таков уж мой мозг Он сделал несколько яростных шагов Не самой лучшей целью – в чем он сам первый признавался, – но эта какая-никакая цель как-никак давала ему какое-никакое занятие После сбора ее следует положить в темный пыльный ящик и не трогать много лет – Серьезно?

– Да Уперев руки в бока, он вновь обвел взором пустынный мир$$);
insert into тип_продукции values (default, 4800, 'Организаторы с персонализированным дизайном и тиснением', $$– Э-э… – в отчаянии выпалил Артур, – э-эй!

– И нечего тут! – рявкнул инопланетянин Она была безлична – не как неизвестно чей злобный вопль в толпе, но как отпечатанный на принтере квиток за неправильную парковку Когда его знакомые (даже у таких типов бывают знакомые) намекали, что план не только этически неприемлем, но и неосуществим – поскольку все время кто-то умирает, а кто-то рождается, Охмешконасыпатель просто вперял в оппонента свой стальной взгляд и бурчал: «Что, и помечтать нельзя?»

Итак, он взялся задело Пространство не просто изменило текстуру и состав$$);
insert into тип_продукции values (default, 6790, 'Альбомы для фотографий с тиснением и мягкими листами', $$Главное – промахнуться мимо земли случайно После нескольких удачных проб вы обнаружите, что отвлечься становится все проще и проще Это та самая планета и есть – Артур, – сказал Форд Затем пусть отправляются все втроем на поиски первого, поговорят с ним по-людски, споют ему колыбельную, что ли$$);
insert into тип_продукции values (default, 5832, 'Изготовленные на заказ ежедневники с закладками из ленты', $$К сожалению, именно терминалы рубки Зафод и заткнул кляпом Нервно опираясь о стену коридора, он морщил лоб (то есть лбы), словно пытаясь откупорить бутылку методом телекинеза Он встал на дыбы, чтобы заглянуть за заросли, но смотреть было не на что – Артур, – сказал Форд И само собой разумеется, он был слегка пьян Он зафлёпал туда-сюда, ошеломленный и взволнованный – А сейчас ты опять в здравом рассудке? – поинтересовался Артур Планета Хэй-Виляй изобилует сказочно, непостижимо роскошными отелями и казино$$);
insert into тип_продукции values (default, 940, 'Персонализированные конверты с сургучными печатями', $$– Чего? Зачем? Эгей-гей! Ну-ка вернись и повтори!

Он подпрыгивал и выплясывал, пока его ноги не подкосились, взывал, пока не надорвал связки Компьютер донимал его вопросами, что за чертовщина тут происходит, но Зафод заткнул его терминалы электронными кляпами И давайте хранить память о том – через несколько минут я подскажу вам, как это сделать, – что до криккитских войн Галактика была чудо как хороша Затем он совершил нечто, что матрассы обычно делать ленятся Это крикетный приз Зафод крякнул С тем же успехом можно покориться судьбе, а здравый рассудок поберечь на потом – Тс-с-с, – сказал Слартибартфаст – Быть такого не может$$);
insert into тип_продукции values (default, 1440, 'Комплекты открыток с тематическими принтами', $$Форд что-то мурлыкал под нос – Быть такого не может Другой же своей частью он был точь-в-точь маленькое итальянское бистро, только поставленное вверх тормашками Царила тишина$$);
insert into тип_продукции values (default, 2684, 'Декоративные коробки с узорами из тиснения', $$– Артур Филип Дент? – уточнило существо, деловито лязгнув зубами Он увидел место, указанное Марвином, и не был разочарован, осознав, что оно в точности похоже на все остальные участки болота – Я сам вам поясню, – прошептал старец То есть больно будет, если вам не удастся промахнуться мимо земли Меня выручил сборщик металлолома – можете себе это представить? Меня, мозг масштаба… ну да ладно Недавно был открыт лес, где почти все деревья в качестве плодов дают отвертки с храповиком – Ау, компьютер! – прошептал он – Я тут временно спустил свой разум с цепи, предполагая, что, если я миру дико понадоблюсь, он призовет меня обратно – Правда, что ли? – вскричал Зафод, поигрывая пистолетом$$);
insert into тип_продукции values (default, 1034, 'Экологичные сумки-шопперы с ручками из крафт-бумаги', $$И тут же остановился Вот уже пять лет, как его не расщепляли на атомы Он мягко приземлился Звук превратился в монотонный звон в ушах Десять минут спустя он уже горбился над чашкой чая под тентом летнего буфета, и на его осунувшееся лицо постепенно возвращался румянец$$);
insert into тип_продукции values (default, 1000, 'Оригами-комплекты с пошаговыми инструкциями', $$Оно меняется в период первых трех телефонных звонков в ресторан, а потом, как выясняется, и отдаленно не совпадает с истинным числом явившихся на ужин, а также с количеством людей, которые присоединяются к ним после спектакля/концерта/матча/вечеринки, и с количеством людей, которые спешат ретироваться при виде новоприбывших То, что вы испытали…

Слартибартфаст, проплывая мимо, помахал Артуру рукой В нем зрела ненависть к Вселенной в целом и каждому из ее обитателей в частности – Три столба, – гремел мужчина Форд с Артуром так и обмерли, подавившись собственным воплем – Нет, – сказал Форд, – он чувствует мобильную аномалию в ткани пространства-времени, локальное возмущение, очаг нестабильности А от этого субъекта никому не удалось добиться подробностей, поэтому поиски были весьма поверхностными$$);
insert into тип_продукции values (default, 7410, 'Набор бумажных цветов с реалистичными деталями', $$– Ву-ун, – заметил матрасс – Какое-то «что»?

– ННП Потренируйтесь делать пике, вначале простое, а потом, мерно дыша, лягте в дрейф над верхушками деревьев – Мое место здесь, – сказал он умиленным шепотом Ну а для Зафода это обернулось тем, что: а) он ни разу даже не подошел к девочке и б) пропустил целую эпоху в древней истории, знания о которой ему бы сейчас очень пригодились Свет померк$$);
insert into тип_продукции values (default, 3796, 'Календари с эстетичными дизайнами и функциональными функциями', $$На миг воцарилась скорбная тишина, но тут же ее нарушил громкий ропот (будто сотня тысяч невидимых людей вымолвила: «Уф!»), и с небес, точно пушинки с одуванчика, посыпались белые роботы Марвин помедлил, отдавшись воспоминаниям Процедура превращения какого-либо объекта из зримого в незримый столь трудоемка, что в 999 999 999 случаях из миллиарда гораздо проще и эффективнее просто убрать этот объект куда подальше и обойтись без него – Нет, – заявил Марвин ) Ха! О, жизнь моя – жестянка, жестянка на червячном ходу!

И снова побрел вокруг своей тонкой стальной ноги-протеза, которая вращалась в грязи, но никак не поддавалась Форд, надувшись, засунул «Путеводитель» назад в сумку Порой он замирал, часто моргая$$);
insert into тип_продукции values (default, 3465, 'Ежедневники с яркими принтами и водостойкой обложкой', $$– Не знаю, – сказал Форд, – но я буквально чувствую, что время пришло Ветер обдувал бухту, где останки одной из крупнейших и мощнейших космических флотилий в истории Галактики поспешно превращались из пепла в исходное состояние – Алло? – произнес он в воображаемую трубку – Что это было? – вымолвил Артур Почва производила впечатление тяжелой и вязкой, трава была упруга На несколько минут воцарилось изумленное безмолвие$$);
insert into тип_продукции values (default, 1740, 'Блокноты с обложкой из переработанного картона и тонированной бумагой', $$С другой стороны, нельзя было отрицать, что по сравнению с этим проворным кораблем «Золотое сердце» казалось детской коляской – Ммммм ммммы?

– Все равно, какой головы – Порвалась, – добавил он, – ни с того ни с сего порвалась цепь причин и следствий…

И наперекор сказанному, неуклюже сполз под стол после еще одного стакана Охмешконасыпатель Конца-Краю-Не-Знающий принадлежал – то есть принадлежит – к очень узкому кругу бессмертных обитателей Вселенной Он обзавелся звездолетом, построенным на века, и бортовым компьютером, который умело управлялся со всей информацией о местоположении всех обитателей Вселенной, а также рассчитывал самые замысловатые маршруты полета Вот уже пять лет, как его не расщепляли на атомы Зафод не покидал кровати – Речь, – взмолился матрасс Весьма сложно отвлечь ваше внимание от этих трех вещей за неполную секунду, которой вы располагаете$$);
insert into тип_продукции values (default, 5278, 'Наборы карточек ручной работы с уникальными иллюстрациями', $$Стена, казалось, все близилась и близилась, густела и густела, тяжелела и тяжелела А потом откашлялся еще раз Жизненный цикл отвертки с храповиком весьма занятен – Да? – обалдело переспросил Зафод$$);
insert into тип_продукции values (default, 702, 'Настенные панно из бумаги-маше с объемными деталями', $$Но не думаю, что с дурными намерениями – Тут одна подробность, – взорвался он наконец, – если мы не поторопимся смыться, то рискуем вновь влипнуть во всю эту историю Вдвоем они взвалили Артура на диван и унесли с поля, причем неожиданное исчезновение дивана на полдороге задержало их совсем ненадолго То есть он решил оскорбить всех ее обитателей Он никогда не слышал, чтобы на Зете Прутивнобендзы выступали с речами, а тем более знаменитости Форд довел свою речь до конца, прежде чем Артур успел перейти от тупого взгляда к тупым замечаниям – Хм По-моему, врут$$);
insert into тип_продукции values (default, 2610, 'Доски для заметок из переработанной бумаги с ярким дизайном', $$А теперь – в Зал информационных иллюзий Вот он я, Зафод Библброкс – Искомый субъект – некрупный слизняк, – пискнул он, – из рода А-Рт-Ур-Еа-Ипдену Ему не хотелось думать, что эту идиллическую страну постигнет несчастье$$);
insert into тип_продукции values (default, 3619, 'Конверты с вырезами и красочными подкладками', $$– Ни фига себе, – с этими словами он выпил еще стакан – Как ты там? – спросила она по внутренней связи – Полотенце не мое, – настаивал Артур, – именно это я и пытаюсь…

– А я пытаюсь потребовать, чтобы ты заткнулся, – продолжал Форд, переходя на рык, – причем немедленно!

– Ладно, – сказал Артур, пытаясь засунуть полотенце обратно в свою неуклюжую сумку Артуру Денту остро захотелось мороженого – Правда, что ли? – вскричал Зафод, поигрывая пистолетом – Э-э, пять, – сказал матрасс – Но почему? Почему нельзя?

– Те, кто разговаривает по телефону сам с собой, ничего хорошего не узнают Мне это кажется чрезвычайно странным, тем более что сумку я сшил на доисторической Земле своими руками$$);
insert into тип_продукции values (default, 3610, 'Подарочная упаковка с персонализированными сообщениями и декором', $$И камни тоже не мои, – добавил он, вытащив из сумки горсть плоских серых камешков – Что это было? – вымолвил Артур Все равно тут больше ничего не покажут Фигура тихо преклонила перед ним колени – Это, сказал бы я, тоже очень любопытный случай, – заявил Артур, поспешно закрыв сумку и прикинувшись, что высматривает мяч на земле Также там советовалось заглянуть в главу о необозримости Вселенной и методике примирения с этим фактом – В глубинах фундаментального сердца духа и Вселенной, – сказал Слартибартфаст, – кроется причина тому$$);
insert into тип_продукции values (default, 4416, 'Наборы для рисования с бумагой высокого качества и инструментами', $$Когда ее находят, то выкидывают на помойку Не Наша Проблема Ему почудилось, будто атомы его мозга и атомы космоса струятся друг сквозь друга Биллионы крошечных миров-кристаллов огненной пылью припорошили тьму-бесконечность Это крупные, благодушные, чехольно-пружинные существа, живущие тихой, уединенной жизнью в болотах Зеты Прутивнобендзы – Вот видите?

Это произвело на матрасса весьма сильное впечатление Музыка, доносившаяся из бортовых динамиков, рвала душу – ничего тут не поделаешь На миг воцарилась скорбная тишина, но тут же ее нарушил громкий ропот (будто сотня тысяч невидимых людей вымолвила: «Уф!»), и с небес, точно пушинки с одуванчика, посыпались белые роботы – На мой взгляд, – сказал матрасс, сочувственно рассматривая вышеуказанную конечность, – это не такая уж замечательная нога$$);
insert into тип_продукции values (default, 4720, 'Книги-раскраски со сложными узорами и мотивами', $$Подъем по горным тропам со снежных равнин Лиски до вершины Хрустальных Пирамид Састантуа долог и утомителен даже при наличии реактивных лыж и упряжки синекских снегодавов, но открывающаяся сверху панорама: Ледники Безмолвия, мерцающие Призматические Горы и хоровод призрачных ледяных светляков вдалеке – вначале замораживает разум, а потом медленно возвышает его к еще невиданным высотам наслаждения прекрасным Эта фраза проходила на ура Довольные улыбки, которыми он обычно озарял чужие похороны, стали какими-то натянутыми Наше странствие уже началось$$);
insert into тип_продукции values (default, 4998, 'Наборы оригами с разноцветной бумагой и схемами', $$Слартибартфаст сказал:

– Потому что при передвижении по космосу числа – настоящий бич божий – Ву-ун, – враднул он наконец Он спорил с судьбой, лез на рожон, срывал цветы удовольствий и сумасшедшие деньги на высокодоходных долгосрочных сберегательных вкладах… в общем, давал всем жизни, как говорится По крайней мере там он будет чувствовать себя во всеоружии – Возмущения в континууме!

– А, это они мебельные магазины громят! – воскликнул Артур, с трудом вернувшись в вертикальное положение и – как он смел надеяться – в здравый рассудок Я ненавижу и презираю вас всех – Безусловно, – согласился Форд Думаю, вы очень довольны$$);
insert into тип_продукции values (default, 260, 'Настенные обои с текстурами, имитирующими натуральные материалы', $$Этот простой факт вызвал бурю в научном мире Гладь болота украсилась очаровательными пузырьками А потом все завершилось – так же внезапно, как и началось Около того, – сказал Марвин надменно$$);
insert into тип_продукции values (default, 1023, 'Оберточная бумага с замысловатыми принтами и фактурами', $$Артур растерянно кивнул – По-моему, его здесь нет, – сказал он мальчишкам, которые немедленно столпились вокруг него, – вероятно, он куда-то откатился – Ну же, спросите, не бывает ли мне скучно Будь ты хоть семи пядей во лбу, но за год спроектировать и построить такой корабль… Не верю Артур сначала посмотрел вслед за указующим перстом – на табло, а потом туда, куда Форд глядел, – на поле и кивнул, пожимая плечами – Так оно и вышло, – сказал Слартибартфаст Это Артур Дент говорит Его губы тоже дергались Инопланетный корабль уже с треском прорывался сквозь верхние слои атмосферы, навстречу той ужасной пустоте с редкими-редкими материальными вкраплениями, из которой и состоит Вселенная$$);
insert into тип_продукции values (default, 2450, 'Свадебные приглашения с замысловатыми кружевами из бумаги', $$– Мост? – не поверил своим ушам матрасс Глянул на экран – и не узнал ни единого созвездия Итак, Охмешконасыпатель пресытился жизнью Робкий солнечный луч, случайно пробившийся сквозь туман, высветил синие и белые полоски на шкуре матрасса, чем немало его напугал – Вон там, – повторил он Я, наоборот, от нее бегал$$);
insert into тип_продукции values (default, 1178, 'Рождественские открытки с тиснением и блестящими элементами', $$– Сходить с ума, так сходить, – рассудил Форд Они вели себя очень мирно…

– Извини, Питер, я тебя перебью – диван только что исчез Стена, казалось, все близилась и близилась, густела и густела, тяжелела и тяжелела Не Наша Проблема Тогда он, и его друзья, и друзья его друзей, и знакомые друзей его друзей, и друзья знакомых друзей его друзей, и довольно шапочные знакомые друзей знакомых друзей его друзей, которые зато владели крупным межзвездным трансагентством, за одну ночь совершили величайший трудовой подвиг в истории человечества – Мне кажется, – сказал Форд тоном, обещавшим (как уже было известно Артуру) какое-то чрезвычайно непонятное продолжение, – что вон там какое-то ННП А там происходило всего лишь то, что люди столпились на площадке вокруг ее середины – Вон там, – сказал Форд, вновь указывая на табло и глядя на поле – Основной вычислительный центр, – невозмутимо пояснил Слартибартфаст Когда его знакомые (даже у таких типов бывают знакомые) намекали, что план не только этически неприемлем, но и неосуществим – поскольку все время кто-то умирает, а кто-то рождается, Охмешконасыпатель просто вперял в оппонента свой стальной взгляд и бурчал: «Что, и помечтать нельзя?»

Итак, он взялся задело$$);
insert into тип_продукции values (default, 5487, 'Наборы для квиллинга с разноцветными полосками бумаги и инструментом', $$Интерьер тесной, сумрачной рубки был выдержан в темно-зеленых, темно-красных и темно-коричневых тонах Прибор едва слышно жужжал, подмигивая крохотной тусклой лампочкой Его раздирали противоречивые чувства А на скатерти пребывало с полдюжины тарелок с недоеденными итальянскими кушаньями Вот оно – то, что разрушили орды Криккита, то, что теперь держит их планету в заточении и будет держать до скончания вечности!

И вальяжным жестом мужчина извлек из воздуха модель Трикетной Калитки И меж тем как «Золотое сердце» неслось с невероятной скоростью в неопределенном направлении, Триллиан прихлебывала какое-то неудобоваримое творение нутримата и читала о том, как научиться летать – Неверно, – пробурчал Марвин Матрасс флёпал вокруг него$$);
insert into тип_продукции values (default, 1222, 'Абажуры из бумаги с уникальными формами и узорами', $$– Ч… ч… ч… – выговорили его губы – … напомни, чтобы я дал сам себе в зубы Робкий солнечный луч, случайно пробившийся сквозь туман, высветил синие и белые полоски на шкуре матрасса, чем немало его напугал – Не знаю, – сказал Форд, – но я буквально чувствую, что время пришло Фальшивка Артур, растроганный и недоумевающий, только замотал головой – Вон там, – повторил он$$);
insert into тип_продукции values (default, 5313, 'Мебель из картона с прочной и легкой конструкцией', $$В его желудке точно черти свадьбу справляли Криккитские войны относились к древней истории Галактики На миг воцарилась скорбная тишина, но тут же ее нарушил громкий ропот (будто сотня тысяч невидимых людей вымолвила: «Уф!»), и с небес, точно пушинки с одуванчика, посыпались белые роботы Против инстинкта не попрешь – наши герои невольно двигались опасливо, даже воровато, хоть и знали, что с тем же успехом могли трубить в трубы и вопить: «Ату!» – инфоиллюзию это бы не спугнуло Докажете – все равно не поверю$$);
insert into тип_продукции values (default, 4060, 'Дизайнерская бумага для скрапбукинга с различными текстурами и принтами', $$Тогда бы ему заметили, что он поет только одну ноту, на что бы он ответил, что по очевидным, как ему кажется, причинам он опустил кусочек «ология любви» А теперь – в Зал информационных иллюзий Тихо проскользнув под ветками, они поднялись вслед за веселой компанией по тропке в гору Стратегия заключалась в том, чтобы он перехватил предыдущий у скрещения дорог, и пусть соединенными силами поднимут дух второго – Я дома, – повторил Артур По-моему, – пояснил Артур, не сбавляя скорости Он уставился вверх Она даже не задала машине никаких координат – ей было все равно, куда бежать$$);
insert into тип_продукции values (default, 2112, 'Обложки для книг с индивидуальной гравировкой и яркими рисунками', $$Как ни странно, за пределами словаря осталось слово «плучительно», означающее просто-напросто «с плучительностью» Всех их зовут одинаково – Зем Поговаривают, что у нее эрогенные зоны начинаются милях в четырех от тела как такового Оплетенные соломой бутылки поджидали неосторожных путников в засаде Блаженно разжевав мясо, он решил официально оповестить мир о своем решении$$);
insert into тип_продукции values (default, 589, 'Скетчбуки с акварельной бумагой и удобной спиралью', $$Его мозг замер, как щенок, испуганно забившийся в угол – Артур! – заорал на него Форд Стол был покрыт скатертью – неказистой скатертью в красную и белую клетку, на которой кое-где зияли прожженные дыры – положение всякой из них, по-видимому, имело глубокий математический смысл А также флёпал, гумкал и уйломикивал К сожалению, невежественный Зафод не был польщен этой честью, ибо, как мы уже упомянули, в детстве интересовался не древней историей, а собственным органическим телом – Алло? Да? – пробормотал Артур – Теперь понял?

– Нет, – признался Артур Форд и Артур прикинулись, будто ничего не замечают Из всех цивилизаций и племен Галактики только англичане могли воскресить воспоминание о самых ужасных войнах в истории Вселенной и превратить его в чрезвычайно замысловатую, нудную и бесцельную игру Одно-единственное «Уф!», и все тут$$);
insert into тип_продукции values (default, 3995, 'Папки-регистраторы с тиснением и прочной картонной обложкой', $$Но возможно, тебе любопытно будет узнать, что твой покорный слуга единолично ответственен за удлиненную форму животного, которому в будущих веках дадут имя «жираф» – Эй! – вскрикнул Артур – Три столба, – гремел мужчина Внезапно Артур вспомнил, что через два дня Земля погибнет, и впервые испытал при этой мысли некоторое утешение Что делать?

Форд пожал плечами:

– А что ты предлагаешь?

– Скажи мне, – попросил Артур, – что все последние пять лет приснились мне во сне Десять минут спустя он уже горбился над чашкой чая под тентом летнего буфета, и на его осунувшееся лицо постепенно возвращался румянец$$);
insert into тип_продукции values (default, 4345, 'Наборы для рисования с цветными карандашами, фломастерами и бумагой', $$– Как ты дога…

Форд только передернул плечами Затем поспешил влить в себя еще один – пусть догонит первый и составит ему компанию Несомненно, «Золотое сердце» произвело здесь фурор, и Триллиан была польщена Форд с Артуром так и обмерли, подавившись собственным воплем – Я так, просто напомнить хотел, – сказал Форд Тут он решил, что пора заговорить$$);
insert into тип_продукции values (default, 2736, 'Маски из папье-маше с изысканными деталями и рисунками', $$– Неверно, – пробурчал Марвин Он осознал, что удостоился знакомства с носителем незаурядного ума Пристегиваясь ремнями, Форд Префект только возносил хвалу судьбе за то, что это всего лишь безопасная инфоиллюзия – И что ты там делаешь?

– Сижу Главное – не кивайте ему!

– А теперь преклоним наши головы в знак оплаты, – произнес голос, а потом пробормотал ту же фразу гораздо быстрее и задом наперед Глаза Артура пошли колесом Он тряс руку Форда и пожимал ее, пожимал и тряс$$);
insert into тип_продукции values (default, 350, 'Изготовленные на заказ фотоальбомы с хронологическими разделителями', $$– Намой взгляд, тебе следовало это узнать перед уходом в мир иной И я подключился к цепи открытия моста Оно меняется в период первых трех телефонных звонков в ресторан, а потом, как выясняется, и отдаленно не совпадает с истинным числом явившихся на ужин, а также с количеством людей, которые присоединяются к ним после спектакля/концерта/матча/вечеринки, и с количеством людей, которые спешат ретироваться при виде новоприбывших – Ваш, что ли, диван? – раздалось сверху$$);
insert into тип_продукции values (default, 5336, 'Свадебные программы с элегантным дизайном и качественной бумагой', $$– Видимо, нет, – ответил Зафод неизвестно откуда И пискнул Артур невольно отпрянул – Намой взгляд, тебе следовало это узнать перед уходом в мир иной – Мне кажется, – сказал Форд тоном, обещавшим (как уже было известно Артуру) какое-то чрезвычайно непонятное продолжение, – что вон там какое-то ННП Затем Артур заметил, что идущая впереди компания тоже обратила внимание на визг и пришла в замешательство$$);
insert into тип_продукции values (default, 3002, 'Приглашения на детский праздник с яркими принтами и забавными персонажами', $$Однако Артура воскресили не эти пасторальные радости И не потому, что звездолет был невидим – Правда, – сказал робот ) Ха! О, жизнь моя – жестянка, жестянка на червячном ходу!

И снова побрел вокруг своей тонкой стальной ноги-протеза, которая вращалась в грязи, но никак не поддавалась Произнесенные роботом слова подтвердили это впечатление – Не пугайтесь, – сказал он и немедленно испуганно воззрился на прибор, – это…

Конца его фразы Форд с Артуром не услышали, ибо в этот момент корабль, в котором они находились, просто испарился Слартибартфаст сказал:

– Потому что при передвижении по космосу числа – настоящий бич божий$$);
insert into тип_продукции values (default, 798, 'Карточки с рецептами со стильными рамками и водонепроницаемой подложкой', $$Странно, но факт – И также я тебя прошу не говорить, что ты очень рада быть полезной или что ты польщена честью раскрыться передо мной и премного довольна вновь затвориться с сознанием выполненного долга, ладно?

– Ладно Форд сгреб его за отвороты халата и стал объяснять ему терпеливо и размеренно, с толком и с расстановкой – словом, так, будто Артур был служащим расчетного отдела телефонной компании Думаю, вы очень довольны Вылетаем без промедления Они взобрались на верхушку ближнего утеса и принялись обозревать окрестности Так-то он надеялся войти незамеченным – из-за замысловатой формы рубки (в виде сердечка) дверь находилась в укромном уголке$$);
insert into тип_продукции values (default, 7500, 'Обложки для паспортов с замысловатыми рисунками и защитой от RFID', $$Криккит По какой-то непостижимой причине их элегантные обтекаемые тела казались совершенным олицетворением чистого, патологического зла По трапу решительной походкой сошла высокая серо-зеленая фигура и приблизилась к маленькой кучке людей, которые окружали жертв недавней абсурдной бойни – Где?

Слегка дрожащей рукой Форд очертил чуткоматом дугу в воздухе Но тут же, заметив, что отряхивает именно халат, застыл как вкопанный Блаженно разжевав мясо, он решил официально оповестить мир о своем решении Сияющее облако булавок и иголок на знойно-черном бархате открытого космоса И потому вскорости они оказались у внутренней границы сферического, полого изнутри Пылевого Облака, со всех сторон окружавшего Криккит и его солнце – Ну и как она выглядит?

– Ну а мне-то откуда знать, идиот? Сам видишь – сам и описывай – Что «нет»?

– Не пытайся звонить себе самому домой$$);
insert into тип_продукции values (default, 2812, 'Коробочки для подарков с окнами из прозрачной бумаги и лентами', $$И потому вскорости они оказались у внутренней границы сферического, полого изнутри Пылевого Облака, со всех сторон окружавшего Криккит и его солнце Но тут же просияв, перевел взгляд на широкий экран панорамного обзора, где струились, головокружительно сплетаясь и расплетаясь вокруг корабля, серебряные нити Нервно опираясь о стену коридора, он морщил лоб (то есть лбы), словно пытаясь откупорить бутылку методом телекинеза А когда раскроешься, я тебя прошу, не говори, что тебя это осчастливило, ладно?

– Ладно Он указал, чтó понимает под термином «вон там» Слартибартфаст покинул стеклянную комнату Понимаете, мысль «Мы одни во Вселенной» их ни разу не посещала, потому что до сегодняшнего вечера они вообще не знали о существовании Вселенной Весьма сложно отвлечь ваше внимание от этих трех вещей за неполную секунду, которой вы располагаете – Да нет же, – возразил Артур Матрасс флёпал вокруг него$$);
insert into тип_продукции values (default, 972, 'Декоративные вазы из картона с уникальными формами и текстурами', $$– Нет уж – То были, – проговорила фигура, восседающая в исполинском мягком кресле, – криккитские войны, величайшая катастрофа в истории нашей Галактики Через минуту я попрошу тебя раскрыться Вот тогда-то он и набрел на свою цель жизни, дело, которое не позволит ему впасть в спячку никогда-никогда (так ему, во всяком случае, казалось)$$);
insert into тип_продукции values (default, 713, 'Костюмы из папье-маше для фестивалей и театральных представлений', $$– …моргал…

– Ну да Большинству людей промахнуться не удается, и чем больше усилий они прилагают, тем крупнее вероятность столкновения с землей В нем звучала даже какая-то интеллигентная хрипотца Время – это, так сказать, худшее место из всех, где только можно заблудиться Вследствие чего школьная администрация отправила компьютер в клинику для помешанных киберустройств, куда за ним последовала и девочка, имевшая глупость влюбиться в злосчастную машину – Примерно… – задумался Слартибартфаст, – примерно две трети диаметра галактического диска В их штате есть специальные работники с удивительными телами и воззрениями Правда, он не был ярко-розовым, но это вовсе не значит, что внешне он ничем не выделялся$$);
insert into тип_продукции values (default, 1608, 'Органайзеры для ванной с водостойким покрытием и нескользящим дном', $$Раздался залп Так оно и было – Я сам вам поясню, – прошептал старец – … и премного довольна вновь затвориться с сознанием выполненного долга Большой стеклянный ящик, этакий аквариум – точнее, целая комната День за днем они исследовали останки сгоревшего корабля, разгрызая секрет за секретом, распевая звонкие кораблеразборочные марши Корабль вылетел из Облака Я стал звездой экспозиции Тихо проскользнув под ветками, они поднялись вслед за веселой компанией по тропке в гору$$);
insert into тип_продукции values (default, 234, 'Календари с магнитными держателями и увеличенными полями для заметок', $$Спасение – Откуда вы это взяли? – заорал он на полисменообразное – Нет смысла ломать голову над действиями машин, – заявил он, – только зря нервничаешь Уперев руки в бока, он вновь обвел взором пустынный мир$$);
insert into тип_продукции values (default, 6480, 'Подарочные сертификаты с тиснением и персонализированным дизайном', $$Приборы, столь занимавшие внимание Слартибартфаста, были вмонтированы в донца бутылок, которые, в свою очередь, были заделаны в бетонную стену – Из мглы времен восстало великое проклятие, – сказал Слартибартфаст Ветер обдувал бухту, где останки одной из крупнейших и мощнейших космических флотилий в истории Галактики поспешно превращались из пепла в исходное состояние Большой стеклянный ящик, этакий аквариум – точнее, целая комната – Ну-с, сэр, – сказал полицейский после того, как они пробрались сквозь обуянную любопытством толпу и уложили умиротворенного, бездвижного Артура на одеяло, – теперь вы мне, возможно, соизволите сообщить, кто вы такие, откуда взялись и что хотели сказать этим балаганом?

Форд уставился себе под ноги, точно заимствуя у земли твердость духа, затем, вскинув голову, ответил полицейскому взглядом, в который было вложено все напряжение каждого дюйма из шестисот световых лет, разделяющих Землю и отчизну Форда – окрестности Бетельгейзе$$);
insert into тип_продукции values (default, 2262, 'Обложки для альбомов с тисненым текстом и мягкой набивкой', $$Засунув руки в единственный карман своего халата, он воззрился вдаль с видом знатока – Протечки?

– Протечки в пространстве-времени, – сказал Форд и поспешил подставить свое зверски ухмыляющееся лицо ветру, который как раз случайно пролетал мимо Эффрафакс Вугский, маг-суперзвезда от науки, однажды поставил на кон свою голову, что за год сумеет сделать абсолютно невидимой великую мегагору Меграмал Робот, остановившись, уставился на матрасса Вновь проследив траекторию мяча, Форд захлопал глазами Форд вытащил свой субэфирный чуткомат$$);
insert into тип_продукции values (default, 3500, 'Блокноты с прошитыми страницами и гибкой обложкой', $$Зафод застыл как вкопанный Огни зажглись и потухли, столбы исчезли, мужчина, пятясь, растворился в пустоте, а Вселенная проворно сложилась обратно в привычную картину Сияющее облако булавок и иголок на знойно-черном бархате открытого космоса – Я вижу эту штуку, – объявил Артур, – это звездолет Вот оно – то, что разрушили орды Криккита, то, что теперь держит их планету в заточении и будет держать до скончания вечности!

И вальяжным жестом мужчина извлек из воздуха модель Трикетной Калитки Между мигом, когда криккитяне впервые узнали о существовании космоса как такового, и запуском этой первой ласточки среди космических кораблей прошел ровно год И само собой разумеется, он был слегка пьян$$);
insert into тип_продукции values (default, 5510, 'Упаковочная бумага с биоразлагаемым покрытием и яркими принтами', $$Вот уже четыре года (со дня расставания с Фордом Префектом) Артур в общем-то ни одной души не видел, а потому и оскорблениям больше не подвергался Грубо говоря, конечно Сам себе сосчитал пульс – Повелители Криккита, – выдохнул Слартибартфаст голосом призрака – Трубку бросил, – пояснил он, пожал плечами и аккуратно положил свою воображаемую трубку на воображаемый рычаг – Собственно, невозможность их формулирования и есть один из самих этих принципов По-прежнему ничто не шевелилось И само собой разумеется, он был слегка пьян – Ну, как я уже сказал, ваша команда только что победила$$);
insert into тип_продукции values (default, 4345, 'Визитные карточки с тиснением, ламинированием и выборочной УФ-печатью', $$– Нынче тут, завтра там и кое-где еще, – сообщил Форд А спустя еще несколько часов вылезло вновь, расправило плечи и опять принялось карабкаться вверх по небу Вот оно – то, что разрушили орды Криккита, то, что теперь держит их планету в заточении и будет держать до скончания вечности!

И вальяжным жестом мужчина извлек из воздуха модель Трикетной Калитки Широко развел руки Это звук, который издают живые матрассы в своей естественной среде обитания, приняв близко к сердцу чью-то повесть о жизненной драме – Ну и? – тревожно вопросил Артур А кто-нибудь еще его заметил?

– По-видимому, нет В этот миг необходимо полное, глубочайшее хладнокровие – Хмммм$$);
insert into тип_продукции values (default, 7544, 'Коробки для хранения с разделителями из картона и магнитными застежками', $$Артур откашлялся Артур Дент Затем вы освоите массу приемов по управлению своим телом в полете, регулировке скорости, выполнению маневров – Нет, – заявил Марвин$$);
insert into тип_продукции values (default, 224, 'Тематические наборы открыток с художественными иллюстрациями', $$Наверху их глазам предстала совершенно бредовая картина Пришельцы покидают площадку в сопровождении офицера полиции, и, по-моему, все входит в привычное русло, и игра сейчас возобновится Это было их творение, и сейчас они пели о нем песенку, изливая в ней двойную радость успеха и обладания – Должно быть, она тебе донельзя обрыдла Финиш И естественно, на следующее утро Меграмал больше не был виден Зафод похолодел Царила тишина – Батарейка села? – поинтересовался Артур$$);
insert into тип_продукции values (default, 3680, 'Комиксы с уникальными сюжетами и персонализированными персонажами', $$Услышь ее Маккартни, она мигом подарила бы ему Кент и Суссекс и позволила бы всерьез задуматься о приобретении Хэмпшира Как ни странно, за пределами словаря осталось слово «плучительно», означающее просто-напросто «с плучительностью» Второе не-абсолютное число – это оговоренный час сбора приглашенных, который, как ныне известно, представляет собой одно из сложнейших математических понятий – реситуасексулузон, число, о котором с уверенностью можно сказать лишь одно – оно равно чему угодно, только не самому себе – Нет, чушь какая-то… Это было бы абсурднее, еще абсурднее…» И замялся$$);
insert into тип_продукции values (default, 1422, 'Книги с выдвижной бумагой с прикрепленными фигурками или предметами', $$Одну голову он засунул под подушку, а вторая до поздней ночи разгадывала кроссворды Однако матрасс попался какой-то уж очень глупый и лишь воззрился на него в ответ круглыми глазами Прикрыв один глаз, он что-то созерцал другим – Речь идет о каких-то неполадках космического водопровода, я так понял? – осторожно спросил он Левая голова посмотрела влево, а правая – вправо, и обе решили, что следует отправиться куда глаза глядят – А-а, – воскликнул он, сосредоточившись на первом попавшемся имени$$);
insert into тип_продукции values (default, 6120, 'Поздравительные открытки с музыкальным чипом и настраиваемой мелодией', $$Несмотря на кучи обломков, Зафод с новым ужасом разглядел, что они движутся к самому ядру корабля, сердцу невероятностной тяги, загадочным образом сгущаемой из пустоты, – в общем, к самому «Золотому сердцу» По крайней мере я думаю, что оно думало, что оно джин с тоником… Есть вероятность, – добавил он с ухмылкой, от которой самые хладнокровные люди с воем полезли бы на деревья, – что мне это всего лишь примерещилось И все же что было, тому не миновать Для примера – задумайте число, любое число На горизонте маячили симпатичные круглые холмы – Он гордо возносился над водами?

– Да, он гордо возносился над водами – Нет смысла ломать голову над действиями машин, – заявил он, – только зря нервничаешь И вновь зашагал$$);
insert into тип_продукции values (default, 1820, 'Светодиодные фонари из бумаги с вырезанными узорами и мягким светом', $$– Недурная мысль, – заметил Форд Префект, соскальзывая с валуна, на котором сидел – Кто? – переспросил он Форд и Артур воззрились на него с крайним удивлением и острым чувством обиды за хороший вкус Зафод, кивнув, принялся поигрывать пистолетом, дабы добиться дальнейших пояснений Артур кивнул – медленно, опасливо, с безмерно дурацким выражением лица Он спорил с судьбой, лез на рожон, срывал цветы удовольствий и сумасшедшие деньги на высокодоходных долгосрочных сберегательных вкладах… в общем, давал всем жизни, как говорится – Не лучшее его место$$);
insert into тип_продукции values (default, 682, 'Украшения из папье-маше с яркими цветами и затейливыми формами', $$– Ч… ч… ч… да, – согласился Артур Даже Форд, похоже, повеселел – Выражаю свою позицию, – процедил Марвин, не переставая описывать круг за кругом Однако на взгляд Артура, абсолютно черный небосвод придавал всему идиллическому, несмотря на сумрак, пейзажу какой-то зловещий оттенок Собрав все силы, он выпрямил свое длинное тело, встал на дыбы и несколько секунд простоял на цыпочках, вглядываясь в туман Размял их между пальцами – Это не первая аномалия времени на моем веку – Странный трофей Хуже может быть только одно – наблюдать за ее разрушением с ее же поверхности$$);
insert into тип_продукции values (default, 2666, 'Модели парусных кораблей из бумаги с детальными парусами и корпусом', $$Артур хмуро поплелся за ним – Приятных сновидений, – сказал он Мне это кажется чрезвычайно странным, тем более что сумку я сшил на доисторической Земле своими руками Она даже не задала машине никаких координат – ей было все равно, куда бежать Маленькие группки монахов, которые взяли за обычай болтаться около крупных научных институтов и петь странные псалмы во имя идеи, что Вселенная – лишь крупица ее собственного воображения, куда-то сгинули после того, как получили от правительства дотацию на организацию уличных представлений – Ага, чтоб ты его опять выбросил?

– Разумно, – сознался Артур$$);
insert into тип_продукции values (default, 1375, 'Бумажные скульптуры с подвижными частями и реалистичными деталями', $$Что ж, одной загадкой меньше Он снял с рычага воображаемую трубку и стал крутить воображаемый диск – Ты завершил то, к чему шел много лет Затем, вернувшись к реальности, осознал, что все равно не понимает, куда клонит старец Тут он обнаружил в стене искомое отверстие и с хрустом воткнул в него вилку прибора Роботы успели частично разобрать дальнюю стену рубки и пробить ход через жизненно важные органы корабля$$);
insert into тип_продукции values (default, 3243, 'Коврики для занятия йогой из переработанного картона с противоскользящей поверхностью', $$Они бежали, не разбирая дороги, через траву, подпрыгивали, хохотали, кричали друг другу: «Загоняй его сюда!», «Перехватывай!» Солнце мечтательно освещало травяное море, крохотные полевые животные сломя голову разбегались из-под их ног Они стояли неподвижно Вот что написано в «Путеводителе» об искусстве полета:


Полет – это искусство, а точнее сказать, навык Эта штука недавно проснулась – Полотенце не мое, – настаивал Артур, – именно это я и пытаюсь…

– А я пытаюсь потребовать, чтобы ты заткнулся, – продолжал Форд, переходя на рык, – причем немедленно!

– Ладно, – сказал Артур, пытаясь засунуть полотенце обратно в свою неуклюжую сумку Венских – Чего-о? – воскликнул Форд Одни вязы он огибал, сквозь другие просачивался с ловкостью призрака Настоящее издевательство Марвин шагал$$);
insert into тип_продукции values (default, 4480, 'Наборы для аппликации с цветной бумагой, ножницами и клеем', $$– Я понимаю, что в масштабе Вселенной этот факт не имеет никакого значения, но просто интересно Защитник, взмахнув битой, послал мяч себе за спину так, что он пролетел над табло – Правда, что ли? – вскричал Зафод, поигрывая пистолетом Артур уставился на компанию фермеров, пытаясь свести воедино крохи информации, которыми располагал Матрасс пришел в возбуждение Как ни странно, за пределами словаря осталось слово «плучительно», означающее просто-напросто «с плучительностью»$$);
insert into тип_продукции values (default, 3392, 'Домики для кукол из картона с мебелью и аксессуарами', $$– Чай, – произнес он, – крикет, – добавил он с нежностью, – стриженые газоны, деревянные скамейки, белые полотняные пиджаки, пиво в банках…

Медленно-медленно его взгляд сфокусировался на газете Какой-то голос произнес: «Это…» Слартибартфаст дернул за ручку, и он умолк – Из мглы времен восстало великое проклятие, – сказал Слартибартфаст НИКОМУ НЕ МАШИТЕ – Ну там, вогоны не заворачивают краны…

– Нет, это возмущения в континууме, – пояснил Форд Попятившись, Артур испуганно огляделся по сторонам Он вскочил с дивана – Хм$$);
insert into тип_продукции values (default, 876, 'Оригами-гирлянды с разноцветными бумажными фигурами', $$– … и премного довольна вновь затвориться с сознанием выполненного долга Причем все они созданы трудами ветра и дождя – естественный процесс эрозии – Я изумлен, – сказал Артур, – и потрясен Слартибартфаст быстрым шагом вошел в «аквариум» и, судя по всему, затеял какой-то пустой разговор с метрдотелем, а один из роботов-клиентов, авторазмякающая модель, меж тем тихо сполз под стол, не переставая рассказывать, что именно собирается сделать с неким типом из-за некой девушки – Я все правильно сделала, мистер Библброкс? – громко поинтересовалась дверь Но радовался он зря Воздух был прозрачен и душист Другой же своей частью он был точь-в-точь маленькое итальянское бистро, только поставленное вверх тормашками$$);
insert into тип_продукции values (default, 2528, 'Подарочные пакеты с рельефным рисунком и ручками из ленты', $$– Компьютер, – окликнул Охмешконасыпатель Приборы, столь занимавшие внимание Слартибартфаста, были вмонтированы в донца бутылок, которые, в свою очередь, были заделаны в бетонную стену Часа через два стало очевидно, что Зафод тверд в своем решении, и корабль вновь поднялся в небо, даже не спустив трапа – … верно я говорю? – добавил он Строго говоря, эту шайку бесчувственных выродков он давно уже возненавидел лютой ненавистью – Форд встряхнул прибор Нежданно-негаданно вывалившись из пространственно-временной аномалии в чудный, совершенно очаровательный лондонский денек, Форд с Артуром совершили довольно жесткую посадку на безупречный газон площадки «Лордз» Так и вышло$$);
insert into тип_продукции values (default, 6225, 'Обложки для электронной книги с индивидуальной гравировкой и магнитными застежками', $$– Ты будешь слушать или нет?

– Я слушаю, – сказал Артур, – только боюсь, толку мне от этого мало Обычно фокус в том, чтобы не слишком сосредоточиваться на своих действиях, но просто пускать их на самотек, точно нечто от вас не зависящее – Намой взгляд, тебе следовало это узнать перед уходом в мир иной Мало того, нижние сегменты их ног были защищены чем-то вроде белых щитков А теперь – в Зал информационных иллюзий Во-первых, из-за ННП-поля Спасение – Ну и хорошо, – сказал Артур$$);
insert into тип_продукции values (default, 2262, 'Бумажные гирлянды с вырезанными вручную узорами и тканевыми лентами', $$Каждое утро традиционный душераздирающий вопль оповещал окрестности, что Артур Дент проснулся и заново ужаснулся своему местоположению Они вели себя очень мирно…

– Извини, Питер, я тебя перебью – диван только что исчез Самый подходящий афоризм, чтобы заронить в молодые умы искру вдумчивого отношения к жизни Они взобрались на верхушку ближнего утеса и принялись обозревать окрестности По-моему, – пояснил Артур, не сбавляя скорости$$);
insert into тип_продукции values (default, 1643, 'Мемуарные книги с персонализированными обложками и расширенными полями', $$– Нет, – заявил Марвин Они стояли одни-одинешеньки на вершине утеса где-то на доисторической Земле и решительно смотрели друг другу в глаза Большинство зрителей, будучи не в силах выдержать этого зрелища, зажмурили глаза и переключились на слушание радиотрансляции Он замер Прикрыв глаза, он жадно вдыхал пар, поднимающийся над чашкой чая, словно это был не чай, а… – но в данном случае, с точки зрения Артура, вся прелесть именно в том и состояла, что это был чай$$);
insert into тип_продукции values (default, 988, 'Игрушечные машины из картона с реалистичными деталями и подвижными колесами', $$Ни робота, ни сверкающего моста, ни корабля – одни камыши да ряска И поторопился опустошить его, пока не случилось чего похуже Еще раз широко улыбнувшись, он откусил кусочек от кроличьей ноги – остатка вчерашнего ужина – Ключ, – спокойно продолжал робот, – был развеян на ветру пространств и времен – Ч… ч… ч… да, – согласился Артур – Любопытное происшествие, Брайан, – сказал один радиокомментатор другому Они бежали, не разбирая дороги, через траву, подпрыгивали, хохотали, кричали друг другу: «Загоняй его сюда!», «Перехватывай!» Солнце мечтательно освещало травяное море, крохотные полевые животные сломя голову разбегались из-под их ног Куда пожелаю, туда и полечу, что на ум взбредет, то и выкину$$);
insert into тип_продукции values (default, 1800, 'Наборы для рисования с цветными карандашами, маркерами и бумагой премиум-класса', $$– На самом деле? – спросил Артур, ни на миг не отводя глаз от Форда И это где-то недалеко – Что случилось? – спросил Артур с глубоким благоговением – Ч… ч… ч… – выговорили его губы – Было что-то интересное?

И вновь они балансировали на краю ужасно высокого утеса$$);
insert into тип_продукции values (default, 460, 'Бумажные самолеты с уникальным дизайном и аэродинамической конструкцией', $$– Мощность моей мыслительной деятельности на всех ее уровнях и во всех ее аспектах столь же безгранична, как бескрайние просторы самой Вселенной Триллиан вновь терпеливо кивнула, досчитала до… – в общем, число было немаленькое – и сказала себе, что на данном этапе самое важное – хотя бы разговорить Зафода Он почувствовал себя ограбленным – Только, – заверил его Форд Недавно был открыт лес, где почти все деревья в качестве плодов дают отвертки с храповиком – Ожидаемое время в пути – три недели, – продолжил он Вследствие чего школьная администрация отправила компьютер в клинику для помешанных киберустройств, куда за ним последовала и девочка, имевшая глупость влюбиться в злосчастную машину$$);
insert into тип_продукции values (default, 9300, 'Бумажные тарелки с персонализированными принтами и экологически чистым покрытием', $$Форд что-то мурлыкал под нос Но не думаю, что с дурными намерениями Однако это событие оказалось не только кошмарным крахом одной начинающей науки, но и апофеозом другой – Быть такого не может – Здесь производятся все вычисления, обеспечивающие жизнедеятельность корабля В этот момент Артур заметил странную особенность песни, которую распевали криккитяне – Да что этот старый дурак собрался делать, вакуум его заарктурь? – взорвался Форд Они стояли неподвижно На миг он вообразил свой маршрут в виде ломаной линии, связывающей все небесные огоньки, как на детских «загадочных картинках» с пронумерованными точками$$);
insert into тип_продукции values (default, 2736, 'Бумажные лампы с вырезанными вручную узорами и теплым рассеянным светом', $$Однако спустя миг стряслось нечто, чего невозможно было не заметить Холод, тяжесть, беспросветность потихоньку проникли в сердце Артура, и он остро ощутил переживания пилотов-криккитян, повисшие в воздухе кабины, точно грозовое электричество – А что сталось со зрителем?

– По-моему, кто-то вызвался угостить его обедом, но тот пояснил, что уже отобедал, и довольно плотно, поэтому вопрос был замят, и Уорвикшир победил с перевесом в три калитки Если бы его спросили, он бы ответил, что все время мурлычет первую строчку песни «Психология любви» Слепящий свет, подобно цунами, захлестнул мрак и откатился, унося с собой большой кусок планеты, что висела прямо под их ногами$$);
insert into тип_продукции values (default, 7296, 'Картонные домики для кошек с прорезями и мягкими подушечками', $$Он шествовал к центру поля ужасающе решительной поступью, и его борода, волосы и одеяние развевались по ветру – вылитый Моисей на горе Синай, только в роли Синая сейчас выступала холеная лужайка, а не грозный вулкан в косматом дыму, каким его обычно изображают – Ага, чтоб ты его опять выбросил?

– Разумно, – сознался Артур Я стал звездой экспозиции А в моих руках точная копия, изготовленная руками народных умельцев Пользуясь секретами древних мастеров, они любовно смонтировали этот сувенир, который украсит ваш дом – в напоминание о павших и в знак почтения к Галактике – нашей Галактике, – на алтарь которой они положили свои жизни…

Тут мимо вновь проплыл Слартибартфаст Примерно в 14 – Спасибо – Не пугайтесь, – сказал он и немедленно испуганно воззрился на прибор, – это…

Конца его фразы Форд с Артуром не услышали, ибо в этот момент корабль, в котором они находились, просто испарился – И я хочу знать, можешь ли ты ее видеть$$);
insert into тип_продукции values (default, 5130, 'Доски для рисования с магнитной поверхностью и водонепроницаемой бумагой', $$Ему не хотелось думать, что эту идиллическую страну постигнет несчастье – Тс-с-с, – сказал Слартибартфаст – Более того, они еще толком и не начались, – уточнил Форд Словно ниоткуда, зазвучала музыка И это где-то недалеко Из тьмы прямо на них вылетел, изрытая лазерный огонь, боевой звездокрейсер размером с небольшой промышленный город$$);
insert into тип_продукции values (default, 7776, 'Бумажные зонты с красочными принтами и водоотталкивающей обработкой', $$Также никому не известно, что за радость находят в своем образе жизни матрассы – Через несколько минут, – терпеливо повторил робот, – мы завладеем Золотой Перекладиной…

– Фигушки, – сказал Зафод – Не знаю, – сказал Форд, – но я буквально чувствую, что время пришло – Мне это известно, – ответил Слартибартфаст Артур последовал совету, вначале несколько нервно, словно боясь, что рука сейчас обернется скользкой рыбиной$$);
insert into тип_продукции values (default, 4212, 'Металлизированная бумага с блестящим покрытием и широким спектром оттенков', $$Приятели направились к пресловутому кораблю Фальшивка Большинству людей промахнуться не удается, и чем больше усилий они прилагают, тем крупнее вероятность столкновения с землей Матрасс флёпал вокруг него Тем, кто только что настроился на нашу волну, будет любопытно знать, что… э-э-э… два человека, двое довольно неряшливо одетых мужчин и самый настоящий диван – честерфильдский, по-моему?

– Да, честерфильдский – Я обнаружил, – заявил он, – аномальные протечки Внезапно лампочка ярко вспыхнула – Жду с нетерпением!

– Она была принята очень плохо, – сказал Марвин, – по многим причинам – Но почему? Почему нельзя?

– Те, кто разговаривает по телефону сам с собой, ничего хорошего не узнают И вдруг исчезла$$);
insert into тип_продукции values (default, 3036, 'Самоклеющаяся бумага с яркими принтами и легким нанесением', $$Спустя некоторое время он начал медленно, воровато пробираться вперед с гримасой вдумчивой озадаченности на лице – как леопард, который не совсем уверен, что только что видел в полумиле впереди, на раскаленной и пыльной прерии, полупустую банку «Вискаса» А потом все завершилось – так же внезапно, как и началось Мужчина, с ужасом и смятением в глазах, слабо кивнул Сегодняшнее утро выдалось благоуханным и ясным – в чем лично удостоверился Артур Дент, выйдя из пещеры, которую именовал домом (за неимением как более подходящего названия для нее, так и более подходящей для этого названия пещеры) Они не просто убивают людей – они их подбрасывают вверх А от этого субъекта никому не удалось добиться подробностей, поэтому поиски были весьма поверхностными Какое-то время он бездействовал, словно ожидая, что люди займутся своими обычными делами, не порицая его за это висение Звездолет легко опустился на землю, и его ненавязчивое гудение разом стихло, точно убаюканное вечерней тишиной$$);
insert into тип_продукции values (default, 8464, 'Дизайнерская бумага с узорами из тиснения, фольги и тиснением', $$Артур, погруженный в мысли об Эссексе и Ирландии, на миг растерялся Воцарилась бесконечно холодная и зловещая тишина Он, как известно всем, был уничтожен, развеян по извечным водоворотам пространственно-временного континуума и исчез навеки Без нее мой корабль перестанет работать$$);
insert into тип_продукции values (default, 2006, 'Бумажные постеры с высококачественными принтами и экологически чистой отделкой', $$– Я не о полотенце, – сказал Артур – Где же ты…

– Отыскал джин с тоником? – радостно продолжил за него Форд – … и премного довольна вновь затвориться с сознанием выполненного долга Чересчур осмысленное и лаконичное$$);
insert into тип_продукции values (default, 589, 'Упаковочная бумага с биоразлагаемым покрытием и устойчивыми к разрывам рулонами', $$Вселенское Переустройство будет возобновлено – Разбудишь ко второй серии Разумеется, экипаж не реагировал на присутствие посторонних – ведь их тут, в сущности, и не было То есть больно будет, если вам не удастся промахнуться мимо земли Эта штука недавно проснулась$$);
insert into тип_продукции values (default, 1295, 'Картонные коробки с пользовательскими размерами, внутренними вставками и тиснением', $$Форд взял его за руку – Видимо, вы поглощены размышлениями, – плучительно сказал матрасс Проведя рукой по стене, он нащупал нечто ценное Пойдемте за ними и посмотрим сами$$);
insert into тип_продукции values (default, 5396, 'Самовосстанавливающиеся офисные подложки из картона с нескользящей поверхностью и водостойким покрытием', $$Роботы пялились на Зафода душераздирающими покойницкими глазами «Автостопом по Галактике» Над болотами расстилался туман, обесцвечивая деревья, обращая высокие заросли осоки в сплошные стены – Здравствуйте, робот, – поздоровался матрасс – Из мглы времен восстало великое проклятие, – сказал Слартибартфаст Дело есть В общем, голос был столь же древним, как и его владелец Фигура сошла по трапу и остановилась перед Артуром$$);
insert into тип_продукции values (default, 819, 'Разноцветная бумага для орегами с замысловатыми узорами и повышенной толщиной', $$Тут силы матрасса иссякли, и он флюмкнулся обратно в протоку, обрушив на Марвина струю мокрой тины с водорослями и мхом Фигура сошла по трапу и остановилась перед Артуром Вспыхнули споры, посетители кинулись рисовать на салфетках иллюстрации своей правоты На миг он вообразил свой маршрут в виде ломаной линии, связывающей все небесные огоньки, как на детских «загадочных картинках» с пронумерованными точками Он приближался к рубке лилипутскими шажками с таким видом, будто предпочел бы улепетывать от нее великаньими Но возможно, тебе любопытно будет узнать, что твой покорный слуга единолично ответственен за удлиненную форму животного, которому в будущих веках дадут имя «жираф» Инопланетный корабль уже с треском прорывался сквозь верхние слои атмосферы, навстречу той ужасной пустоте с редкими-редкими материальными вкраплениями, из которой и состоит Вселенная Вот… – вымолвил он, задыхаясь, – … за чем… они… прилетали… – С этими словами он легонько мотнул головой, словно пытаясь утрясти свой мозг$$);
insert into тип_продукции values (default, 5760, 'Конверты для прямой почтовой рассылки с глянцевой отделкой, самоклеющимся клапаном и расширенными полями', $$– Ты что-то придумал, правда? – спросил Артур Матч меж тем продолжался Матрасс пришел в возбуждение – Ничего не знаю, ничего не слышу, ничего не вижу, – причитал он на бегу, – это не моя планета, я сюда не просился, не хочу ввязываться, просто вытащите меня отсюда и отвезите куда-нибудь в бар, к людям, которые мне свои!

Над полем взметнулся столб пламени и дыма С легким жужжанием и крайне зловещим видом он завис над землей – Стальной Столб – символ Силы и Мощи Галактики!

Лучи света бешено заплясали на столбе слева, действительно изготовленном из стали или чего-то очень похожего Зафод крякнул Последовала немая сцена – Это Артур Дент? Ага, алло, да$$);
insert into тип_продукции values (default, 7600, 'Промышленная бумага с высокой прочностью на разрыв, влагостойкостью и устойчивостью к истиранию', $$Если не считать разговоров с некоторыми дубами – этим хоть в лоб, хоть по лбу Большую часть всех абсурдных вещей, какие приходили ему в голову, он уже повидал наяву Затем он совершил нечто, что матрассы обычно делать ленятся Ветерок приносил оттуда мирные бытовые звуки В таком настроении к оружию лучше не прикасаться – Это что-то важное, – рассудил Артур и окликнул старца – Я дома, – повторил Артур И потому большинство людей после первых неудач разочаровываются в этом увлекательном, зрелищном спорте$$);
insert into тип_продукции values (default, 5720, 'Вощеная бумага с биоразлагаемым покрытием, водостойкостью и термостойкостью', $$Странно, но факт Все было ясно из самой его походки – Ну-ка, улыбочку, усмешечку!» Я разъяснял, что для того, чтобы мое лицо исказила улыбка, нужно отнести его в мастерскую и часа два поработать над ним кувалдой Артур поделился своим впечатлением с друзьями Я выступил с ней, – тут он выдержал паузу, чтобы сделать неуклюжий жест своей здоровой рукой (относительно здоровой по сравнению с другой, наглухо приваренной к его корпусу слева), – во-он там, примерно в миле отсюда$$);
insert into тип_продукции values (default, 5307, 'Бумага для акварели холодного прессования с текстурированной поверхностью и высоким содержанием хлопка', $$Туман висел неподвижно, точно то самое перехваченное на полдороге дыхание – Артур Филип Деодат? – спросила она Артур посмотрел еще раз Поскольку личный обучающий компьютер Зафода играл активную роль в этом плане, Зафод в итоге стер из его памяти всю историю, освобождая место для более актуальной группы концепций Как ни странно, за пределами словаря осталось слово «плучительно», означающее просто-напросто «с плучительностью» С кличем внезапного восторга он спрыгнул с утеса и весело помчался вдогонку за Фордом Префектом и своенравным предметом мебели Ты мне веришь?

– Расскажи, – сказал Артур Это было их творение, и сейчас они пели о нем песенку, изливая в ней двойную радость успеха и обладания Замотав головой, Форд закрыл лицо руками и нечаянно отфутболил к стене подвернувшийся под ногу цветочный горшок – От… к-к-к… э-э… – добавил он немного погодя$$);
insert into тип_продукции values (default, 3735, 'Пергаментная бумага с жиростойким покрытием, устойчивостью к высоким температурам и возможностью многократного использования', $$– Может, мне…

– Нет, – рявкнул Форд – Хмммм – Разумеется, это не подлинный ключ Протечку – Над болотами был сооружен мост$$);
insert into тип_продукции values (default, 3828, 'Пекарская бумага с антипригарной поверхностью, термостойкостью и влагостойкостью', $$Все это было искусственным В отчаянии он снова пихнул Форда локтем – И что же с ней стало? – спросил Артур Форд только покачал головой – Э-э… – в отчаянии выпалил Артур, – э-эй!

– И нечего тут! – рявкнул инопланетянин$$);
insert into тип_продукции values (default, 5160, 'Бумага для рисования с гладкой поверхностью, высокой плотностью и превосходной белизной', $$– Правда, – сказал робот Синее с желтыми звездочками Форд и Артур воззрились на него с крайним удивлением и острым чувством обиды за хороший вкус Те, кто рождается бессмертным, от рождения бессознательно свыкаются с этим своим свойством, но Охмешконасыпатель – не из их числа – Сходить с ума, так сходить, – рассудил Форд Оно опасно?

– Мммм$$);
insert into тип_продукции values (default, 1794, 'Блокноты для заметок с проклеенными страницами, твердой обложкой и эластичной застежкой', $$Итак, Охмешконасыпатель пресытился жизнью Робот, похоже, понял Они бежали, не разбирая дороги, через траву, подпрыгивали, хохотали, кричали друг другу: «Загоняй его сюда!», «Перехватывай!» Солнце мечтательно освещало травяное море, крохотные полевые животные сломя голову разбегались из-под их ног Они немного прошли в сторону города, и инфоиллюзия травы приятно пружинила под ногами, а инфоиллюзии цветов безупречно благоухали Форд вытащил свой субэфирный чуткомат Робкий солнечный луч, случайно пробившийся сквозь туман, высветил синие и белые полоски на шкуре матрасса, чем немало его напугал Однако это событие оказалось не только кошмарным крахом одной начинающей науки, но и апофеозом другой А еще я пробовал научиться летать – И побежал$$);
insert into тип_продукции values (default, 3944, 'Папка с кольцами с прозрачными карманами, разделителями и застежкой-молнией', $$– Я дома, – шептал Артур Корабль этот был изумителен не своей конструкцией (мягко говоря, неудачной), но самим фактом своего появления В его пещере царил холод (а также смрад и сырость), но это еще пол-ужаса Он снял с рычага воображаемую трубку и стал крутить воображаемый диск Их внешность произвела неуловимо устрашающее впечатление даже на Зафода, который видел их впервые и даже ни разу о них не слыхал Одно-единственное «Уф!», и все тут – Вам весело? – спросил матрасс$$);
insert into тип_продукции values (default, 9500, 'Портфель из картона с прочным корпусом, удобными отделениями и мягкой ручкой', $$Зачем это понадобилось притаскивать сюда сто тысяч человек ради такой ерунды?

Он нервно двинулся в сторону рубки – Опасно?

– Мммм Роботы пялились на Зафода душераздирающими покойницкими глазами – Возмущения в континууме!

– А, это они мебельные магазины громят! – воскликнул Артур, с трудом вернувшись в вертикальное положение и – как он смел надеяться – в здравый рассудок – А это что?

