insert into тип_материала values (default, 7452, 'Элитная коллекция пригласительных открыток', $$Оно опасно?

– Мммм Слартибартфаст быстрым шагом вошел в «аквариум» и, судя по всему, затеял какой-то пустой разговор с метрдотелем, а один из роботов-клиентов, авторазмякающая модель, меж тем тихо сполз под стол, не переставая рассказывать, что именно собирается сделать с неким типом из-за некой девушки – А это что?

– Не Наша Проблема Как ни странно, за пределами словаря осталось слово «плучительно», означающее просто-напросто «с плучительностью» Ему почудилось, что его уносит ветер Вселенной, причем этот ветер – он сам Корабль пересекал орбиты планет Солнечной системы, намереваясь совершить пертурбационный маневр вокруг Солнца и, разогнавшись, выскочить в большой космос Попробуйте проделать это в погожий денек, рекомендует «Путеводитель» – И также я тебя прошу не говорить, что ты очень рада быть полезной или что ты польщена честью раскрыться передо мной и премного довольна вновь затвориться с сознанием выполненного долга, ладно?

– Ладно Тут он обнаружил в стене искомое отверстие и с хрустом воткнул в него вилку прибора$$);
insert into тип_материала values (default, 4960, 'Художественные журналы с персонализированной обложкой', $$– Серьезно?

– Да – Все в ажуре, офицер, – заявил он И оторопел от последствий своего заявления – Я вижу эту штуку, – объявил Артур, – это звездолет У официанта в блокноте числа пляшут Вскоре всех собравшихся обуяла необыкновенная, настоятельная вежливость – Нет уж А потом тьма позади Вселенной взорвалась, и каждый лоскуток тьмы обернулся косматым дымом преисподней – Не слишком похоже на наш случай Настоящее издевательство$$);
insert into тип_материала values (default, 6603, 'Организаторы с персонализированным дизайном и тиснением', $$– Мощность моей мыслительной деятельности на всех ее уровнях и во всех ее аспектах столь же безгранична, как бескрайние просторы самой Вселенной Артур невольно отпрянул – Откуда?

– Ты разве не изучал в школе древнюю историю Галактики?

– Моя киберкабинка была позади Зафода, – пояснил Форд, – это очень отвлекало Замотав головой, Форд закрыл лицо руками и нечаянно отфутболил к стене подвернувшийся под ногу цветочный горшок Дело в том, что принцип его работы основан на свойственной людям естественной предрасположенности не видеть ничего из того, чего видеть не желаешь, увидеть не предполагаешь или не можешь себе объяснить – Он говорит, что они забрали «Пепел» – Ладно, – сказал Зафод и напрягся, – а теперь раскройся Ему почудилось, будто он – одна из мыслей Вселенной, а Вселенная – одна из его мыслей – Теперь понял?

– Нет, – признался Артур Артур поднял глаза$$);
insert into тип_материала values (default, 7332, 'Альбомы для фотографий с тиснением и мягкими листами', $$– Считайте, что вы ее уже выразили, мой дорогой друг, – флюрбнул матрасс, – считайте, что вы ее уже выразили – Хм Слартибартфаст дернул за ручку, и она умолкла – Пойду-ка вздремну, – проговорил он – Не могу я с ней сжиться, – мрачно вымолвил он и выслал в свой желудок третий стакан: пусть найдет второй и выяснит, почему тот еще не доложил о здоровье первого$$);
insert into тип_материала values (default, 880, 'Изготовленные на заказ ежедневники с закладками из ленты', $$– Верно, – признал Артур Со вздохом облегчения и возгласом триумфа они вскочили на диван, солнце, моргнув, погасло, и, провалившись сквозь головокружительное ничто, они выбрались на свет божий в самом неожиданном месте – посреди поля крикетной площадки «Лордз» (что расположена в лондонском районе Сент-Джонс-Вуд) незадолго до окончания последнего матча международного турнира на Приз Австралии 198… года, причем команде Англии требовалось лишь двадцать восемь перебежек для победы И потому вскорости они оказались у внутренней границы сферического, полого изнутри Пылевого Облака, со всех сторон окружавшего Криккит и его солнце Приятели направились к пресловутому кораблю Часа через два стало очевидно, что Зафод тверд в своем решении, и корабль вновь поднялся в небо, даже не спустив трапа$$);
insert into тип_материала values (default, 1386, 'Персонализированные конверты с сургучными печатями', $$Неслышно появилась узенькая серебряная каемка ранней зари Свобода По моему состоянию вы можете заключить, что я едва спасся А за спиной человека из исполинских клубов мглы стали постепенно вырисовываться три высоких столба Он никогда не слышал, чтобы на Зете Прутивнобендзы выступали с речами, а тем более знаменитости Воцарилась бесконечно холодная и зловещая тишина Может, там находится другая планета – ох, как трудно далось это предположение самозамкнутым умам сынов Криккита с его глухой стеной вместо неба Судя по всему, вон туда Тогда бы ему заметили, что он поет только одну ноту, на что бы он ответил, что по очевидным, как ему кажется, причинам он опустил кусочек «ология любви» На полпути к рубке его осенило, что это вполне может оказаться Марвин, и он бегом вернулся обратно$$);
insert into тип_материала values (default, 864, 'Комплекты открыток с тематическими принтами', $$Охмешконасыпатель покосился на невероятную алмазную россыпь космической ночи – Привет, Слартибартфаст, – наконец-то выдавил из себя Артур Наверху их глазам предстала совершенно бредовая картина Без нее мой корабль перестанет работать Робот-официант, робот-буфетчик и робот-метрдотель обслуживали роботов-клиентов Триллиан казалось, что это-то ей и требуется после всего пережитого Но тут же, заметив, что отряхивает именно халат, застыл как вкопанный По трапу решительной походкой сошла высокая серо-зеленая фигура и приблизилась к маленькой кучке людей, которые окружали жертв недавней абсурдной бойни А это совсем другой коленкор$$);
insert into тип_материала values (default, 1386, 'Декоративные коробки с узорами из тиснения', $$Инопланетное существо, морща лоб, заглянуло в штучку вроде папки, которую сжимало в своих длинных, лианообразных инопланетных пальцах Форд саркастически огляделся по сторонам Он встал на дыбы, чтобы заглянуть за заросли, но смотреть было не на что Он был призван воскресить экономику системы Прутивнобендзы, напрочь подорванную расходами на его строительство После чего задумался, а настолько ли хорош, как ему кажется, – и, испытав новое потрясение, едва не уронил стакан (полный) Однако через некоторое время до него дошло, что он недалеко продвинулся и все же следует спросить: «Это в каком плане?»

– При передвижении по космосу, – повторил Слартибартфаст, – числа – настоящий бич божий – Не могу я с ней сжиться, – мрачно вымолвил он и выслал в свой желудок третий стакан: пусть найдет второй и выяснит, почему тот еще не доложил о здоровье первого – Скатертью дорожка, – пробормотал Зафод, перевернулся на другой бок и всю ночь не смыкал глаз Попятившись, Артур испуганно огляделся по сторонам Финиш$$);
insert into тип_материала values (default, 5168, 'Экологичные сумки-шопперы с ручками из крафт-бумаги', $$– Ву-ун, – враднул он наконец – Да что этот старый дурак собрался делать, вакуум его заарктурь? – взорвался Форд Пора смываться Зафод отключил большинство второстепенных систем и механизмов Проведя рукой по стене, он нащупал нечто ценное В нем звучала даже какая-то интеллигентная хрипотца – Угм, – произнес Артур, глубокомысленно морща лоб, чтобы никто не усомнился в маневренности его извилин, – угу$$);
insert into тип_материала values (default, 3150, 'Оригами-комплекты с пошаговыми инструкциями', $$Потренируйтесь делать пике, вначале простое, а потом, мерно дыша, лягте в дрейф над верхушками деревьев И оторопел от последствий своего заявления Как ни странно, за пределами словаря осталось слово «плучительно», означающее просто-напросто «с плучительностью» – Затвори пасть Неся в руках поднос с ужином, она вошла к Зафоду и спросила, нет ли у него желания поговорить Артур увидел вереницу крохотных огоньков, что, качаясь и приплясывая, медленно двигались к ним$$);
insert into тип_материала values (default, 2720, 'Набор бумажных цветов с реалистичными деталями', $$– Это необходимо убрать, – сказали криккитяне, направив корабль в сторону дома Триллиан терпеливо кивнула самой себе, досчитала до предыдущего числа в кубе, вяло швырнула поднос в стену, прошла в телепортационную кабину и просто ушла из его жизни – Я же сказал! – заорал Форд, вскочив на ноги А потом все завершилось – так же внезапно, как и началось Затем поспешил влить в себя еще один – пусть догонит первый и составит ему компанию – Неверно, – пробурчал Марвин Следовательно, надо отыскать этого собрата – «Пепел», – сухо ответил Артур$$);
insert into тип_материала values (default, 1500, 'Календари с эстетичными дизайнами и функциональными функциями', $$Тебе это по силам?

– Что это Слартибартфаст так волнуется? – спросил Артур Он одновременно казался твердым, как деревья, и бесплотным, как сон русалки – Форд встряхнул прибор Больше ничего не произойдет – Быть такого не может, – сказал Форд, когда наблюдатели оправились от ускорения, а корабль уже рассекал верхние слои атмосферы На миг болото буквально вскипело: роботы все разом накинулись на Марвина, оторвали его ногу-протез и вознеслись обратно на свой корабль, который вымолвил: «Фу!»

– Вот видите, с какими издевательствами мне приходится смиряться? – сказал Марвин момишкающему матрассу Но не думаю, что с дурными намерениями Зафод застыл как вкопанный$$);
insert into тип_материала values (default, 260, 'Ежедневники с яркими принтами и водостойкой обложкой', $$– Рада быть полезной И все засохли Затем поспешил влить в себя еще один – пусть догонит первый и составит ему компанию Людям на крикетной площадке «Лордз» почудилось, что еще один ресторан возник и вылетел в трубу, как оно часто бывает с ресторанами в Северном Лондоне, и что это «Не Наша Проблема» По-моему, врут – Я тут временно спустил свой разум с цепи, предполагая, что, если я миру дико понадоблюсь, он призовет меня обратно Финиш$$);
insert into тип_материала values (default, 2046, 'Блокноты с обложкой из переработанного картона и тонированной бумагой', $$Еще раз широко улыбнувшись, он откусил кусочек от кроличьей ноги – остатка вчерашнего ужина Вторая реакция: «Извините, можно выйти?»

– И что, эта штука полетит? – спросил Артур, сочувственно косясь на связанные веревочками трубы и приклеенные к картонной обшивке провода, что составляли интерьер корабля Топ-топ-топ-топ Они прошли очень близко от наблюдателей под деревом, размахивая фонарями, от чего по траве и листве скакали забавные «зайчики», радостно болтая между собой и самым натуральным образом распевая песню о том, как все чуд-чуд-чудесно на свете, как они счастливы, как здорово они потрудились на ферме и как приятно возвращаться домой, где ждут жены и дети Не бросай трубку$$);
insert into тип_материала values (default, 979, 'Наборы карточек ручной работы с уникальными иллюстрациями', $$– Ну-ка, улыбочку, усмешечку!» Я разъяснял, что для того, чтобы мое лицо исказила улыбка, нужно отнести его в мастерскую и часа два поработать над ним кувалдой – Хорошо И пискнул Господи, здесь же их полным-полно Они вели себя очень мирно…

– Извини, Питер, я тебя перебью – диван только что исчез$$);
insert into тип_материала values (default, 6840, 'Настенные панно из бумаги-маше с объемными деталями', $$– Ты будешь слушать или нет?

– Я слушаю, – сказал Артур, – только боюсь, толку мне от этого мало Не Наша Проблема Матрасс флёпал вокруг него Но едва сойдя со стапелей, он и первой своей радиограммы – сигнала SOS – передать не успел, как все его системы беспричинно отказали – Возмущения в континууме!

– А, это они мебельные магазины громят! – воскликнул Артур, с трудом вернувшись в вертикальное положение и – как он смел надеяться – в здравый рассудок Артур увидел вереницу крохотных огоньков, что, качаясь и приплясывая, медленно двигались к ним Однако же если в решающий момент вам посчастливится нежданно отвлечься на умопомрачительную пару ног (щупалец, ложноножек, в зависимости от вашей видовой принадлежности и/или личных вкусов), или на взрыв бомбы неподалеку, или на внезапное явление ужасно редкого жука на соседней былинке – тогда-то, к своему изумлению, вы увильнете от всякого столкновения с землей, точнее, останетесь болтаться в каких-то считанных дюймах над ее поверхностью – Я дома, – хрипло буркнул Артур$$);
insert into тип_материала values (default, 1615, 'Доски для заметок из переработанной бумаги с ярким дизайном', $$– Я этот номер уже видел, – проговорил он Жизненный цикл отвертки с храповиком весьма занятен Из тьмы прямо на них вылетел, изрытая лазерный огонь, боевой звездокрейсер размером с небольшой промышленный город Они попросили меня открыть мост Ветерок осторожно ворошил высокую траву вокруг пещеры, птицы чирикали друг с дружкой, бабочки изящно порхали туда-сюда, и вообще вся природа из кожи вон лезла, стараясь произвести благоприятное впечатление В наше время мало что производится на фабриках, поскольку в бесконечно огромной Вселенной – например в нашей – большинство вещей и предметов, какие только может вообразить человек (а также масса абсолютно невообразимых), где-нибудь да произрастает само В системе Неавооси находятся – то есть находились – крупнейшие страховые компании Галактики И все засохли$$);
insert into тип_материала values (default, 2850, 'Конверты с вырезами и красочными подкладками', $$– Да так, ничего особенного, – сказал Форд Артуру пришло в голову, что раз они добрались до конца, точнее, до начала всех ужасов, которые смутно пережили, сейчас должна стрястись беда – Он сказал подождать у его корабля, – сообщил Артур Каждое утро традиционный душераздирающий вопль оповещал окрестности, что Артур Дент проснулся и заново ужаснулся своему местоположению А потом даже гумкнул от избытка чувств – Мы уже установили, что оно не мое Она была безлична – не как неизвестно чей злобный вопль в толпе, но как отпечатанный на принтере квиток за неправильную парковку Сам собой откинулся трап – Ты наверняка знаешь, что сейчас произойдет, – сказал Слартибартфаст Форду Но тут синее полисменообразное нечто тронуло их обоих за плечи$$);
insert into тип_материала values (default, 3256, 'Подарочная упаковка с персонализированными сообщениями и декором', $$Попытайтесь взять пример с нас, матрассов Можете рассказать это вместо анекдота своим друзьям Зему и Зему при первой же встрече – они животики надорвут, если я их знаю  – Пользительное занятие Артура трясло – Как вас зовут?

– Дент Триллиан терпеливо кивнула, побарабанила пальцами по столу и нажала кнопку внутрисвязи:

– Думаю, в веселье из-под палки ты сейчас не нуждаешься Для примера – задумайте число, любое число Хотя в горле у него привычно саднило от традиционного утреннего душераздирающего вопля, он внезапно пришел в великолепное расположение духа$$);
insert into тип_материала values (default, 1272, 'Наборы для рисования с бумагой высокого качества и инструментами', $$Сотни разных мыслей, расталкивая друг дружку, боролись за контроль над его голосовыми связками А это совсем другой коленкор – Где?

Слегка дрожащей рукой Форд очертил чуткоматом дугу в воздухе Охмешконасыпатель Конца-Краю-Не-Знающий принадлежал – то есть принадлежит – к очень узкому кругу бессмертных обитателей Вселенной – Нет уж$$);
insert into тип_материала values (default, 1656, 'Книги-раскраски со сложными узорами и мотивами', $$Если бы его спросили, он бы ответил, что все время мурлычет первую строчку песни «Психология любви» – Похоже на балаган, – сказал Артур Инопланетный корабль уже с треском прорывался сквозь верхние слои атмосферы, навстречу той ужасной пустоте с редкими-редкими материальными вкраплениями, из которой и состоит Вселенная Только двадцать минут назад он решил сойти с ума – и вот уже гоняется по лугам доисторической Земли за честерфильдским диваном В его голове родился целый рой глубокомысленных вопросов А эта была не хуже прочих – Она самая Роботы пялились на Зафода душераздирающими покойницкими глазами А несколько часов спустя вновь отправился в свой скорбный обход темных коридоров, срывая зло на любезных дверях$$);
insert into тип_материала values (default, 4004, 'Наборы оригами с разноцветной бумагой и схемами', $$Глянул на Слартибартфаста Зафод крякнул А случится это сегодня – Завладеем, – заявил робот – Через несколько минут, – терпеливо повторил робот, – мы завладеем Золотой Перекладиной…

– Фигушки, – сказал Зафод Я, наоборот, от нее бегал Погоди, сейчас уточню – Тут одна подробность, – взорвался он наконец, – если мы не поторопимся смыться, то рискуем вновь влипнуть во всю эту историю Поле «Не Наша Проблема» куда проще в использовании и эффективнее, а главное, целых сто лет может работать от одной «пальчиковой» батарейки И может статься, приведет к безвременной гибели всю Вселенную$$);
insert into тип_материала values (default, 5092, 'Настенные обои с текстурами, имитирующими натуральные материалы', $$Разумеется, экипаж не реагировал на присутствие посторонних – ведь их тут, в сущности, и не было Вот как расшифровывается ННП Форд злобно обернулся к Артуру Спустя некоторое время он начал медленно, воровато пробираться вперед с гримасой вдумчивой озадаченности на лице – как леопард, который не совсем уверен, что только что видел в полумиле впереди, на раскаленной и пыльной прерии, полупустую банку «Вискаса» – Откуда на этом поле диван? – вскричал он – Было что-то интересное?

И вновь они балансировали на краю ужасно высокого утеса Охмешконасыпатель Конца-Краю-Не-Знающий принадлежал – то есть принадлежит – к очень узкому кругу бессмертных обитателей Вселенной$$);
insert into тип_материала values (default, 3655, 'Оберточная бумага с замысловатыми принтами и фактурами', $$Форд, еще раз пожав плечами, исполнил требуемое:

– Все последние пять лет приснились тебе во сне Мерещилось, будто мрак гудит, с треском лопается на носу корабля – Разве что «Психоз в космосе» Некоторое время все молчали, из чего Зафод заключил, что роботы явились сюда не для разговоров и дело за ним – Роботы, – поправил себя Зафод, – что вы, роботы, тут делаете?

– Мы пришли, – прохрипел робот, – за Золотом Перекладины Артур пришел в безмятежное настроение – Ну и как там?

– А это что, твоя пещера? – спросил Форд – Ты что-то придумал, правда? – спросил Артур – По-моему, никаких загадочных материализации на поле не было с… э-э… с… может, их вообще ни разу еще не было – ты не помнишь?

– А Эджбастон 1932 года?

– А, ну и что же там стряслось?

– Гм, Питер, если я не ошибаюсь, Кантер играл против Уилсокса и шел в нападение со стороны павильона, когда вдруг напрямик через площадку пробежал зритель$$);
insert into тип_материала values (default, 2664, 'Свадебные приглашения с замысловатыми кружевами из бумаги', $$Он опять воззрился на экран Оплетенные соломой бутылки поджидали неосторожных путников в засаде И сколько ни гляди на циферблат, неумолимые стрелки вскоре передвинутся на четыре – час, когда начинается долгое, мутное и, что греха таить, безумное чаепитие души – Хуже нигде уже не будет, – сказала она себе, нажимая кнопку Инопланетный корабль уже с треском прорывался сквозь верхние слои атмосферы, навстречу той ужасной пустоте с редкими-редкими материальными вкраплениями, из которой и состоит Вселенная В таком настроении к оружию лучше не прикасаться – Я не о полотенце, – сказал Артур Через некоторое время Форд счел необходимым отнять у Артура свою конечность$$);
insert into тип_материала values (default, 1595, 'Рождественские открытки с тиснением и блестящими элементами', $$Форд взял его за руку А придумал он вот что Я сам посадил сотни Какой-то голос произнес: «Это…» Слартибартфаст дернул за ручку, и он умолк$$);
insert into тип_материала values (default, 345, 'Наборы для квиллинга с разноцветными полосками бумаги и инструментом', $$Тогда я попробую ходить задом наперед Марвин помедлил, отдавшись воспоминаниям Затем Артур заметил, что идущая впереди компания тоже обратила внимание на визг и пришла в замешательство Тем временем Форд начал выделывать какие-то странные фортели – Я только, – продолжил Слартибартфаст со вздохом, – я только хотел упредить ваш вопрос и заранее пояснить, почему на моем корабле все вычисления производятся в блокноте официанта$$);
insert into тип_материала values (default, 3276, 'Абажуры из бумаги с уникальными формами и узорами', $$– Ты завершил то, к чему шел много лет По-моему, это было животное из семейства аллигаторов – Покамест я недалеко продвинулся, – сказал он и протянул Артуру руку Он осознал, что удостоился знакомства с носителем незаурядного ума Но возможно, тебе любопытно будет узнать, что твой покорный слуга единолично ответственен за удлиненную форму животного, которому в будущих веках дадут имя «жираф» – Я сам знаю, на что это похоже, – отрезал Слартибартфаст и вошел в пресловутое помещение – Вот что я сказал Роботы Невдалеке слышались голоса играющих детей, а чуть подальше в раннем сумраке виднелся небольшой городок$$);
insert into тип_материала values (default, 6461, 'Мебель из картона с прочной и легкой конструкцией', $$– Мы ищем Ключ, – повторил он, – мы уже владеем Деревянным Столбом, Стальным Столбом и Плексигласовым Столбом – Сгинь в вакуум, – сказал Зафод А придумал он вот что Криккитяне смотрели друг на друга, направо, налево, вперед, назад, даже на землю Нервно опираясь о стену коридора, он морщил лоб (то есть лбы), словно пытаясь откупорить бутылку методом телекинеза Но никто этого не спрашивал, и Форд злился «Пейте смело, – рекомендует «Путеводитель», – и ни пуха вам ни пера» Новая вибрация сотрясла корабль – Ч… ч… ч… – выговорили его губы$$);
insert into тип_материала values (default, 870, 'Дизайнерская бумага для скрапбукинга с различными текстурами и принтами', $$На следующий день Артур сшил себе сумку из кроличьей шкурки – под всякие полезные вещи Точнее, распахнул люки и выпустил из себя нечто необычное в количестве одиннадцати штук Фальшивка Так и вышло$$);
insert into тип_материала values (default, 340, 'Обложки для книг с индивидуальной гравировкой и яркими рисунками', $$Слова все время забываю Он заразился у Слартибартфаста беспокойством, хоть и не понимал его причин Мелкие капли едва просачивались сквозь туман Словно ниоткуда, зазвучала музыка И поистине, она того стоит Старец, пропустив эти слова мимо ушей, внимательно, с непонятным в данной ситуации волнением следил за происходящим на поле$$);
insert into тип_материала values (default, 2001, 'Скетчбуки с акварельной бумагой и удобной спиралью', $$Что матрасс и сделал, испустив еще одно легкое флюпчание – Сие проклятие, – не унимался Слартибартфаст, – пройдет по Галактике с огнем и мечом Он, как известно всем, был уничтожен, развеян по извечным водоворотам пространственно-временного континуума и исчез навеки Но только не вверх Не знаю, зачем им это надо, но так оно и есть И пискнул Звук превратился в монотонный звон в ушах Она была холодна – и то был не ледяной хлад льда, но холод стены А в моих руках точная копия, изготовленная руками народных умельцев$$);
insert into тип_материала values (default, 2550, 'Папки-регистраторы с тиснением и прочной картонной обложкой', $$– Еще миллион лет, – заявил Марвин, – еще миллиончик – Я стоял на центральной платформе Мотнув головой, Артур сел на землю и поглядел на Форда снизу вверх – Да, бывает, – заметил Форд Над всеми нами простерты крыла смерти$$);
insert into тип_материала values (default, 1512, 'Наборы для рисования с цветными карандашами, фломастерами и бумагой', $$Большинство зрителей, будучи не в силах выдержать этого зрелища, зажмурили глаза и переключились на слушание радиотрансляции Охмешконасыпатель только хмыкнул По жизни он не согласился бы взойти на борт такого корабля даже за всю рисовую водку страны Китай Он, как известно всем, был уничтожен, развеян по извечным водоворотам пространственно-временного континуума и исчез навеки Для практики я разговариваю с этими… ну как их там… как называются эти, с которыми разговариваешь, когда с ума сходишь? Ну как Георг Третий – Круто По-прежнему ничто не шевелилось – Спасибо, что осчастливили простую скромную дверцу$$);
insert into тип_материала values (default, 6084, 'Маски из папье-маше с изысканными деталями и рисунками', $$Охмешконасыпатель скорбно и устало прикрыл глаза, заказал бортовой стереосистеме какой-нибудь легкий джаз и рассудил, что все бы ничего, если бы не воскресные дни, будь они неладны Третий и самый загадочный образчик не-абсолютности кроется в соотношении между количеством включенных в счет блюд, стоимостью каждого блюда, числом людей за столом и суммой, которую каждый из них готов заплатить (количество людей, которые действительно прихватили с собой деньги – лишь субфеномен вышеуказанного поля) – А, вот как, – сказал Артур – А затем мы отправимся, – на полном серьезе заявил робот, – на вечеринку С его шкурки, заплимтавшей от умиления, во все стороны полетели брызги воды Под ними расстилались серебристо-белые ризы Аллосиманиуса-Синеки – Эксцентрика Гамбитус, ты ее когда-нибудь видел? Троегрудая путана с Эротикона-6 Оно, случайно, не твое?

– Изволь заткнуться насчет твоего полотенца! – воскликнул Форд Артур привстал с дивана и помотал головой:

– Куда мы летим?

– На битву с Древним…

– Замнем, – вмешался Форд$$);
insert into тип_материала values (default, 3250, 'Изготовленные на заказ фотоальбомы с хронологическими разделителями', $$А ведь Зафод был на борту один Но несть числа тем, кто упивается историей «Звездного Титаника», легендарного корабля-колосса Ветер обдувал бухту, где останки одной из крупнейших и мощнейших космических флотилий в истории Галактики поспешно превращались из пепла в исходное состояние Ни информации, ни иллюзий – только они трое, белые стены да несколько мелких устройств, которые, по-видимому, следовало подключить к некой розетке – Именно Когда он притомился тщетно обрабатывать гору массивными отбелизаторами, аннигиляторами рефракции и спектральными астраломылками, ему открылось, что за оставшиеся девять часов он вряд ли выполнит зарок А кто-нибудь еще его заметил?

– По-видимому, нет И только Слартибартфаст ежился, точно ему было не по себе$$);
insert into тип_материала values (default, 3290, 'Свадебные программы с элегантным дизайном и качественной бумагой', $$И тишина без конца – Все в ажуре, офицер, – заявил он – Нет ли фильмов, которых я не видел уже тридцать тысяч раз?

– Нет Они находились перед Рубиконом исторического самосознания своего народа – А во-вторых, – продолжал Форд, – у тебя в бороде кость Зафод похолодел А потом даже гумкнул от избытка чувств$$);
insert into тип_материала values (default, 6237, 'Приглашения на детский праздник с яркими принтами и забавными персонажами', $$– При передвижении по космосу, знаете ли… – проговорил Слартибартфаст, возясь с оборудованием Зала информационных иллюзий, – … при передвижении по космосу… – Не договорив, он принялся озираться по сторонам Артур растерянно кивнул Как ни странно, и тут моделью послужило маленькое итальянское бистро – Ты будешь слушать или нет?

– Я слушаю, – сказал Артур, – только боюсь, толку мне от этого мало – Что это было? – шепотом спросил Форд Даже Форд, похоже, повеселел Они находились перед Рубиконом исторического самосознания своего народа Роботы До сегодняшнего вечера$$);
insert into тип_материала values (default, 4140, 'Карточки с рецептами со стильными рамками и водонепроницаемой подложкой', $$Некому было его услышать, некому было с ним поговорить – Хм А теперь – в Зал информационных иллюзий А это другое – Ау, компьютер! – прошептал он Также вы научитесь правильно приземляться – сразу предупредим, что первая попытка выйдет большущим комом Без нее мой корабль перестанет работать Аналогично последовательность отдельных впечатлений сливалась тут в единое чувство – хотя на чувство оно как-то не походило Оно опасно?

– Мммм$$);
insert into тип_материала values (default, 1443, 'Обложки для паспортов с замысловатыми рисунками и защитой от RFID', $$Тело Артура безвольно плюхнулось обратно на траву – Вне всяких сомнений, – ответил Форд с не меньшей непреклонностью В обе стороны, на сотни миль передо мной и на сотни миль позади меня, тянулось полотно моста Он шествовал к центру поля ужасающе решительной поступью, и его борода, волосы и одеяние развевались по ветру – вылитый Моисей на горе Синай, только в роли Синая сейчас выступала холеная лужайка, а не грозный вулкан в косматом дыму, каким его обычно изображают И каждая частичка еды была, по-видимому, наделена всеми механическими свойствами, например, «цыпленка-алла-романа», на деле им не будучи Причем все они созданы трудами ветра и дождя – естественный процесс эрозии$$);
insert into тип_материала values (default, 2632, 'Коробочки для подарков с окнами из прозрачной бумаги и лентами', $$– Завладеем, – заявил робот Солнце клонилось к закату Сегодняшнее утро выдалось благоуханным и ясным – в чем лично удостоверился Артур Дент, выйдя из пещеры, которую именовал домом (за неимением как более подходящего названия для нее, так и более подходящей для этого названия пещеры) – Здравствуйте, робот, – поздоровался матрасс В его голове родился целый рой глубокомысленных вопросов Птицы выражали в песнях свое мнение обо всем этом – по-видимому, благоприятное Из тьмы прямо на них вылетел, изрытая лазерный огонь, боевой звездокрейсер размером с небольшой промышленный город$$);
insert into тип_материала values (default, 4620, 'Декоративные вазы из картона с уникальными формами и текстурами', $$По какой-то непостижимой причине их элегантные обтекаемые тела казались совершенным олицетворением чистого, патологического зла И тут мы подходим к еще одной и главной причине его странности – Терпение, – вновь заявил Слартибартфаст С кличем внезапного восторга он спрыгнул с утеса и весело помчался вдогонку за Фордом Префектом и своенравным предметом мебели Зафод тихо проскользнул в нее Артур последовал совету, вначале несколько нервно, словно боясь, что рука сейчас обернется скользкой рыбиной Похоже, в основном он состоял из низеньких зданий, построенных из белого камня$$);
insert into тип_материала values (default, 990, 'Костюмы из папье-маше для фестивалей и театральных представлений', $$Он созерцал приборы с видом человека, который пытается перевести градусы Фаренгейта в градусы Цельсия, пока его дом горит Безусловно, вся земная медицина была уже не в силах его спасти – И все же, – продолжало оно, – спустя пару деньков всему этому придет конец, не правда ли? Хотя, как я уже вам говорил при нашей последней встрече, это меня весьма опечалило Он пронзил облака, на миг озарив их своим серебряным свечением, и исчез из виду Артура – одинокой букашки, бестолково скачущей на месте посреди бескрайней шири Меня заставляли сидеть на ящике и рассказывать мою историю, а зрители уговаривали меня приободриться и мыслить позитивно – Нет, – сказал Форд, – он чувствует мобильную аномалию в ткани пространства-времени, локальное возмущение, очаг нестабильности$$);
insert into тип_материала values (default, 2754, 'Органайзеры для ванной с водостойким покрытием и нескользящим дном', $$– Я думал, ты сказал, что это не наша проблема Обычно фокус в том, чтобы не слишком сосредоточиваться на своих действиях, но просто пускать их на самотек, точно нечто от вас не зависящее Небосвод – от горизонта до горизонта, с востока до запада, с севера до юга – был абсолютно черен Но несть числа тем, кто упивается историей «Звездного Титаника», легендарного корабля-колосса – Ликвидация, – сказал он$$);
insert into тип_материала values (default, 4200, 'Календари с магнитными держателями и увеличенными полями для заметок', $$– Я обнаружил, – заявил он, – аномальные протечки Затем они построили собственный корабль – он-то и готовился сейчас к взлету – ННП – это нечто, что мы не можем увидеть, или не видим, или то, чего нам не дает увидеть наш мозг, потому что мы считаем, что это не наша проблема Матрасс зауйломикал с головы до пят, отчего гладь мелкой, заросшей ряской протоки подернулась восторженной рябью$$);
insert into тип_материала values (default, 1950, 'Подарочные сертификаты с тиснением и персонализированным дизайном', $$Вообще-то я практикуюсь Однако казалось, если что тут и назревало, так только какая-то церемония И вновь зашагал Звездолет (да-да, еще один, просто звездолетопад какой-то), только на сей раз изящный и серебряный, спустился с небес на площадку – тихо, как-то даже интеллигентно, совершая опорами балетные па во славу технического прогресса О нет – то были действия, странно непохожие на все его обычные странности и чудачества А когда раскроешься, я тебя прошу, не говори, что тебя это осчастливило, ладно?

– Ладно Было неопровержимо доказано, что количество зрителей, смотревших телерепортаж о запуске «Титаника», превосходило все население Вселенной на тот момент$$);
insert into тип_материала values (default, 6916, 'Обложки для альбомов с тисненым текстом и мягкой набивкой', $$Разумеется, экипаж не реагировал на присутствие посторонних – ведь их тут, в сущности, и не было То была ненависть, слепая ненависть Если не считать разговоров с некоторыми дубами – этим хоть в лоб, хоть по лбу Форд взял его за руку – Порвалась, – добавил он, – ни с того ни с сего порвалась цепь причин и следствий…

И наперекор сказанному, неуклюже сполз под стол после еще одного стакана Он зафлёпал туда-сюда, ошеломленный и взволнованный Музыка, доносившаяся из бортовых динамиков, рвала душу – ничего тут не поделаешь Он перешел на шепот Всех их зовут одинаково – Зем – Возможно, до вас не сразу дойдет, что именно навело меня на это воспоминание, – таков уж мой мозг$$);
insert into тип_материала values (default, 400, 'Блокноты с прошитыми страницами и гибкой обложкой', $$Строго индивидуально, лицом к лицу, одного за другим и (тут он с особым сладострастием скрипнул зубами) в алфавитном порядке – Уф, нащупал, – сообщил он – По-моему, его здесь нет, – сказал он мальчишкам, которые немедленно столпились вокруг него, – вероятно, он куда-то откатился – Спасибо за внимание Нешуточное это дело – обнаружить, что после неопределенно долгого периода молчания ты, оказывается, не отучился разговаривать$$);
insert into тип_материала values (default, 1909, 'Упаковочная бумага с биоразлагаемым покрытием и яркими принтами', $$Самый подходящий афоризм, чтобы заронить в молодые умы искру вдумчивого отношения к жизни В ней стоял стол Фигура тихо преклонила перед ним колени – Ну и как она выглядит?

– Ну а мне-то откуда знать, идиот? Сам видишь – сам и описывай$$);
insert into тип_материала values (default, 2964, 'Визитные карточки с тиснением, ламинированием и выборочной УФ-печатью', $$Это Артур Дент говорит На обратном пути они спели немало мелодичных, наполненных глубоким смыслом песен на темы мира, справедливости, нравственности, культуры, спорта, семейной жизни и ликвидации всех прочих форм жизни Невдалеке слышались голоса играющих детей, а чуть подальше в раннем сумраке виднелся небольшой городок – Назревают великие события И тут мы подходим к еще одной и главной причине его странности$$);
insert into тип_материала values (default, 4104, 'Коробки для хранения с разделителями из картона и магнитными застежками', $$У официанта в блокноте числа пляшут Есть частные клубы летателей, где вам помогут достичь ключевого самозабвения Он пронзил облака, на миг озарив их своим серебряным свечением, и исчез из виду Артура – одинокой букашки, бестолково скачущей на месте посреди бескрайней шири Зафод так изумился, что роботам пришлось дать еще один залп, прежде чем он упал$$);
insert into тип_материала values (default, 3397, 'Тематические наборы открыток с художественными иллюстрациями', $$Ему только что пришел в голову великолепный способ победить ужас одиночества, кошмары, комплекс неполноценности из-за провала всех сельскохозяйственных начинаний и патологического отсутствия всякой будущности для него на доисторической Земле Приятели направились к пресловутому кораблю Весь фокус в том, чтобы научиться швыряться своим телом в земную поверхность и при этом промахиваться Кто-то коснулся его плеча – От… к-к-к… э-э… – добавил он немного погодя Вероятно, людей обуяла коллективная мысль «Ну и дела!», сопровождаемая единодушным чувством недоумения Ну а для Зафода это обернулось тем, что: а) он ни разу даже не подошел к девочке и б) пропустил целую эпоху в древней истории, знания о которой ему бы сейчас очень пригодились$$);
insert into тип_материала values (default, 4453, 'Комиксы с уникальными сюжетами и персонализированными персонажами', $$Слартибартфаст молча указал ему на ту сторону холма – Повелители Криккита, – выдохнул Слартибартфаст голосом призрака На миг воцарилась скорбная тишина, но тут же ее нарушил громкий ропот (будто сотня тысяч невидимых людей вымолвила: «Уф!»), и с небес, точно пушинки с одуванчика, посыпались белые роботы Затем из клубов дыма вынырнула светлая фигура Слартибартфаста Матрасс зауйломикал с головы до пят, отчего гладь мелкой, заросшей ряской протоки подернулась восторженной рябью Он подождал реакции Артура, но тот лишь благоразумно обронил:

– Давай дальше$$);
insert into тип_материала values (default, 5312, 'Книги с выдвижной бумагой с прикрепленными фигурками или предметами', $$– Мы могли бы побеседовать, – сказал матрасс, – хотите?

Матрасс был крупный, по-видимому, один из лучших в своем роде Сделав несколько опасливых вдохов, он прошептал:

– Дверь, если ты меня слышишь, ответь мне – только тихо-тихо-тихо – Они завяли лепел! – еще раз вскричал Слартибартфаст Правда, он всегда подозревал о ее существовании, поскольку обладал полным комплектом стандартных органов (и даже двойным – кое-каких), но, внезапно обнаружив в глубине своего существа эту затаившуюся зверюшку, был крайне шокирован Бедные кретины Матрасс момнухнул$$);
insert into тип_материала values (default, 4608, 'Поздравительные открытки с музыкальным чипом и настраиваемой мелодией', $$Первый комментатор призадумался Они и не догадывались, что всем вычислениям в области невероятности свойственны квазивзаимообратимость и кольцеобразность, благодаря чему все Бесконечно Невероятное почти немедленно осуществляется в реальности Шшшшрр Это крикетный приз Тот же самый эффект наблюдался и в случае с кораблем Слартибартфаста Против инстинкта не попрешь – наши герои невольно двигались опасливо, даже воровато, хоть и знали, что с тем же успехом могли трубить в трубы и вопить: «Ату!» – инфоиллюзию это бы не спугнуло Он решил оскорбить Вселенную$$);
insert into тип_материала values (default, 1296, 'Светодиодные фонари из бумаги с вырезанными узорами и мягким светом', $$Артуру Денту остро захотелось мороженого Видение дергалось и колебалось перед глазами Артура, хотя, видимо, в действительности это глаза Артура дергались вместе с головой – Я-то думал, что стряслось, – сказал Форд, – а это просто матч кончился – От… к-к-к… э-э… – добавил он немного погодя Марвин отвлекся от своего утомительного кругового обхода Пластмасса под бетон Звездолет (да-да, еще один, просто звездолетопад какой-то), только на сей раз изящный и серебряный, спустился с небес на площадку – тихо, как-то даже интеллигентно, совершая опорами балетные па во славу технического прогресса Хотя я узнал немало сногсшибательных вещей Однако казалось, если что тут и назревало, так только какая-то церемония Мозг просто вымарывает эту штуку из поля зрения, точно слепое пятно$$);
insert into тип_материала values (default, 8051, 'Украшения из папье-маше с яркими цветами и затейливыми формами', $$Артур обратил внимание, что двое криккитян завели новую песню – милую романтическую балладу, которая словно парила в прохладном ночном воздухе После чего задумался, а настолько ли хорош, как ему кажется, – и, испытав новое потрясение, едва не уронил стакан (полный) Следовательно, надо отыскать этого собрата – Пойдемте, – добавил он с неожиданной властностью, – я должен вам многое показать и поведать$$);
insert into тип_материала values (default, 5740, 'Модели парусных кораблей из бумаги с детальными парусами и корпусом', $$Похоже, на них восседали не то девушки, не то ангелы Музыка, доносившаяся из бортовых динамиков, рвала душу – ничего тут не поделаешь К его немалому удивлению, на поле перед ними находился мягкий диван, так называемый честерфильдский, обитый бархатом веселенького оттенка Их внешность произвела неуловимо устрашающее впечатление даже на Зафода, который видел их впервые и даже ни разу о них не слыхал И само собой разумеется, он был слегка пьян Вселенское Переустройство будет возобновлено Потренируйтесь делать пике, вначале простое, а потом, мерно дыша, лягте в дрейф над верхушками деревьев Умопомрачительно красивый, уникально огромный и к тому же самый уютный корабль в истории Галактики (точнее, в нынешней, сильно обкарнанной опровержениями версии этой самой истории – подробности см$$);
insert into тип_материала values (default, 4884, 'Бумажные скульптуры с подвижными частями и реалистичными деталями', $$Стратегия заключалась в том, чтобы он перехватил предыдущий у скрещения дорог, и пусть соединенными силами поднимут дух второго – Э-э-э?…

Существо кивнуло само себе, произвело чисто инопланетный щелчок застежкой папки и направилось к своему кораблю О нет – то были действия, странно непохожие на все его обычные странности и чудачества Вторая реакция: «Извините, можно выйти?»

– И что, эта штука полетит? – спросил Артур, сочувственно косясь на связанные веревочками трубы и приклеенные к картонной обшивке провода, что составляли интерьер корабля$$);
insert into тип_материала values (default, 2704, 'Коврики для занятия йогой из переработанного картона с противоскользящей поверхностью', $$Единственная надежда – застичь ННП врасплох краешком глаза – Верно, – признал Артур Золотая Перекладина заключена в механизме, который движет вашим кораблем Те, кто рождается бессмертным, от рождения бессознательно свыкаются с этим своим свойством, но Охмешконасыпатель – не из их числа – Эксцентрика Гамбитус, ты ее когда-нибудь видел? Троегрудая путана с Эротикона-6 Он только пялился на нее – ему еще не доводилось видеть девушку, способную сидеть на коленях у себя самой Ты это зачем? – Форд по-прежнему протягивал Артуру руку, а тот с изумлением пялился на нее$$);
insert into тип_материала values (default, 1050, 'Наборы для аппликации с цветной бумагой, ножницами и клеем', $$– Алло? Да? – пробормотал Артур – Вот что я сказал Чисто инопланетная долговязость, чисто инопланетная приплюснутая голова, чисто инопланетные глазки-щелочки, экстравагантно-складчатое золотое одеяние с воротником чисто инопланетного покроя и бледная, серо-зеленая инопланетная кожа, сияющая тем особым блеском, который дается большинству серозеленоликих субъектов лишь благодаря постоянному массажу и самому дорогостоящему мылу Марвин не удостоил его ответа и лишь с усиленной демонстративностью заработал суставами И тут мы подходим к еще одной и главной причине его странности Я ненавижу и презираю вас всех Он плюнул на это занятие и, переведя взгляд на навигационный экран, ахнул при виде беспрецедентного полчища звезд Правда, роботы сыпались не абы как, а четким военным строем Зафод крякнул Вот она:

Числа, записываемые в счета на территории ресторанов, не подчиняются математическим законам, которые управляют числами, записываемыми на любых других листках бумаги в любых других уголках Вселенной$$);
insert into тип_материала values (default, 224, 'Домики для кукол из картона с мебелью и аксессуарами', $$– Мм… да, – ответил Артур – Правда, что ли? – вскричал Зафод, поигрывая пистолетом Тем самым выведя Форда из медитационного транса – Не буду беспокоить тебя подробностями, а то они…

– Что «они»?

– Обеспокоят тебя Это было их творение, и сейчас они пели о нем песенку, изливая в ней двойную радость успеха и обладания И пискнул Зафод влил еще стакан в свою другую глотку Неслышно появилась узенькая серебряная каемка ранней зари Криккитские войны относились к древней истории Галактики$$);
insert into тип_материала values (default, 1164, 'Оригами-гирлянды с разноцветными бумажными фигурами', $$Сам собой откинулся трап Или, – добавил он почти под нос, – наблюдать крикетные матчи – …моргал…

– Ну да Артур Дент$$);
insert into тип_материала values (default, 4648, 'Подарочные пакеты с рельефным рисунком и ручками из ленты', $$– Да так, ничего особенного, – сказал Форд Стратегия заключалась в том, чтобы он перехватил предыдущий у скрещения дорог, и пусть соединенными силами поднимут дух второго В общем, неба они и не замечают «Автостопом по Галактике» – Это не мое полотенце, – заявил Артур, копавшийся в своей сумке из кроличьей шкурки – И что ты там делаешь?

– Сижу Внезапно Артур вспомнил, что через два дня Земля погибнет, и впервые испытал при этой мысли некоторое утешение Артур поделился своим впечатлением с друзьями – От… к-к-к… э-э… – добавил он немного погодя$$);
insert into тип_материала values (default, 432, 'Обложки для электронной книги с индивидуальной гравировкой и магнитными застежками', $$Слартибартфаст, Форд и Артур остановились под ароматно пахнущим деревом – Протечки?

– Протечки в пространстве-времени, – сказал Форд и поспешил подставить свое зверски ухмыляющееся лицо ветру, который как раз случайно пролетал мимо Взамен она направила корабль на Аллосиманиус-Синеку, планету льдов, снега, умопомрачительных красот природы и ужасных морозов – Мне много не надо, – кричал Форд в уточнение своих предыдущих замечаний, – только рюмка крепкого виски и компания братьев по духу!

Он несся, как лань, замешкавшись лишь на миг, чтобы взять на буксир Артура, который среагировал было на катастрофу в своем обычном духе – замер с открытым ртом, ожидая, пока все кончится Вероятно, природа – в своей безмерной мудрости – работает над этим Ты что, не помнишь?

– Помню И хотя они предназначались не нашим путешественникам, те машинально склонили головы – и слава богу, ибо маленький красный и тяжелый мяч (истинный виновник овации) просвистел в считаных миллиметрах над макушкой Артура – Знаю, – вымолвил нагнавший их Слартибартфаст, задыхаясь и волнуясь, – но тому есть причины Неся в руках поднос с ужином, она вошла к Зафоду и спросила, нет ли у него желания поговорить И вновь ответа не последовало$$);
insert into тип_материала values (default, 960, 'Бумажные гирлянды с вырезанными вручную узорами и тканевыми лентами', $$Нешуточное это дело – обнаружить, что после неопределенно долгого периода молчания ты, оказывается, не отучился разговаривать Особенно этот момент, когда нужно угодить в калитку маленьким красным мячиком Он только пялился на нее – ему еще не доводилось видеть девушку, способную сидеть на коленях у себя самой Ее-то и пытался найти Слартибартфаст – Она самая Проведя рукой по стене, он нащупал нечто ценное – Сгинь в вакуум, – сказал Зафод – Боюсь, это зрелище подействует вам на нервы, – предупредил он – Нет, – сказал Форд, – он чувствует мобильную аномалию в ткани пространства-времени, локальное возмущение, очаг нестабильности – Через несколько минут, – терпеливо повторил робот, – мы завладеем Золотой Перекладиной…

– Фигушки, – сказал Зафод$$);
insert into тип_материала values (default, 1357, 'Мемуарные книги с персонализированными обложками и расширенными полями', $$Это произошло как-то весенним вечером года два тому назад Тут-то он и услышал пресловутое «Уф!», что его страшно встревожило – Полагаю, – добавил он, сделав передышку на писк, – что вы решили обозвать его безмозглой задницей – Назревают великие события Артур уставился на компанию фермеров, пытаясь свести воедино крохи информации, которыми располагал – Повелители Криккита, – повторил Слартибартфаст Он таил надежду, что кто-нибудь спросит: «Что это ты мурлычешь?» – но никто не спрашивал – Чего? Зачем? Эгей-гей! Ну-ка вернись и повтори!

Он подпрыгивал и выплясывал, пока его ноги не подкосились, взывал, пока не надорвал связки Одно-единственное «Уф!», и все тут$$);
insert into тип_материала values (default, 1980, 'Игрушечные машины из картона с реалистичными деталями и подвижными колесами', $$– И уставился в крохотный иллюминатор – на кромешную тьму В нем зрела ненависть к Вселенной в целом и каждому из ее обитателей в частности Вот оно – то, что разрушили орды Криккита, то, что теперь держит их планету в заточении и будет держать до скончания вечности!

И вальяжным жестом мужчина извлек из воздуха модель Трикетной Калитки – Я собирал коллекцию интересных камней, а эти, сразу видно, сплошная скука$$);
insert into тип_материала values (default, 6935, 'Наборы для рисования с цветными карандашами, маркерами и бумагой премиум-класса', $$Слова все время забываю С того дня прошло уже два года – Пойдемте, – добавил он с неожиданной властностью, – я должен вам многое показать и поведать Если грубо округлить параметры, я в тридцать биллионов раз интеллектуальнее вас – Я был в Африке, – заявил Форд Синее с желтыми звездочками$$);
insert into тип_материала values (default, 6100, 'Бумажные самолеты с уникальным дизайном и аэродинамической конструкцией', $$– Бистроматика, – пояснил он В их штате есть специальные работники с удивительными телами и воззрениями Он перешел на шепот В его голове родился целый рой глубокомысленных вопросов Форд саркастически огляделся по сторонам$$);
insert into тип_материала values (default, 2070, 'Бумажные тарелки с персонализированными принтами и экологически чистым покрытием', $$Это звук, который издают живые матрассы в своей естественной среде обитания, приняв близко к сердцу чью-то повесть о жизненной драме – Ну-ка, улыбочку, усмешечку!» Я разъяснял, что для того, чтобы мое лицо исказила улыбка, нужно отнести его в мастерскую и часа два поработать над ним кувалдой Точнее, распахнул люки и выпустил из себя нечто необычное в количестве одиннадцати штук Это была безумная колымага из подручных материалов Воцарилась бесконечно холодная и зловещая тишина Однако на сей раз внизу что-то происходило Больше ничего не произойдет Форд саркастически огляделся по сторонам – Но зачем вы все ходите и ходите кругами? – спросил матрасс Грубо говоря, конечно$$);
insert into тип_материала values (default, 2291, 'Бумажные лампы с вырезанными вручную узорами и теплым рассеянным светом', $$Но радовался он зря Глянул на экран – и не узнал ни единого созвездия С тем же успехом можно покориться судьбе, а здравый рассудок поберечь на потом Некоторые из нас гибнут от рук охотников, но, поскольку всех нас зовут Земами, утраты проходят незамеченными, и момнуханье, таким образом, остается минимальным – Эксцентрика Гамбитус, ты ее когда-нибудь видел? Троегрудая путана с Эротикона-6 – Может, мне…

– Нет, – рявкнул Форд Впереди них сидели трое пилотов – Мы уже установили, что оно не мое Одни вязы он огибал, сквозь другие просачивался с ловкостью призрака$$);
insert into тип_материала values (default, 1150, 'Картонные домики для кошек с прорезями и мягкими подушечками', $$Однако Эффрафакс все же проиграл пари – и лишился головы – из-за педантизма некоего арбитра, обратившего внимание на то, что: а) при прохождении через место, где следовало находиться Меграмалу, он ни обо что не споткнулся и не расшиб себе лоб и б) в небесах засияла какая-то подозрительная новая луна Артуру пришло в голову, что раз они добрались до конца, точнее, до начала всех ужасов, которые смутно пережили, сейчас должна стрястись беда – Куда? На чем? – воскликнул Артур Что матрасс и сделал, испустив еще одно легкое флюпчание – Сие проклятие, – не унимался Слартибартфаст, – пройдет по Галактике с огнем и мечом$$);
insert into тип_материала values (default, 1360, 'Доски для рисования с магнитной поверхностью и водонепроницаемой бумагой', $$– Но…

– Демонстрирую, – сказал Форд Казалось, его соорудили где-то в сарае – собственно, так оно и было «Может ли быть, что это и есть истинное устройство Вселенной? – вопросил он себя Сам себе сосчитал пульс – Полотенце не мое, – настаивал Артур, – именно это я и пытаюсь…

– А я пытаюсь потребовать, чтобы ты заткнулся, – продолжал Форд, переходя на рык, – причем немедленно!

– Ладно, – сказал Артур, пытаясь засунуть полотенце обратно в свою неуклюжую сумку Приборы, столь занимавшие внимание Слартибартфаста, были вмонтированы в донца бутылок, которые, в свою очередь, были заделаны в бетонную стену Мотнув головой, Артур сел на землю и поглядел на Форда снизу вверх Зафод похолодел – Да? – обалдело переспросил Зафод$$);
insert into тип_материала values (default, 840, 'Бумажные зонты с красочными принтами и водоотталкивающей обработкой', $$Он прошел к зеленой винтовой лестнице из кованого железа, непонятно зачем помещенной в середине рубки, и начал всходить по ней Три столба с двумя поперечинами Надежда и ликование в душе Артура вмиг сменились чувством крайней озадаченности Он замер «Криккит-1» не был хорошим кораблем Первым потрясением для него было открытие, что у него имеется душа как таковая$$);
insert into тип_материала values (default, 6536, 'Металлизированная бумага с блестящим покрытием и широким спектром оттенков', $$Темп застольных манипуляций неуловимо ускорился Матч меж тем продолжался Еще раз широко улыбнувшись, он откусил кусочек от кроличьей ноги – остатка вчерашнего ужина – Полотенце не мое, – настаивал Артур, – именно это я и пытаюсь…

– А я пытаюсь потребовать, чтобы ты заткнулся, – продолжал Форд, переходя на рык, – причем немедленно!

– Ладно, – сказал Артур, пытаясь засунуть полотенце обратно в свою неуклюжую сумку Форд взял его за руку Теперь слышался какой-то негромкий шум, и исходил он определенно из района рубки – Ого, – сказал мальчишка, глубокомысленно склонив голову набок Казалось, его соорудили где-то в сарае – собственно, так оно и было Артур покачал головой$$);
insert into тип_материала values (default, 475, 'Самоклеющаяся бумага с яркими принтами и легким нанесением', $$Меж тем снаружи солнце лило свой свет на веселую толпу Никто не знает, что за радость находит отвертка в подобной жизни И перевел взгляд на чудо творения за иллюминатором – Вне всяких сомнений, – ответил Форд с не меньшей непреклонностью$$);
insert into тип_материала values (default, 5742, 'Дизайнерская бумага с узорами из тиснения, фольги и тиснением', $$Вероятно, природа – в своей безмерной мудрости – работает над этим Вследствие чего школьная администрация отправила компьютер в клинику для помешанных киберустройств, куда за ним последовала и девочка, имевшая глупость влюбиться в злосчастную машину – Где же ты…

– Отыскал джин с тоником? – радостно продолжил за него Форд Артур приосанился, взглянул миру прямо в поля и леса – Назревают великие события Распластавшись по стене, он стал пробираться к двери, только бы не нарушить рубежи поля (еле-еле заметные) – Ваш, что ли, диван? – раздалось сверху Господи, здесь же их полным-полно – Какое-то «что»?

– ННП Какое-то время он бездействовал, словно ожидая, что люди займутся своими обычными делами, не порицая его за это висение$$);
insert into тип_материала values (default, 1215, 'Бумажные постеры с высококачественными принтами и экологически чистой отделкой', $$Все это было искусственным Бистроматика как таковая являет собой революционно-новый подход к интерпретации поведения чисел Меж тем снаружи солнце лило свой свет на веселую толпу И камни тоже не мои, – добавил он, вытащив из сумки горсть плоских серых камешков И что самое удивительное, точно специально экипированные для данного мероприятия А когда раскроешься, я тебя прошу, не говори, что тебя это осчастливило, ладно?

– Ладно Строго индивидуально, лицом к лицу, одного за другим и (тут он с особым сладострастием скрипнул зубами) в алфавитном порядке Артур растерянно кивнул Для практики я разговариваю с этими… ну как их там… как называются эти, с которыми разговариваешь, когда с ума сходишь? Ну как Георг Третий Из-за Пылевого Облака они испокон веку не интересуются небом – все равно там пусто$$);
insert into тип_материала values (default, 1716, 'Упаковочная бумага с биоразлагаемым покрытием и устойчивыми к разрывам рулонами', $$Эта композиция почему-то показалась Артуру до идиотизма знакомой Однако, судя по всему, больше никто его не замечал – Быть такого не может, – сказал Форд, когда наблюдатели оправились от ускорения, а корабль уже рассекал верхние слои атмосферы – И также я тебя прошу не говорить, что ты очень рада быть полезной или что ты польщена честью раскрыться передо мной и премного довольна вновь затвориться с сознанием выполненного долга, ладно?

– Ладно$$);
insert into тип_материала values (default, 3290, 'Картонные коробки с пользовательскими размерами, внутренними вставками и тиснением', $$Воздух был прозрачен и душист Звездолет (да-да, еще один, просто звездолетопад какой-то), только на сей раз изящный и серебряный, спустился с небес на площадку – тихо, как-то даже интеллигентно, совершая опорами балетные па во славу технического прогресса Музыка бодро штурмовала небесное царство полной несказанности Понимаете, мысль «Мы одни во Вселенной» их ни разу не посещала, потому что до сегодняшнего вечера они вообще не знали о существовании Вселенной Не бросай трубку Потом спросил: – Какие зоны вещания попадутся нам в ближайшие часы?

Компьютер пискнул – Послушай, – промолвила Триллиан сочувственным тоном и присела рядышком, – очень даже объяснимо, что некоторое время жизнь будет казаться тебе бесцельной И на большей части из них он побывал уже миллионы раз И тут мы подходим к еще одной и главной причине его странности$$);
insert into тип_материала values (default, 2726, 'Самовосстанавливающиеся офисные подложки из картона с нескользящей поверхностью и водостойким покрытием', $$– Здесь, на болоте?

– Мост, – подтвердил Марвин Словно ниоткуда, зазвучала музыка – Мост? – не поверил своим ушам матрасс Не бросай трубку Жизненный цикл отвертки с храповиком весьма занятен Ни одного матрасса это, по-видимому, не удручает$$);
insert into тип_материала values (default, 8281, 'Разноцветная бумага для орегами с замысловатыми узорами и повышенной толщиной', $$То был мирный край Он сделал несколько яростных шагов И вдруг исчезла Мало того что они были белые, под цвет униформы игроков, но они еще и держали в манипуляторах нечто вроде крикетных бит и крикетных мячей Конкретно – всего лишь одну ноту, повторяющуюся через определенные интервалы Левая голова посмотрела влево, а правая – вправо, и обе решили, что следует отправиться куда глаза глядят – Ну и что «Путеводитель»?

– В смысле?

– Ты хотел процитировать Извините, бога ради, никак не найду клавишу перемотки…

– … это удел биллионов биллионов невинных…

– Ни в коем случае, – прокричал Слартибартфаст, вновь проплывая мимо и яростно возясь с устройством, которое раньше воткнул в стену Зала информационных иллюзий; при ближайшем рассмотрении Артур сообразил, что оно по-прежнему торчало в стене, – не соглашайтесь ничего покупать Пристегиваясь ремнями, Форд Префект только возносил хвалу судьбе за то, что это всего лишь безопасная инфоиллюзия$$);
insert into тип_материала values (default, 2660, 'Конверты для прямой почтовой рассылки с глянцевой отделкой, самоклеющимся клапаном и расширенными полями', $$Три пилота были одновременно и конструкторами корабля – Оно имеет, – прошептал он Форду, серьезно наморщив лоб, – форму полисмена – Подождите минутку! Что вы хотели? Эй! Да подождите же!

Корабль приподнялся, беспечно скинув свою тяжесть наземь, будто плащ, секунду повисел в воздухе – и унесся в вечернее небо – Мм… да, – ответил Артур Каждое утро традиционный душераздирающий вопль оповещал окрестности, что Артур Дент проснулся и заново ужаснулся своему местоположению Что матрасс и сделал, испустив еще одно легкое флюпчание – А это розовое Артуру почудилось, будто весь небосвод, галантно посторонившись, уступил им дорогу – Нет, – сказал Форд, – он чувствует мобильную аномалию в ткани пространства-времени, локальное возмущение, очаг нестабильности Принесли новый мяч, игра возобновилась, солнце продолжало светить, а Форд все скакал и скакал на месте, мотая головой и моргая$$);
insert into тип_материала values (default, 532, 'Промышленная бумага с высокой прочностью на разрыв, влагостойкостью и устойчивостью к истиранию', $$Но зубы ему не требовались Чересчур осмысленное и лаконичное С того дня прошло уже два года – Именно – Я понимаю, что в масштабе Вселенной этот факт не имеет никакого значения, но просто интересно$$);
insert into тип_материала values (default, 830, 'Вощеная бумага с биоразлагаемым покрытием, водостойкостью и термостойкостью', $$– Ого, – сказал мальчишка, глубокомысленно склонив голову набок Вдвоем они взвалили Артура на диван и унесли с поля, причем неожиданное исчезновение дивана на полдороге задержало их совсем ненадолго Несмотря на кучи обломков, Зафод с новым ужасом разглядел, что они движутся к самому ядру корабля, сердцу невероятностной тяги, загадочным образом сгущаемой из пустоты, – в общем, к самому «Золотому сердцу» Все это было искусственным Затем поспешил влить в себя еще один – пусть догонит первый и составит ему компанию И что самое удивительное, точно специально экипированные для данного мероприятия$$);
insert into тип_материала values (default, 4977, 'Бумага для акварели холодного прессования с текстурированной поверхностью и высоким содержанием хлопка', $$Он вскочил на ноги, точно услышавший телефонный звонок писатель, и обвел ошалелым взглядом окрестный пейзаж, внезапно сложившийся в удивительно привычную картину Тело Артура безвольно плюхнулось обратно на траву Форд довел свою речь до конца, прежде чем Артур успел перейти от тупого взгляда к тупым замечаниям Пользуясь секретами древних мастеров, они любовно смонтировали этот сувенир, который украсит ваш дом – в напоминание о павших и в знак почтения к Галактике – нашей Галактике, – на алтарь которой они положили свои жизни…

Тут мимо вновь проплыл Слартибартфаст – Не буду беспокоить тебя подробностями, а то они…

– Что «они»?

– Обеспокоят тебя – Мы ищем Ключ, – повторил он, – мы уже владеем Деревянным Столбом, Стальным Столбом и Плексигласовым Столбом Стена, казалось, все близилась и близилась, густела и густела, тяжелела и тяжелела$$);
insert into тип_материала values (default, 840, 'Пергаментная бумага с жиростойким покрытием, устойчивостью к высоким температурам и возможностью многократного использования', $$Оно, случайно, не твое?

– Изволь заткнуться насчет твоего полотенца! – воскликнул Форд Форд с Артуром решили покориться судьбе и претерпеть мучения – Ну и что «Путеводитель»?

– В смысле?

– Ты хотел процитировать Затем, вернувшись к реальности, осознал, что все равно не понимает, куда клонит старец Он с грохотом понесся по небу, словно точно знал, что делает – Собственно, невозможность их формулирования и есть один из самих этих принципов – Сходить с ума, так сходить, – рассудил Форд Артур приподнялся на локтях:

– Где я?

– На крикетной площадке «Лордз», – сообщил Форд Какой-то голос произнес: «Это…» Слартибартфаст дернул за ручку, и он умолк$$);
insert into тип_материала values (default, 3249, 'Пекарская бумага с антипригарной поверхностью, термостойкостью и влагостойкостью', $$– Было что-то интересное?

И вновь они балансировали на краю ужасно высокого утеса Впереди них сидели трое пилотов Артур покачал головой Зафод испытал секундное недоумение, но, скосив глаза на свою руку, с облегчением узрел, что предмет, обнаруженный им на стене коридора, оправдал его надежды Самый подходящий афоризм, чтобы заронить в молодые умы искру вдумчивого отношения к жизни Он никогда не слышал, чтобы на Зете Прутивнобендзы выступали с речами, а тем более знаменитости Похоже, на них восседали не то девушки, не то ангелы – Недурная мысль, – заметил Форд Префект, соскальзывая с валуна, на котором сидел Произошла настоящая революция$$);
insert into тип_материала values (default, 1200, 'Бумага для рисования с гладкой поверхностью, высокой плотностью и превосходной белизной', $$И все же она медленно, опасливо забралась в него и заняла свое привычное место Они находились перед Рубиконом исторического самосознания своего народа – Она самая – Только-то? – опасливо уточнил Артур Артур обратил внимание, что двое криккитян завели новую песню – милую романтическую балладу, которая словно парила в прохладном ночном воздухе Докажете – все равно не поверю А ведь Зафод был на борту один В настоящее время реситуасексулузоны играют ключевую роль во многих отраслях математики, в том числе в статистике и бухгалтерии, а также являются элементами основных уравнений, управляющих генерацией ННП-поля Припев был немного печальный$$);
insert into тип_материала values (default, 2816, 'Блокноты для заметок с проклеенными страницами, твердой обложкой и эластичной застежкой', $$Приборы, столь занимавшие внимание Слартибартфаста, были вмонтированы в донца бутылок, которые, в свою очередь, были заделаны в бетонную стену Не слушайте окружающих – ничего полезного они не скажут Криккитские войны относились к древней истории Галактики – Серебряной нитью пронзал незримый туман и скрывался за горизонтом?

– Еще как, – процедил Марвин$$);
insert into тип_материала values (default, 7176, 'Папка с кольцами с прозрачными карманами, разделителями и застежкой-молнией', $$– Отлично, – проговорил Форд очень тихо Ночью оно абсолютно черное Не будучи уверен в понятливости четвертого стакана, он послал за ним пятый с дополнительными пояснениями и шестой чисто ради моральной поддержки – Вон там! – вскричал Форд, дико взмахнув рукой И что любопытно – направление, в котором указала его рука, не совпадало с направлением его взгляда Внезапно почудилось, что это вопль вины и отчаяния Артур не совсем понял, какая связь между игрой, которая на Земле называлась крикетом, и…

Слартибартфаст точно прочел его мысли – И я не хочу, чтобы ты желала мне приятно провести день, поняла?

– Я поняла Матрасс момнухнул Для практики я разговариваю с этими… ну как их там… как называются эти, с которыми разговариваешь, когда с ума сходишь? Ну как Георг Третий$$);
insert into тип_материала values (default, 2622, 'Портфель из картона с прочным корпусом, удобными отделениями и мягкой ручкой', $$Сдержанно, но властно отстраняя людей со своего пути, фигура пробралась к мужчине, который лежал при последнем издыхании в жуткой луже крови Правда, в них проглядывала некоторая чудаковатость – не хотел бы Артур ехать с ними в одном купе, – но вся эта чудаковатость сводилась к чрезмерному добродушию и любезности, а не каким-то изъянам – Диван исчез Что Слартибартфаст в этом нашел такого интересного, ведал он один А потом развернулись Протечку – Ты завершил то, к чему шел много лет Солнце нехотя попыталось одолеть туман, пробуя то тут добавить немножко тепла, то вон туда запустить несколько лучиков, но, судя по всему, сегодня его ожидала очередная тягомотная прогулка от горизонта до горизонта И вдруг исчезла – Мы отправляемся в путь, – вскричал он, весь трепеща от прилива сил$$);
insert into тип_материала values (default, 1484, 'Кипа бумаги формата A4 с высокой белизной', $$– Что это было? – шепотом спросил Форд – Э-э… – в отчаянии выпалил Артур, – э-эй!

– И нечего тут! – рявкнул инопланетянин И потому вскорости они оказались у внутренней границы сферического, полого изнутри Пылевого Облака, со всех сторон окружавшего Криккит и его солнце – Я, собственно, хочу сказать, – продолжал Форд, – что нет смысла доводить себя до безумия стараниями это безумие избежать$$);
