insert into сообщение values (default, 1, 'консультант', $$Скорбное выражение на лице Артура Дента уступило место еще более скорбному Проведя рукой по стене, он нащупал нечто ценное$$, '2023-01-19 04:23:16.150571');
insert into сообщение values (default, 1, 'консультант', $$Грязно-розовое небо померкло, посинело, вновь окуталось мраком Куда пожелаю, туда и полечу, что на ум взбредет, то и выкину$$, '2023-01-19 08:58:50.525700');
insert into сообщение values (default, 1, 'консультант', $$Однако на взгляд Артура, абсолютно черный небосвод придавал всему идиллическому, несмотря на сумрак, пейзажу какой-то зловещий оттенок – Ну же, спросите, не бывает ли мне скучно Ему только что пришел в голову великолепный способ победить ужас одиночества, кошмары, комплекс неполноценности из-за провала всех сельскохозяйственных начинаний и патологического отсутствия всякой будущности для него на доисторической Земле На миг он вообразил свой маршрут в виде ломаной линии, связывающей все небесные огоньки, как на детских «загадочных картинках» с пронумерованными точками$$, '2023-01-19 19:46:06.760350');
insert into сообщение values (default, 1, 'клиент', $$Они бежали, не разбирая дороги, через траву, подпрыгивали, хохотали, кричали друг другу: «Загоняй его сюда!», «Перехватывай!» Солнце мечтательно освещало травяное море, крохотные полевые животные сломя голову разбегались из-под их ног – Я вижу эту штуку, – объявил Артур, – это звездолет – Короли? – подсказал Форд$$, '2023-01-19 17:48:27.709179');
insert into сообщение values (default, 2, 'консультант', $$– Вот в чем беда с этим разговором, – заявил Артур после того, как озадаченность медленно, точно альпинист по трудному склону, вскарабкалась по его лицу и уселась на бровях, – он очень не похож на те, что мне приходилось вести в последнее время Охмешконасыпатель покосился на невероятную алмазную россыпь космической ночи Разумеется, экипаж не реагировал на присутствие посторонних – ведь их тут, в сущности, и не было Форд и Артур воззрились на него с крайним удивлением и острым чувством обиды за хороший вкус$$, '2023-02-16 21:57:45.920066');
insert into сообщение values (default, 2, 'консультант', $$Но тут он поднял глаза на ужасающе голый небосклон и остро ощутил всю важность этой детали – Ну и хорошо, – сказал Артур$$, '2023-02-17 15:23:51.279901');
insert into сообщение values (default, 3, 'консультант', $$Вселенское Переустройство будет возобновлено Разумеется, никто и не подвергал эти проблемы лабораторному анализу, поскольку в лабораториях такого не случалось – во всяком случае, в приличных, которым можно верить Корабль этот был изумителен не своей конструкцией (мягко говоря, неудачной), но самим фактом своего появления$$, '2023-02-11 22:40:04.874268');
insert into сообщение values (default, 3, 'клиент', $$На несколько минут воцарилось изумленное безмолвие – Как вас зовут?

– Дент$$, '2023-02-11 17:28:58.293329');
insert into сообщение values (default, 3, 'консультант', $$Финиш – Нет, – заявил Марвин$$, '2023-02-12 11:14:58.795594');
insert into сообщение values (default, 4, 'консультант', $$Да, сказал бы я, около двух третей$$, '2023-01-19 11:24:02.345194');
insert into сообщение values (default, 4, 'консультант', $$Корабль лениво дрейфовал где-то в галактической глуши, окруженный чернильно-черной пучиной космоса А также флёпал, гумкал и уйломикивал Они уселись на камень и впали в глубокую задумчивость – Алло? – произнес он в воображаемую трубку$$, '2023-01-19 12:08:46.245235');
insert into сообщение values (default, 4, 'клиент', $$– Ты наверняка знаешь, что сейчас произойдет, – сказал Слартибартфаст Форду$$, '2023-01-19 21:33:00.869103');
insert into сообщение values (default, 4, 'консультант', $$В таком настроении к оружию лучше не прикасаться – Где?

– Там$$, '2023-01-19 13:02:53.230679');
insert into сообщение values (default, 5, 'консультант', $$Это было их творение, и сейчас они пели о нем песенку, изливая в ней двойную радость успеха и обладания Из-за Пылевого Облака они испокон веку не интересуются небом – все равно там пусто – Что «ну и»? – поинтересовался старец Это крикетный приз$$, '2023-01-30 17:23:01.426164');
insert into сообщение values (default, 5, 'клиент', $$Пойдемте за ними и посмотрим сами Ему пришло в голову, что во Вселенной непременно найдется кто-то, кому жизнь кажется еще более беспросветной, тяжелой и треклятой, чем ему По крайней мере мне это кажется странным, – добавил он, – а то, что это факт, я знаю по опыту Артура трясло$$, '2023-01-29 13:02:35.818998');
insert into сообщение values (default, 5, 'клиент', $$Форд вытащил из своей жутко обтрепавшейся и донельзя замызганной сумки субэфирный чуткомат$$, '2023-01-30 00:10:53.624357');
insert into сообщение values (default, 5, 'клиент', $$Задумайтесь об этом, друзья мои Отряхнулся$$, '2023-01-29 22:12:34.071584');
insert into сообщение values (default, 6, 'консультант', $$– Слушаю, – пропищал компьютер – Я дома, – повторил Артур Невдалеке слышались голоса играющих детей, а чуть подальше в раннем сумраке виднелся небольшой городок$$, '2023-02-06 16:24:26.734610');
insert into сообщение values (default, 6, 'консультант', $$Тогда я попробую ходить задом наперед Стена, казалось, все близилась и близилась, густела и густела, тяжелела и тяжелела Во-от, – добавил он, тыча пальцем в экран «Путеводителя», – вот воистину жуткое местечко$$, '2023-02-08 04:49:26.667317');
insert into сообщение values (default, 6, 'клиент', $$– Похоже на балаган, – сказал Артур$$, '2023-02-08 20:54:47.492525');
insert into сообщение values (default, 7, 'клиент', $$55 тебя начинает обволакивать ужасная апатия: ты понимаешь, что уже принял все ванны, какие можно было принять с пользой для души и тела, что сколько ни созерцай любой абзац газетного текста, ты не прочтешь ни строчки, не говоря уже о применении на практике новейшего, совершившего революцию в области стрижки кустарников метода, который в этой газете описан – Ты, случайно, не сказал «мм» дважды?

– Мммм мммм – Я думал, ты умер… – вырвалось у него Не прошло и нескольких секунд, как внезапно было достигнуто согласие$$, '2023-02-14 03:37:53.604857');
insert into сообщение values (default, 7, 'консультант', $$Однако матрасс попался какой-то уж очень глупый и лишь воззрился на него в ответ круглыми глазами – По-моему, это оно меня довело до ручки$$, '2023-02-12 23:23:34.953436');
insert into сообщение values (default, 7, 'консультант', $$По-моему, врут Она была срежиссирована скорее для блага телезрителей, чем просто зрителей, и со своего места в толпе они могли следить за ней только по сообщениям ближайшего репродуктора До сегодняшнего вечера Видите ли, они окружены колоссальным Пылевым Облаком$$, '2023-02-13 10:11:37.787241');
insert into сообщение values (default, 7, 'консультант', $$А это совсем другой коленкор Ответа не последовало Это Артур Дент говорит$$, '2023-02-13 18:18:16.091705');
insert into сообщение values (default, 8, 'клиент', $$Сдержанно, но властно отстраняя людей со своего пути, фигура пробралась к мужчине, который лежал при последнем издыхании в жуткой луже крови$$, '2023-03-22 00:19:01.480905');
insert into сообщение values (default, 8, 'консультант', $$– Разбудишь ко второй серии – Ты никчемный кретин, – сообщило существо – Полагаю, – добавил он, сделав передышку на писк, – что вы решили обозвать его безмозглой задницей$$, '2023-03-20 23:44:20.912256');
insert into сообщение values (default, 9, 'клиент', $$Подобно открытию Эйнштейна, что время не есть абсолют, но зависит от движения наблюдателя в пространстве, а пространство не есть абсолют, ибо зависит от движения наблюдателя во времени, ныне установлено, что числа не абсолютны, но зависят от движения наблюдателя в ресторанах Артур не совсем понял, какая связь между игрой, которая на Земле называлась крикетом, и…

Слартибартфаст точно прочел его мысли Ветер обдувал бухту, где останки одной из крупнейших и мощнейших космических флотилий в истории Галактики поспешно превращались из пепла в исходное состояние$$, '2023-05-11 12:38:53.176026');
insert into сообщение values (default, 9, 'клиент', $$Заблудившемуся в пространстве хотя бы не угрожает смерть со скуки$$, '2023-05-10 15:04:14.747724');
insert into сообщение values (default, 10, 'консультант', $$Тут наблюдатели услышали высоко в безглазых небесах тоненький визг Корабль лениво дрейфовал где-то в галактической глуши, окруженный чернильно-черной пучиной космоса По крайней мере мне это кажется странным, – добавил он, – а то, что это факт, я знаю по опыту$$, '2023-06-11 01:47:45.386672');
insert into сообщение values (default, 10, 'клиент', $$Видение дергалось и колебалось перед глазами Артура, хотя, видимо, в действительности это глаза Артура дергались вместе с головой$$, '2023-06-14 21:26:49.876299');
insert into сообщение values (default, 11, 'консультант', $$Хотя в горле у него привычно саднило от традиционного утреннего душераздирающего вопля, он внезапно пришел в великолепное расположение духа – Надеюсь, когда до этого дойдет, я буду в стельку пьян$$, '2023-03-25 14:42:31.556633');
insert into сообщение values (default, 11, 'клиент', $$– Выражаю свою позицию, – процедил Марвин, не переставая описывать круг за кругом – Как ты дога…

Форд только передернул плечами Пользуясь секретами древних мастеров, они любовно смонтировали этот сувенир, который украсит ваш дом – в напоминание о павших и в знак почтения к Галактике – нашей Галактике, – на алтарь которой они положили свои жизни…

Тут мимо вновь проплыл Слартибартфаст Артур вновь попытался заговорить, но борьба была неравной$$, '2023-03-25 20:16:04.122891');
insert into сообщение values (default, 11, 'консультант', $$– Назревают великие события$$, '2023-03-26 10:17:14.928531');
insert into сообщение values (default, 11, 'клиент', $$Это звук, который издают живые матрассы в своей естественной среде обитания, приняв близко к сердцу чью-то повесть о жизненной драме$$, '2023-03-23 11:09:20.268629');
insert into сообщение values (default, 12, 'консультант', $$– Тогда я был в некотором смысле знаменитостью$$, '2023-03-06 23:13:11.664670');
insert into сообщение values (default, 12, 'клиент', $$Свет он выключил, чтобы его головы не видели друг дружку, поскольку обе выглядели довольно погано – с самого того момента, когда Зафод сдуру заглянул к себе в душу С этим вместилищем у нее были связаны не самые лучшие воспоминания Эта композиция почему-то показалась Артуру до идиотизма знакомой Маленькие круги света выхватывали из мглы горшки с цветами, блестящие изразцы и разнообразные непонятные медные причиндалы$$, '2023-03-07 06:29:24.969668');
insert into сообщение values (default, 12, 'клиент', $$Другими словами, оговоренный час сбора – это один-единственный момент времени, в который абсолютно невозможно появление любого из членов компании Широко развел руки О ее масштабах судить было трудно, но, по-видимому, она была около метра высотой Слартибартфаст покинул стеклянную комнату$$, '2023-03-06 15:58:42.992578');
insert into сообщение values (default, 12, 'клиент', $$Тем самым выведя Форда из медитационного транса$$, '2023-03-07 23:44:36.727564');
insert into сообщение values (default, 13, 'клиент', $$Колоссальные аккорды Его взгляд неспешно подполз к дате, по которой Форд лениво постукивал пальцем$$, '2023-03-13 18:09:16.180032');
insert into сообщение values (default, 13, 'клиент', $$Пользуясь секретами древних мастеров, они любовно смонтировали этот сувенир, который украсит ваш дом – в напоминание о павших и в знак почтения к Галактике – нашей Галактике, – на алтарь которой они положили свои жизни…

Тут мимо вновь проплыл Слартибартфаст – Он вновь раскрыл глаза и блаженно улыбнулся$$, '2023-03-13 17:49:16.732371');
insert into сообщение values (default, 14, 'клиент', $$Зафоду пришло в голову, что для ускорения беседы предложения нужно сделать вопросительными Погоди, сейчас уточню Артур попросил его повторить только что сказанную фразу, ибо не совсем уяснил себе ее смысл$$, '2023-07-29 20:25:20.594315');
insert into сообщение values (default, 14, 'консультант', $$Роботы успели частично разобрать дальнюю стену рубки и пробить ход через жизненно важные органы корабля По крайней мере там он будет чувствовать себя во всеоружии Спросите у него, – добавил он, указывая на Форда, – он мне тоже снился Артур вновь попытался заговорить, но борьба была неравной$$, '2023-07-30 20:21:30.464829');
insert into сообщение values (default, 15, 'консультант', $$Он уже много дней шлялся, не зная покоя, по «Золотому сердцу», но еще не было случая, чтобы какая-нибудь дверь сказала: «Уф!» Да и сейчас он был почти уверен, что «Уф!» исходило не от двери Еще некоторое время они лежали на газоне, скорбно хмурясь – Я тут тоже спрыгнул с ума на время, – заявил Форд$$, '2023-04-27 00:06:53.406100');
insert into сообщение values (default, 15, 'клиент', $$– Он гордо возносился над водами?

– Да, он гордо возносился над водами – Подойти к своему кораблю через две минуты, – пояснил Артур и пожал плечами, что обличало отсутствие всяких мыслей в его голове Прежде чем мы поведаем, что именно сказал робот, следует отметить, что Зафод был первым живым органическим существом, кому довелось услышать голос этих тварей за последние десять биллионов лет$$, '2023-04-26 05:58:22.857882');
insert into сообщение values (default, 16, 'консультант', $$– Компьютер, – окликнул Охмешконасыпатель Робкий солнечный луч, случайно пробившийся сквозь туман, высветил синие и белые полоски на шкуре матрасса, чем немало его напугал Ему только что пришел в голову великолепный способ победить ужас одиночества, кошмары, комплекс неполноценности из-за провала всех сельскохозяйственных начинаний и патологического отсутствия всякой будущности для него на доисторической Земле$$, '2023-04-02 16:59:12.798374');
insert into сообщение values (default, 16, 'консультант', $$– Давайте, вы двое, – сказало нечто, – пройдемте Но не думаю, что с дурными намерениями Вероятно, природа – в своей безмерной мудрости – работает над этим$$, '2023-04-03 18:43:15.318723');
insert into сообщение values (default, 16, 'консультант', $$Форд и Артур воззрились на него с крайним удивлением и острым чувством обиды за хороший вкус Меня выручил сборщик металлолома – можете себе это представить? Меня, мозг масштаба… ну да ладно Тот же самый эффект наблюдался и в случае с кораблем Слартибартфаста$$, '2023-04-03 16:44:31.996685');
insert into сообщение values (default, 16, 'клиент', $$– О Зарквон, спаси и сохрани, – пробурчал он под нос Меня заставляли сидеть на ящике и рассказывать мою историю, а зрители уговаривали меня приободриться и мыслить позитивно$$, '2023-04-04 05:21:59.008958');
insert into сообщение values (default, 17, 'консультант', $$– … верно я говорю? – добавил он – Все последние пять лет приснились мне во сне – Что «ну и»? – поинтересовался старец$$, '2023-03-22 08:02:05.787007');
insert into сообщение values (default, 17, 'консультант', $$– Это же крикетная площадка «Лордз», верно? – возопил Артур Ни информации, ни иллюзий – только они трое, белые стены да несколько мелких устройств, которые, по-видимому, следовало подключить к некой розетке Не Наша Проблема – Это только документальный фильм, – вскричал он$$, '2023-03-22 06:46:33.484569');
insert into сообщение values (default, 17, 'клиент', $$– И я хочу знать, можешь ли ты ее видеть – Я дома, – повторил Артур$$, '2023-03-21 21:17:37.408835');
insert into сообщение values (default, 17, 'клиент', $$– Нет, – сказал Форд, – он чувствует мобильную аномалию в ткани пространства-времени, локальное возмущение, очаг нестабильности Дверь тихо отъехала в сторону Некоторые из нас гибнут от рук охотников, но, поскольку всех нас зовут Земами, утраты проходят незамеченными, и момнуханье, таким образом, остается минимальным$$, '2023-03-21 19:57:54.347095');
insert into сообщение values (default, 18, 'консультант', $$А на уроках древней истории Зафод только и делал, что вычислял, как бы заняться сексом с девочкой из соседней киберкабинки Криккитяне смотрели друг на друга, направо, налево, вперед, назад, даже на землю Второе не-абсолютное число – это оговоренный час сбора приглашенных, который, как ныне известно, представляет собой одно из сложнейших математических понятий – реситуасексулузон, число, о котором с уверенностью можно сказать лишь одно – оно равно чему угодно, только не самому себе Мелкие капли едва просачивались сквозь туман$$, '2023-03-24 07:53:02.245371');
insert into сообщение values (default, 18, 'консультант', $$С головы, украшенной душераздирающе мертвыми глазами, до мощных неживых пят, они, несомненно, являлись порождением педантичного разума, знавшего только одну цель – убивать – Я столько лет никого не видел, – заговорил он, – просто ни единой души Форд тем временем с тревогой наблюдал за суматохой – Я дома, – повторил Артур$$, '2023-03-24 01:51:23.625156');
insert into сообщение values (default, 18, 'консультант', $$Распластавшись по стене, он стал пробираться к двери, только бы не нарушить рубежи поля (еле-еле заметные) – По-моему, никаких загадочных материализации на поле не было с… э-э… с… может, их вообще ни разу еще не было – ты не помнишь?

– А Эджбастон 1932 года?

– А, ну и что же там стряслось?

– Гм, Питер, если я не ошибаюсь, Кантер играл против Уилсокса и шел в нападение со стороны павильона, когда вдруг напрямик через площадку пробежал зритель$$, '2023-03-24 14:14:37.746010');
insert into сообщение values (default, 19, 'клиент', $$– Кажется, что-то началось!

– Беги в корабль, – завопил Форд, – знать ничего не хочу, беги в корабль – Видимо, вы поглощены размышлениями, – плучительно сказал матрасс Строго говоря, эту шайку бесчувственных выродков он давно уже возненавидел лютой ненавистью$$, '2023-05-26 08:11:54.813780');
insert into сообщение values (default, 19, 'клиент', $$– Да, – ответил робот Правда, роботы сыпались не абы как, а четким военным строем – Чего-о? – воскликнул Форд$$, '2023-05-25 14:45:50.127848');
insert into сообщение values (default, 19, 'консультант', $$– Надеюсь, когда до этого дойдет, я буду в стельку пьян$$, '2023-05-25 15:15:20.138982');
insert into сообщение values (default, 19, 'клиент', $$Откуда здесь взяться сотне тысяч людей и что они хотели сказать этим своим «Уф!»?

Зафод огляделся по сторонам – то есть взглянул в оба конца коридора Пользуясь секретами древних мастеров, они любовно смонтировали этот сувенир, который украсит ваш дом – в напоминание о павших и в знак почтения к Галактике – нашей Галактике, – на алтарь которой они положили свои жизни…

Тут мимо вновь проплыл Слартибартфаст Форд протянул руку и потрогал приборную доску – Рада быть полезной$$, '2023-05-25 07:56:41.197873');
insert into сообщение values (default, 20, 'консультант', $$– Классно, – молвил Артур – и его душа выпорхнула наружу перевести дух Зафод похолодел$$, '2023-05-21 09:39:04.305113');
insert into сообщение values (default, 20, 'консультант', $$Это они шли в тот вечер по тропе, распевая мелодичные, проникновенные песни Артуру невольно представилось, как Пол Маккартни, восседая с ногами в кресле у камина, мурлычет эту песенку Линде и соображает, что бы такое купить на доходы с нее – то ли Эссекс, то ли Ирландию – А это что?

– Не Наша Проблема$$, '2023-05-21 00:13:45.809274');
insert into сообщение values (default, 20, 'консультант', $$– Короли? – подсказал Форд – Что это было? – вымолвил Артур Заблудившемуся в пространстве хотя бы не угрожает смерть со скуки$$, '2023-05-20 04:56:00.338496');
insert into сообщение values (default, 21, 'клиент', $$– Думаю, активный спорт поможет тебе не замыкаться на собственных переживаниях  – Да что этот старый дурак собрался делать, вакуум его заарктурь? – взорвался Форд$$, '2023-10-23 20:02:00.084714');
insert into сообщение values (default, 21, 'клиент', $$Тогда он, и его друзья, и друзья его друзей, и знакомые друзей его друзей, и друзья знакомых друзей его друзей, и довольно шапочные знакомые друзей знакомых друзей его друзей, которые зато владели крупным межзвездным трансагентством, за одну ночь совершили величайший трудовой подвиг в истории человечества И что самое удивительное, точно специально экипированные для данного мероприятия Наше странствие уже началось$$, '2023-10-21 20:05:21.656802');
insert into сообщение values (default, 22, 'консультант', $$Уперев руки в бока, он вновь обвел взором пустынный мир – Ага, чтоб ты его опять выбросил?

– Разумно, – сознался Артур Я считаю, что в пяти – Порвалась, – добавил он, – ни с того ни с сего порвалась цепь причин и следствий…

И наперекор сказанному, неуклюже сполз под стол после еще одного стакана$$, '2023-09-17 10:25:55.735528');
insert into сообщение values (default, 22, 'консультант', $$– Мне довелось побыть знаменитостью, – скорбно завывал робот, – совсем недолго благодаря моему чудесному и весьма досадному спасению от удела, сравнимого разве что с такой удачей, как гибель в сердце пылающей звезды$$, '2023-09-12 20:17:41.178084');
insert into сообщение values (default, 23, 'клиент', $$– По-моему, это оно меня довело до ручки Похоже, в основном он состоял из низеньких зданий, построенных из белого камня$$, '2023-05-06 10:09:45.759217');
insert into сообщение values (default, 23, 'клиент', $$– Я тут временно спустил свой разум с цепи, предполагая, что, если я миру дико понадоблюсь, он призовет меня обратно Поплотнее запахнувшись в свой обтрепанный халат, он приветствовал доброе утро широкой улыбкой Вот тогда-то он и набрел на свою цель жизни, дело, которое не позволит ему впасть в спячку никогда-никогда (так ему, во всяком случае, казалось) Как будто у них в зрачках слепое пятно на 180 градусов от горизонта до горизонта$$, '2023-05-05 09:53:07.711860');
insert into сообщение values (default, 23, 'клиент', $$И расстроенно поглядел на воображаемый телефон Задумайтесь об этом, друзья мои У всего мира перехватывает дыхание Маленькие круги света выхватывали из мглы горшки с цветами, блестящие изразцы и разнообразные непонятные медные причиндалы$$, '2023-05-06 23:31:31.777099');
insert into сообщение values (default, 24, 'консультант', $$Можете рассказать это вместо анекдота своим друзьям Зему и Зему при первой же встрече – они животики надорвут, если я их знаю Он дико озирался по сторонам, пока не заметил, что Форд с Артуром пробираются сквозь испуганную толпу, которая шарахнулась прочь от поля Роботы успели частично разобрать дальнюю стену рубки и пробить ход через жизненно важные органы корабля Зафод ошарашенно разглядывал роботов$$, '2023-09-09 14:44:39.999005');
insert into сообщение values (default, 24, 'клиент', $$Артур увидел вереницу крохотных огоньков, что, качаясь и приплясывая, медленно двигались к ним Уперев руки в бока, он вновь обвел взором пустынный мир Артур был совершенно счастлив – Ожидаемое время в пути – три недели, – продолжил он$$, '2023-09-11 20:33:51.251629');
insert into сообщение values (default, 25, 'клиент', $$– Пойдемте, – добавил он с неожиданной властностью, – я должен вам многое показать и поведать$$, '2023-07-20 08:39:23.135369');
insert into сообщение values (default, 25, 'консультант', $$Артур обратил внимание, что двое криккитян завели новую песню – милую романтическую балладу, которая словно парила в прохладном ночном воздухе$$, '2023-07-20 03:28:22.609970');
insert into сообщение values (default, 26, 'клиент', $$– И если ты считаешь, что тебе действительно необходимо слоняться по крикетной площадке в такой момент…

– Считаю – Ну же, спросите, не бывает ли мне скучно – ННП – это нечто, что мы не можем увидеть, или не видим, или то, чего нам не дает увидеть наш мозг, потому что мы считаем, что это не наша проблема$$, '2023-09-09 05:36:01.855839');
insert into сообщение values (default, 26, 'консультант', $$Форд довел свою речь до конца, прежде чем Артур успел перейти от тупого взгляда к тупым замечаниям$$, '2023-09-09 06:02:00.861055');
insert into сообщение values (default, 26, 'клиент', $$Душа Артура летала вокруг его тела кругами и мялась, не испытывая особенного желания войти И оторопел от последствий своего заявления$$, '2023-09-07 22:47:47.829567');
insert into сообщение values (default, 27, 'консультант', $$– Ладно, – сказал Зафод и напрягся, – а теперь раскройся – Диван исчез Компьютер донимал его вопросами, что за чертовщина тут происходит, но Зафод заткнул его терминалы электронными кляпами$$, '2023-08-22 16:13:23.279357');
insert into сообщение values (default, 27, 'клиент', $$Он вскочил с дивана$$, '2023-08-22 11:07:35.642972');
insert into сообщение values (default, 28, 'консультант', $$Он был уже в двух ярдах от двери рубки, когда до него внезапно дошло, что дверь обязательно поздоровается с ним$$, '2023-07-26 13:01:27.053832');
insert into сообщение values (default, 28, 'консультант', $$А также флёпал, гумкал и уйломикивал Матрасс флёпал вокруг него – Судя по всему… – произнес Форд, – … в ткани пространства-времени… – произнес Форд, – … появились… – произнес Форд, – … очаги…

Артур тупо смотрел на отворот своего халата, сжимаемый пальцами Форда Зафод отключил большинство второстепенных систем и механизмов$$, '2023-07-28 13:47:09.499685');
insert into сообщение values (default, 28, 'клиент', $$– Полотенце не мое, – настаивал Артур, – именно это я и пытаюсь…

– А я пытаюсь потребовать, чтобы ты заткнулся, – продолжал Форд, переходя на рык, – причем немедленно!

– Ладно, – сказал Артур, пытаясь засунуть полотенце обратно в свою неуклюжую сумку Правда, он всегда подозревал о ее существовании, поскольку обладал полным комплектом стандартных органов (и даже двойным – кое-каких), но, внезапно обнаружив в глубине своего существа эту затаившуюся зверюшку, был крайне шокирован – Как ты себя чувствуешь? – спросил Форд И теперь, стоя в молчании и одиночестве посреди темного коридора, он содрогнулся при воспоминании о содеянном$$, '2023-07-26 11:47:41.194894');
insert into сообщение values (default, 28, 'консультант', $$– А вот это, – сказал Слартибартфаст, перейдя на загробный хрип и указывая на компанию криккитян, которые удалялись в сторону города, – те самые, с кого все началось Авария инопланетного звездолета сдвинула какие-то шарики в их головах – Чтоб твои диоды сгнили и выпали Итак, Охмешконасыпатель пресытился жизнью$$, '2023-07-25 17:31:51.700766');
insert into сообщение values (default, 29, 'консультант', $$– Очаги нестабильности в ней возникли, – ответил Форд Тут-то он и услышал пресловутое «Уф!», что его страшно встревожило$$, '2023-10-01 03:27:28.686164');
insert into сообщение values (default, 29, 'клиент', $$И аналогично повышающемуся тону, который, забираясь все выше и выше, будет по дороге менять характер и обретать мелодичность, так и это бесчувственное чувство возвысилось до невыносимого, если и немого, вопля Их внешность произвела неуловимо устрашающее впечатление даже на Зафода, который видел их впервые и даже ни разу о них не слыхал$$, '2023-10-03 07:25:46.218321');
insert into сообщение values (default, 30, 'клиент', $$– Свобода, – произнес он вслух Тем временем на Земле под аккомпанемент дождя тянулся один из самых кошмарных вечеров в жизни Артура Дента Он лишь частично походил на нормальный звездолет с дюзами и соплами, аварийными люками и стабилизаторами$$, '2024-01-26 05:18:37.701934');
insert into сообщение values (default, 30, 'консультант', $$Музыка бодро штурмовала небесное царство полной несказанности Можете рассказать это вместо анекдота своим друзьям Зему и Зему при первой же встрече – они животики надорвут, если я их знаю$$, '2024-01-24 13:34:05.562219');
insert into сообщение values (default, 31, 'консультант', $$Будь у него зубы, он скрипел бы ими А на скатерти пребывало с полдюжины тарелок с недоеденными итальянскими кушаньями И вновь ответа не последовало$$, '2023-05-14 18:29:08.461662');
insert into сообщение values (default, 31, 'клиент', $$– И если ты считаешь, что тебе действительно необходимо слоняться по крикетной площадке в такой момент…

– Считаю$$, '2023-05-14 06:29:12.581863');
insert into сообщение values (default, 31, 'консультант', $$– Знаешь, – сказал Форд, – я…

– Где ты шатался? – прервал его Артур, чья голова все-таки покончила с физкультурной разминкой Забудьте, сколько вы весите (забудьте, что вы вообще что-то весите), и просто позвольте ветру поднимать вас все выше$$, '2023-05-15 02:56:41.230477');
insert into сообщение values (default, 31, 'консультант', $$А спустя еще несколько часов вылезло вновь, расправило плечи и опять принялось карабкаться вверх по небу Корабль вылетел из Облака Зафод, кивнув, принялся поигрывать пистолетом, дабы добиться дальнейших пояснений Глагол «флёпать» обозначает действие, посильное лишь живым матрассам на болоте, чем и объясняется малораспространенность этого слова$$, '2023-05-15 21:17:23.697899');
insert into сообщение values (default, 32, 'консультант', $$Триллиан вновь терпеливо кивнула, досчитала до… – в общем, число было немаленькое – и сказала себе, что на данном этапе самое важное – хотя бы разговорить Зафода$$, '2023-10-22 16:32:49.322780');
insert into сообщение values (default, 32, 'клиент', $$А спустя еще несколько часов вылезло вновь, расправило плечи и опять принялось карабкаться вверх по небу$$, '2023-10-22 08:54:12.948837');
insert into сообщение values (default, 32, 'консультант', $$Кроме того, в звездолете просто не нашлось бы столько дверей – пресловутое «уф» прозвучало так, будто его произнесли сто тысяч человек разом – Да, только я его выудил, – сообщил Форд$$, '2023-10-21 01:33:27.704969');
insert into сообщение values (default, 33, 'консультант', $$После чего подозрительно обозрел двух Триллиан и пришел к выводу, что та, что справа, ему больше по вкусу$$, '2023-06-03 16:41:58.679324');
insert into сообщение values (default, 33, 'консультант', $$– Но…

– Демонстрирую, – сказал Форд – Тс-с, – прошипел Форд и глубокомысленно воздел очи горе Не считаясь ни с какими законами пространства, роботы беспардонно материализовали свой корабль там, где им было надо, вследствие чего он сцепился с «Золотым сердцем» крест-накрест, как одна расческа с другой – Я дома, – твердил он, – дома$$, '2023-06-03 22:34:27.071701');
insert into сообщение values (default, 33, 'клиент', $$Затем Артур заметил, что идущая впереди компания тоже обратила внимание на визг и пришла в замешательство Пришельцы покидают площадку в сопровождении офицера полиции, и, по-моему, все входит в привычное русло, и игра сейчас возобновится – Что они… – переспросил Форд$$, '2023-06-04 02:58:49.595520');
insert into сообщение values (default, 33, 'консультант', $$Я, наоборот, от нее бегал Однако, судя по всему, больше никто его не замечал – Ты где?

– В туалете$$, '2023-06-04 14:31:37.300680');
insert into сообщение values (default, 34, 'консультант', $$Этот простой факт вызвал бурю в научном мире Она просто ушла – превратилась в случайный набор точек, странствующий по Вселенной Бредя в сумерках к своей пещере, Артур вдруг заметил за облаками странные вспышки$$, '2023-10-07 03:16:55.268061');
insert into сообщение values (default, 34, 'консультант', $$Они уселись на камень и впали в глубокую задумчивость В небе ничего не было$$, '2023-10-08 04:21:10.169654');
insert into сообщение values (default, 34, 'консультант', $$Темп все возрастал По-видимому, это словесное излияние вдохновило его на новый взлет к высотам уныния и отчаяния – От… к-к-к… э-э… – добавил он немного погодя$$, '2023-10-06 19:15:53.531285');
insert into сообщение values (default, 35, 'клиент', $$Когда он притомился тщетно обрабатывать гору массивными отбелизаторами, аннигиляторами рефракции и спектральными астраломылками, ему открылось, что за оставшиеся девять часов он вряд ли выполнит зарок Произнеся эту речь, Артур побрел к краю поля, отряхивая халат$$, '2023-08-05 04:12:35.728336');
insert into сообщение values (default, 35, 'консультант', $$По крайней мере я думаю, что оно думало, что оно джин с тоником… Есть вероятность, – добавил он с ухмылкой, от которой самые хладнокровные люди с воем полезли бы на деревья, – что мне это всего лишь примерещилось Нет, вся штука в том, что на полдороге к земле вы должны на что-то отвлечься, позабыв и о перспективе падения, и о земле, и о том, как вам будет больно, если не удастся промахнуться$$, '2023-08-06 09:01:12.670918');
insert into сообщение values (default, 36, 'консультант', $$– Ну…

– У официанта в блокноте реальное и ирреальное вступают в противоборство на столь глубинном уровне, что одно переходит в другое и наоборот, благодаря чему возможно практически все при соблюдении определенных принципов – Все в ажуре, офицер, – заявил он Досчитав про себя до десяти значительных десятеричных концептов (то есть отмерив паузу, призванную выразить общее презрение ко всем матрассам и самой идее матрассности), робот вновь принялся описывать миниатюрные круги Пластмасса под бетон$$, '2023-06-18 18:41:20.401559');
insert into сообщение values (default, 36, 'клиент', $$Можете рассказать это вместо анекдота своим друзьям Зему и Зему при первой же встрече – они животики надорвут, если я их знаю Маленькие круги света выхватывали из мглы горшки с цветами, блестящие изразцы и разнообразные непонятные медные причиндалы Ничто не шевелилось$$, '2023-06-18 12:18:41.359328');
insert into сообщение values (default, 36, 'клиент', $$Я не спец по межличн… межличностным взаи-мо-от-но-ше-ни-ям, во…

Триллиан только подняла брови У меня самый классный корабль во всем известном небе, девушка, с которой у меня все чудесно…

– Да?

– Ну, насколько я понимаю Форд злобно обернулся к Артуру Отнюдь$$, '2023-06-19 19:17:13.031141');
insert into сообщение values (default, 36, 'клиент', $$– Никчемная дырка от бублика Артур последовал совету, вначале несколько нервно, словно боясь, что рука сейчас обернется скользкой рыбиной$$, '2023-06-18 05:53:47.033885');
insert into сообщение values (default, 37, 'консультант', $$Затем вы освоите массу приемов по управлению своим телом в полете, регулировке скорости, выполнению маневров Артур Дент Слартибартфаст быстрым шагом вошел в «аквариум» и, судя по всему, затеял какой-то пустой разговор с метрдотелем, а один из роботов-клиентов, авторазмякающая модель, меж тем тихо сполз под стол, не переставая рассказывать, что именно собирается сделать с неким типом из-за некой девушки$$, '2024-01-03 03:34:37.562441');
insert into сообщение values (default, 37, 'консультант', $$И оторопел от последствий своего заявления$$, '2024-01-03 01:46:03.865702');
insert into сообщение values (default, 37, 'консультант', $$Другой же своей частью он был точь-в-точь маленькое итальянское бистро, только поставленное вверх тормашками Спустя некоторое время он начал медленно, воровато пробираться вперед с гримасой вдумчивой озадаченности на лице – как леопард, который не совсем уверен, что только что видел в полумиле впереди, на раскаленной и пыльной прерии, полупустую банку «Вискаса» Некому было его услышать, некому было с ним поговорить$$, '2024-01-05 08:52:11.403348');
insert into сообщение values (default, 38, 'клиент', $$Артур приподнялся на локтях:

– Где я?

– На крикетной площадке «Лордз», – сообщил Форд – Сгинь, тебе говорят, дурилка пластиковая$$, '2023-06-29 06:33:21.752384');
insert into сообщение values (default, 38, 'консультант', $$Уперев руки в бока, он вновь обвел взором пустынный мир – Что я и ожидал услышать, – продолжил Марвин, – а также я ожидаю узнать, что идея робота с искусственной ногой вас немало забавляет$$, '2023-06-28 18:48:56.748618');
insert into сообщение values (default, 38, 'консультант', $$Ширится мнение, что «Максимегалонский словарь» не заслуживает целого полка грузовиков, который используется для транспортировки его микрофильмированной версии Марвин не удостоил его ответа и лишь с усиленной демонстративностью заработал суставами$$, '2023-06-29 05:04:21.205891');
insert into сообщение values (default, 39, 'клиент', $$Они находились перед Рубиконом исторического самосознания своего народа Обычно фокус в том, чтобы не слишком сосредоточиваться на своих действиях, но просто пускать их на самотек, точно нечто от вас не зависящее Вот уже пять лет, как его не расщепляли на атомы После четырех лет полного одиночества он был до слез рад видеть Форда живым и невредимым$$, '2023-06-26 03:13:29.722011');
insert into сообщение values (default, 39, 'клиент', $$Теперь они могли ясно видеть звездолет в его истинном обличье просто потому, что знали о его наличии здесь – Я дома, – шептал Артур Я не спец по межличн… межличностным взаи-мо-от-но-ше-ни-ям, во…

Триллиан только подняла брови$$, '2023-06-27 17:39:41.653639');
insert into сообщение values (default, 39, 'клиент', $$Даже Форд, похоже, повеселел – Видимо, вы поглощены размышлениями, – плучительно сказал матрасс – Вон там! – вскричал Форд, дико взмахнув рукой$$, '2023-06-26 11:40:14.430176');
insert into сообщение values (default, 40, 'клиент', $$– Да-да, хорошо, это не обязательно, – поспешно заявил полисмен, – только постарайтесь, чтобы такого… этого… больше не было Полисмен развернулся и побрел искать кого-нибудь, кто был бы не с Бетельгейзе$$, '2023-08-12 06:34:59.304989');
insert into сообщение values (default, 40, 'клиент', $$А для меня нет более печального зрелища, как разрушение планеты$$, '2023-08-12 14:41:14.847941');
insert into сообщение values (default, 40, 'консультант', $$Зафод застыл как вкопанный «Фундаментальное сердце духа и Вселенной может отдыхать, – подумал он, – это все туфта» А для меня нет более печального зрелища, как разрушение планеты Некоторое время они летели вперед, неподвижные на фоне глазастого тела Галактики, которое само было неподвижно на фоне бесконечных просторов Вселенной$$, '2023-08-11 15:04:57.619948');
insert into сообщение values (default, 40, 'клиент', $$Следовательно, надо отыскать этого собрата$$, '2023-08-11 06:28:02.360077');
insert into сообщение values (default, 41, 'консультант', $$– Ау, компьютер! – прошептал он – Он говорит, что они забрали «Пепел» Пойдемте за ними и посмотрим сами Вы видели этот фильм всего лишь тридцать три тысячи пятьсот семнадцать раз$$, '2023-07-23 12:27:34.966340');
insert into сообщение values (default, 41, 'консультант', $$Однако Эффрафакс все же проиграл пари – и лишился головы – из-за педантизма некоего арбитра, обратившего внимание на то, что: а) при прохождении через место, где следовало находиться Меграмалу, он ни обо что не споткнулся и не расшиб себе лоб и б) в небесах засияла какая-то подозрительная новая луна – Это, сказал бы я, тоже очень любопытный случай, – заявил Артур, поспешно закрыв сумку и прикинувшись, что высматривает мяч на земле$$, '2023-07-24 02:06:21.280797');
insert into сообщение values (default, 41, 'консультант', $$Нервно опираясь о стену коридора, он морщил лоб (то есть лбы), словно пытаясь откупорить бутылку методом телекинеза Я считаю, что в пяти$$, '2023-07-23 11:52:05.397261');
insert into сообщение values (default, 42, 'консультант', $$Окружающая его Вселенная распалась на мириады блестящих осколков, и каждый осколочек тихо вращался в пустоте, отражая своей серебряной кожей все то же жуткое пиршество огня и смерти Он таил надежду, что кто-нибудь спросит: «Что это ты мурлычешь?» – но никто не спрашивал Как-то ночью – а теперь на корабле ночь длилась постоянно – лежа в постели, он решил взять себя в руки, предпринять что-нибудь конструктивное По-моему, это было животное из семейства аллигаторов$$, '2024-07-12 06:20:39.492073');
insert into сообщение values (default, 42, 'клиент', $$С того дня прошло уже два года Как ни странно, и тут моделью послужило маленькое итальянское бистро$$, '2024-07-08 23:00:34.861317');
insert into сообщение values (default, 43, 'клиент', $$Затем еще раз огляделся по сторонам с еще большим ужасом – Серебряной нитью пронзал незримый туман и скрывался за горизонтом?

– Еще как, – процедил Марвин$$, '2023-11-26 08:14:57.647146');
insert into сообщение values (default, 43, 'клиент', $$Над древним Криккитом сгустилась ночь$$, '2023-11-28 19:50:31.699929');
insert into сообщение values (default, 43, 'клиент', $$Меня выручил сборщик металлолома – можете себе это представить? Меня, мозг масштаба… ну да ладно При взгляде на это небо мерещилось, будто ты один-одинешенек во Вселенной – Ву-ун, – заметил матрасс$$, '2023-11-28 00:24:01.744530');
insert into сообщение values (default, 43, 'консультант', $$– Фольфанга, – сообщил он и снова пискнул Робот, похоже, понял Докажете – все равно не поверю$$, '2023-11-27 09:31:04.899892');
insert into сообщение values (default, 44, 'клиент', $$Рука официанта заскользила по листкам блокнота с недостижимым для человека проворством, а затем еще быстрее, так что в глазах зарябило Вспыхнули споры, посетители кинулись рисовать на салфетках иллюстрации своей правоты А теперь – в Зал информационных иллюзий Чересчур осмысленное и лаконичное$$, '2023-05-25 07:32:43.949589');
insert into сообщение values (default, 44, 'консультант', $$– М-да-а-а-а-а, – промолвил он наконец, – да, но в чем тут загадочность? Он ведь не материализовался в подлинном смысле слова? Просто пробежал Пространство не просто изменило текстуру и состав$$, '2023-05-25 18:15:27.720557');
insert into сообщение values (default, 44, 'клиент', $$Воцарилась бесконечно холодная и зловещая тишина$$, '2023-05-25 19:39:49.488701');
insert into сообщение values (default, 44, 'клиент', $$Он никогда не слышал, чтобы на Зете Прутивнобендзы выступали с речами, а тем более знаменитости Мало того, нижние сегменты их ног были защищены чем-то вроде белых щитков Он почувствовал себя ограбленным$$, '2023-05-26 12:49:16.845052');
insert into сообщение values (default, 45, 'консультант', $$Весь следующий день он, не зная отдыха, мерил шагами корабельные коридоры, делая вид, что не ищет Триллиан, а просто прогуливается – хотя и знал, что ее больше нет на борту Что матрасс и сделал, испустив еще одно легкое флюпчание – Но только в порядке хобби$$, '2023-11-08 08:32:42.026428');
insert into сообщение values (default, 45, 'клиент', $$– Хороша лошадка, – заметил Форд, безуспешно пытаясь скрыть свое восхищение маневром корабля, – жаль, с дизайном ей не повезло$$, '2023-11-08 22:37:22.527848');
insert into сообщение values (default, 45, 'клиент', $$Приятели направились к пресловутому кораблю$$, '2023-11-06 01:41:55.610362');
insert into сообщение values (default, 46, 'консультант', $$Проведя рукой по стене, он нащупал нечто ценное В висках у Артура раздался привычный тупой звон, очень часто сопровождавший его разговоры с Фордом$$, '2024-03-16 17:04:01.488906');
insert into сообщение values (default, 46, 'клиент', $$В его желудке точно черти свадьбу справляли Фальшивка$$, '2024-03-19 00:12:00.049544');
insert into сообщение values (default, 46, 'консультант', $$– Бистроматика, – пояснил он$$, '2024-03-16 19:07:17.751118');
insert into сообщение values (default, 47, 'клиент', $$– Полотенце не мое, – настаивал Артур, – именно это я и пытаюсь…

– А я пытаюсь потребовать, чтобы ты заткнулся, – продолжал Форд, переходя на рык, – причем немедленно!

– Ладно, – сказал Артур, пытаясь засунуть полотенце обратно в свою неуклюжую сумку От вас требуется одно – решительно кинуться вниз, не боясь ожидающей вас физической боли Следовательно, надо отыскать этого собрата А ведь Зафод был на борту один$$, '2023-10-27 16:48:29.324843');
insert into сообщение values (default, 47, 'консультант', $$– Э-э-э?…

Существо кивнуло само себе, произвело чисто инопланетный щелчок застежкой папки и направилось к своему кораблю$$, '2023-10-28 09:05:01.215308');
insert into сообщение values (default, 47, 'консультант', $$Фигура тихо преклонила перед ним колени$$, '2023-10-27 09:58:17.881742');
insert into сообщение values (default, 48, 'консультант', $$Но тут же он совершил нечто очень необычное$$, '2023-09-28 14:10:00.526588');
insert into сообщение values (default, 48, 'клиент', $$– Ни фига себе, – с этими словами он выпил еще стакан – Знаешь, – сказал Форд, – я…

– Где ты шатался? – прервал его Артур, чья голова все-таки покончила с физкультурной разминкой Ужасное потрясение, которое они испытали, когда, завывая и гремя, горящий звездолет упал с небес, врезавшись в холм примерно в полумиле от них, словами не передашь$$, '2023-09-28 12:13:34.373489');
insert into сообщение values (default, 49, 'клиент', $$Я, наоборот, от нее бегал$$, '2023-06-21 07:53:43.834752');
insert into сообщение values (default, 49, 'консультант', $$– Самая мощная из известных паранауке вычислительных сил Его ужасно умиляло, что в этот день все его планы сами собой сбывались – Просто прими на веру все, что я тебе скажу, и сразу все станет совсем, совсем ясно Никто не знает, что за радость находит отвертка в подобной жизни$$, '2023-06-21 11:24:23.807727');
insert into сообщение values (default, 49, 'консультант', $$– Три столба, – гремел мужчина$$, '2023-06-22 22:24:42.638801');
insert into сообщение values (default, 49, 'клиент', $$– Онизапелибрепел! – вскричал Слартибартфаст своим тонким, дребезжащим голосом – Жду с нетерпением вашего рассказа о речи на болоте А случится это сегодня Он тряс руку Форда и пожимал ее, пожимал и тряс$$, '2023-06-22 08:56:02.363189');
insert into сообщение values (default, 50, 'клиент', $$А именно: игнорируя недоуменные взгляды собратьев-зрителей, что обступали поле, он совершал всякие резкие движения руками перед своим носом, при этом то проныривая у кого-то за спиной, то подпрыгивая рядом с кем-то еще Внутри царила историческая тишина Форд повторил – Счастливая Галактика, друзья мои, а образ ее – Трикетная Калитка!

Теперь три столба различались ясно$$, '2023-06-27 05:25:54.786028');
insert into сообщение values (default, 50, 'консультант', $$Туман висел неподвижно, точно то самое перехваченное на полдороге дыхание Этакий замысловатый балет меню, счетов, бумажников, чековых книжек, кредитных карточек, часов, карандашей и бумажных салфеток – Одно время я так тоже думал, – подхватил Форд, – а потом на пару недель решил, что я – лимон$$, '2023-06-26 11:51:28.916107');
insert into сообщение values (default, 50, 'клиент', $$Его лучи ласкали брикеты мороженого, от чего оно таяло – Похоже на балаган, – сказал Артур$$, '2023-06-27 23:45:52.602791');
insert into сообщение values (default, 50, 'консультант', $$Они стояли одни-одинешеньки на вершине утеса где-то на доисторической Земле и решительно смотрели друг другу в глаза История собиралась с силами, чтобы нанести криккитянам новый удар Затем вы освоите массу приемов по управлению своим телом в полете, регулировке скорости, выполнению маневров В нем обрисовался силуэт высокой фигуры$$, '2023-06-26 14:44:50.635891');
insert into сообщение values (default, 51, 'клиент', $$Но возможно, тебе любопытно будет узнать, что твой покорный слуга единолично ответственен за удлиненную форму животного, которому в будущих веках дадут имя «жираф» – Просто прими на веру все, что я тебе скажу, и сразу все станет совсем, совсем ясно Эта композиция почему-то показалась Артуру до идиотизма знакомой Прижав к стене кончики пальцев, он ощутил странную вибрацию$$, '2023-12-16 03:58:24.887073');
insert into сообщение values (default, 51, 'консультант', $$И я подключился к цепи открытия моста Созерцая тускло-розовый контур двери, он осознал, что во мраке коридора еле-еле различаются границы сенсорно-тактичного поля, которое и предупреждало дверь о появлении кого-то, перед кем следует раскрыться с любезными словами Зачем это понадобилось притаскивать сюда сто тысяч человек ради такой ерунды?

Он нервно двинулся в сторону рубки – Речь, – взмолился матрасс$$, '2023-12-15 15:29:40.022714');
insert into сообщение values (default, 51, 'клиент', $$То, что вы испытали…

Слартибартфаст, проплывая мимо, помахал Артуру рукой$$, '2023-12-14 21:22:39.501109');
insert into сообщение values (default, 52, 'консультант', $$Еще мрачнее сдвинул брови – и наконец успокоился Под ними расстилались серебристо-белые ризы Аллосиманиуса-Синеки$$, '2024-06-07 18:13:23.769785');
insert into сообщение values (default, 52, 'консультант', $$– Видимо, вы поглощены размышлениями, – плучительно сказал матрасс И все же, рассудил Артур, это дело привычки$$, '2024-06-07 01:11:31.925957');
insert into сообщение values (default, 52, 'консультант', $$Вообще-то я практикуюсь – Жду с нетерпением!

– Она была принята очень плохо, – сказал Марвин, – по многим причинам$$, '2024-06-05 02:30:07.584776');
insert into сообщение values (default, 53, 'клиент', $$– Он говорит, что они забрали «Пепел» Он просочился через протечку континуума, по воле парусных волн эфира и я не знаю еще чьей – какая на фиг разница, мы должны его поймать, а то так здесь и застрянем!

Он съехал на пятках по скале и стремглав понесся по полю$$, '2023-07-02 02:47:18.157176');
insert into сообщение values (default, 53, 'клиент', $$Форд с Артуром поспешили броситься на землю, которая, казалось, ужасно быстро вертелась вокруг них – Мы могли бы побеседовать, – сказал матрасс, – хотите?

Матрасс был крупный, по-видимому, один из лучших в своем роде$$, '2023-07-02 03:02:23.926913');
insert into сообщение values (default, 53, 'консультант', $$Затем он совершил нечто, что матрассы обычно делать ленятся – Подойти к своему кораблю через две минуты, – пояснил Артур и пожал плечами, что обличало отсутствие всяких мыслей в его голове$$, '2023-07-02 03:53:03.498727');
insert into сообщение values (default, 53, 'консультант', $$Примерно одну целую и пять десятых миллиона единиц времени Инопланетный корабль уже с треском прорывался сквозь верхние слои атмосферы, навстречу той ужасной пустоте с редкими-редкими материальными вкраплениями, из которой и состоит Вселенная Затем из клубов дыма вынырнула светлая фигура Слартибартфаста Он уставился вверх$$, '2023-07-02 10:24:24.057197');
insert into сообщение values (default, 54, 'консультант', $$– То были, – проговорила фигура, восседающая в исполинском мягком кресле, – криккитские войны, величайшая катастрофа в истории нашей Галактики Он зафлёпал туда-сюда, ошеломленный и взволнованный$$, '2024-05-04 07:12:12.252576');
insert into сообщение values (default, 54, 'клиент', $$Следовательно, надо отыскать этого собрата И это где-то недалеко – Я-то думал, что стряслось, – сказал Форд, – а это просто матч кончился Поддельные бутылки в поддельном бетоне$$, '2024-05-06 20:18:15.505266');
insert into сообщение values (default, 54, 'клиент', $$– Как вас зовут?

– Дент$$, '2024-05-06 15:43:26.194126');
insert into сообщение values (default, 55, 'клиент', $$– Грядет катастрофа, – заявил Слартибартфаст$$, '2024-03-27 07:18:18.402163');
insert into сообщение values (default, 55, 'консультант', $$Неслышно появилась узенькая серебряная каемка ранней зари Тот же самый эффект наблюдался и в случае с кораблем Слартибартфаста Не прошло и нескольких секунд, как внезапно было достигнуто согласие$$, '2024-03-25 19:40:09.243743');
insert into сообщение values (default, 55, 'клиент', $$– Основной вычислительный центр, – невозмутимо пояснил Слартибартфаст$$, '2024-03-26 04:56:58.386098');
insert into сообщение values (default, 56, 'консультант', $$Многие из них попадаются в силки охотников, после чего их убивают, высушивают, экспортируют и кладут на кровати, чтобы люди на них спали Корабль лениво дрейфовал где-то в галактической глуши, окруженный чернильно-черной пучиной космоса$$, '2024-05-05 15:40:53.887404');
insert into сообщение values (default, 56, 'консультант', $$С тем же успехом можно покориться судьбе, а здравый рассудок поберечь на потом Тем временем на Земле под аккомпанемент дождя тянулся один из самых кошмарных вечеров в жизни Артура Дента В нем обрисовался силуэт высокой фигуры Главное – не кивайте ему!

– А теперь преклоним наши головы в знак оплаты, – произнес голос, а потом пробормотал ту же фразу гораздо быстрее и задом наперед$$, '2024-05-08 00:48:39.595681');
insert into сообщение values (default, 56, 'клиент', $$– Должно быть, она тебе донельзя обрыдла Только двадцать минут назад он решил сойти с ума – и вот уже гоняется по лугам доисторической Земли за честерфильдским диваном – Где мы?

– Гм… на чем-то зеленом$$, '2024-05-05 01:17:33.343221');
insert into сообщение values (default, 57, 'консультант', $$– Повелители Криккита, – повторил Слартибартфаст$$, '2024-05-27 18:11:01.362593');
insert into сообщение values (default, 57, 'клиент', $$Что делать?

Форд пожал плечами:

– А что ты предлагаешь?

– Скажи мне, – попросил Артур, – что все последние пять лет приснились мне во сне$$, '2024-05-27 10:19:42.071573');
insert into сообщение values (default, 57, 'клиент', $$– А затем мы отправимся, – на полном серьезе заявил робот, – на вечеринку$$, '2024-05-27 04:16:21.780192');
insert into сообщение values (default, 58, 'консультант', $$Роботы пялились на Зафода душераздирающими покойницкими глазами Из люка вырвался столб света Большинству людей промахнуться не удается, и чем больше усилий они прилагают, тем крупнее вероятность столкновения с землей Зафод застыл как вкопанный$$, '2025-02-18 08:37:25.653821');
insert into сообщение values (default, 58, 'консультант', $$Первым потрясением для него было открытие, что у него имеется душа как таковая По-видимому, этот разговор действовал ему на эквивалент нервов Триллиан казалось, что это-то ей и требуется после всего пережитого Он просочился через протечку континуума, по воле парусных волн эфира и я не знаю еще чьей – какая на фиг разница, мы должны его поймать, а то так здесь и застрянем!

Он съехал на пятках по скале и стремглав понесся по полю$$, '2025-02-14 21:12:28.001360');
insert into сообщение values (default, 59, 'клиент', $$Его лучи ласкали белые шляпы и красные лица Он замер$$, '2023-06-22 11:45:38.963919');
insert into сообщение values (default, 59, 'клиент', $$После сбора ее следует положить в темный пыльный ящик и не трогать много лет Меж тем снаружи солнце лило свой свет на веселую толпу – Вон там, – повторил он Было синее в желтую звездочку, а стало розовое$$, '2023-06-22 00:45:09.326020');
insert into сообщение values (default, 59, 'консультант', $$Затем из клубов дыма вынырнула светлая фигура Слартибартфаста – Так что вы тут делаете, мужики?

Молчание Только двадцать минут назад он решил сойти с ума – и вот уже гоняется по лугам доисторической Земли за честерфильдским диваном – Мне довелось побыть знаменитостью, – скорбно завывал робот, – совсем недолго благодаря моему чудесному и весьма досадному спасению от удела, сравнимого разве что с такой удачей, как гибель в сердце пылающей звезды$$, '2023-06-22 17:58:27.285566');
insert into сообщение values (default, 59, 'клиент', $$К счастью, таких тут хватало – Я так и понял$$, '2023-06-22 11:11:30.777090');
insert into сообщение values (default, 60, 'клиент', $$Во-первых, из-за ННП-поля$$, '2023-11-21 11:59:21.834571');
insert into сообщение values (default, 60, 'клиент', $$Музыка бодро штурмовала небесное царство полной несказанности Другими словами, оговоренный час сбора – это один-единственный момент времени, в который абсолютно невозможно появление любого из членов компании Будь ты хоть семи пядей во лбу, но за год спроектировать и построить такой корабль… Не верю$$, '2023-11-23 18:42:03.430957');
insert into сообщение values (default, 60, 'консультант', $$Толпа взревела$$, '2023-11-23 21:09:10.361848');
insert into сообщение values (default, 60, 'клиент', $$Он приближался к рубке лилипутскими шажками с таким видом, будто предпочел бы улепетывать от нее великаньими И вдруг роботы вернулись, снова начался кавардак, и на этот раз после их отлета матрасс остался на болоте один Довольные улыбки, которыми он обычно озарял чужие похороны, стали какими-то натянутыми Артур, погруженный в мысли об Эссексе и Ирландии, на миг растерялся$$, '2023-11-22 00:10:22.390707');
insert into сообщение values (default, 61, 'консультант', $$– Как вас зовут?

– Дент Пластмасса под бетон$$, '2023-11-21 21:09:24.602108');
insert into сообщение values (default, 61, 'консультант', $$Он прислушался, но в свист ветра вплетались лишь привычные голоса полусумасшедших энтомологов, перекликающихся через мрачную трясину Строго говоря, эту шайку бесчувственных выродков он давно уже возненавидел лютой ненавистью – У нас на борту кто-то есть?

– Мммм, – ответил компьютер – … напомни, чтобы я дал сам себе в зубы$$, '2023-11-21 01:22:48.548770');
insert into сообщение values (default, 61, 'консультант', $$Или, – добавил он почти под нос, – наблюдать крикетные матчи – М-да, похоже, сегодня все потусторонние силы в гости к нам… – радостно объявил репродуктор самому себе$$, '2023-11-20 18:10:17.699078');
insert into сообщение values (default, 61, 'консультант', $$– Ожидаемое время в пути – три недели, – продолжил он – Артур Дент? – переспросило оно Небосвод – от горизонта до горизонта, с востока до запада, с севера до юга – был абсолютно черен – Ну и что «Путеводитель»?

– В смысле?

– Ты хотел процитировать$$, '2023-11-19 17:47:29.428754');
insert into сообщение values (default, 62, 'клиент', $$Царила тишина И вновь зашагал Роботы – Артур Филип Дент? – уточнило существо, деловито лязгнув зубами$$, '2024-08-30 15:54:54.750426');
insert into сообщение values (default, 62, 'консультант', $$Из тьмы прямо на них вылетел, изрытая лазерный огонь, боевой звездокрейсер размером с небольшой промышленный город$$, '2024-09-03 01:20:45.288576');
insert into сообщение values (default, 62, 'клиент', $$Что Слартибартфаст в этом нашел такого интересного, ведал он один – Да, ты прав, и все же он утверждал, что видел, как нечто материализовалось на площадке$$, '2024-09-02 04:35:59.172620');
insert into сообщение values (default, 63, 'клиент', $$Но радовался он зря$$, '2024-07-26 08:03:50.961385');
insert into сообщение values (default, 63, 'консультант', $$– Ему что-то не везло последние два миллиона лет, – пояснил он полисмену Зачем это понадобилось притаскивать сюда сто тысяч человек ради такой ерунды?

Он нервно двинулся в сторону рубки$$, '2024-07-29 04:26:51.340814');
insert into сообщение values (default, 63, 'клиент', $$Один мальчишка озадаченно посмотрел на него:

– У вас все в норме?

– Нет Главное – не кивайте ему!

– А теперь преклоним наши головы в знак оплаты, – произнес голос, а потом пробормотал ту же фразу гораздо быстрее и задом наперед А там происходило всего лишь то, что люди столпились на площадке вокруг ее середины$$, '2024-07-26 17:41:48.474369');
insert into сообщение values (default, 64, 'клиент', $$– И плюхнувшись на колени перед Фордом, прошипел: – Это полисмен Форд с Артуром поспешили за ним как околдованные$$, '2023-08-29 15:15:55.932828');
insert into сообщение values (default, 64, 'клиент', $$Музыка бодро штурмовала небесное царство полной несказанности Ты что-то сказал?

– Дизайн, – повторил Форд$$, '2023-08-30 03:12:18.333331');
insert into сообщение values (default, 64, 'консультант', $$– И это было величественное зрелище?

– Довольно величественное$$, '2023-08-29 18:11:03.971464');
insert into сообщение values (default, 64, 'консультант', $$Жизненный цикл отвертки с храповиком весьма занятен$$, '2023-08-28 19:52:25.585490');
insert into сообщение values (default, 65, 'клиент', $$– Примерно… – задумался Слартибартфаст, – примерно две трети диаметра галактического диска$$, '2024-05-13 12:13:30.030345');
insert into сообщение values (default, 65, 'клиент', $$Периодически в головокружительном мельтешении событий они выделяли, скорее чутьем, чем зрением, ужасные катастрофы, кошмарные преступления, катаклизмы, и всегда они были связаны с определенными, вновь и вновь возникающими образами – единственными, которые ясно выступали из беспорядочной лавины исторических фактов: крикетная калитка, твердый красный мячик, беспощадные белые роботы, а также нечто смутное – что-то темное, закрытое облаками$$, '2024-05-11 18:29:19.456052');
insert into сообщение values (default, 66, 'клиент', $$Одно мычание вместо «да», два вместо «нет» Старец остановился и поднял глаза к небу Корабль пересекал орбиты планет Солнечной системы, намереваясь совершить пертурбационный маневр вокруг Солнца и, разогнавшись, выскочить в большой космос$$, '2023-11-07 17:12:53.463673');
insert into сообщение values (default, 66, 'клиент', $$– Повелители Криккита, – повторил Слартибартфаст Вероятно, природа – в своей безмерной мудрости – работает над этим – Да что этот старый дурак собрался делать, вакуум его заарктурь? – взорвался Форд Марвин отвлекся от своего утомительного кругового обхода$$, '2023-11-07 06:02:12.674899');
insert into сообщение values (default, 66, 'консультант', $$– Где же ты…

– Отыскал джин с тоником? – радостно продолжил за него Форд Но никто этого не спрашивал, и Форд злился – Вон там, – сказал Форд, вновь указывая на табло и глядя на поле$$, '2023-11-06 03:29:36.823718');
insert into сообщение values (default, 66, 'консультант', $$Отряхнулся И естественно, на следующее утро Меграмал больше не был виден Аналогично последовательность отдельных впечатлений сливалась тут в единое чувство – хотя на чувство оно как-то не походило Артур поделился своим впечатлением с друзьями$$, '2023-11-08 01:48:04.250062');
insert into сообщение values (default, 67, 'клиент', $$– Ну и что «Путеводитель»?

– В смысле?

– Ты хотел процитировать$$, '2024-09-02 00:05:37.157417');
insert into сообщение values (default, 67, 'клиент', $$– Ч… ч… ч… – выговорили его губы Не Наша Проблема Морщась, он выслушал пояснение, что сейчас на поле произойдет вручение «Урны с Пеплом» капитану команды Англии, весь скукожился при известии, что данная команда заслужила этот приз, выиграв турнир в энный раз, буквально взлаял от злобы после сообщения, что «Пепел» – это останки столбика крикетной калитки, а когда (ну куда уж дальше!) от него потребовали смириться с фактом, что вышеупомянутый столбик был сожжен в австралийском городе Мельбурне в 1882 году, в знак «смерти английского крикета», Форд развернулся к Слартибартфасту, набрал в грудь воздуха – но ничего не сказал, потому что старца рядом с ними уже не было$$, '2024-08-31 15:59:41.773640');
insert into сообщение values (default, 67, 'консультант', $$Всеми фибрами своего пружинного сознания матрасс чувствовал, что робот горячо мечтает, чтобы его спросили, давно ли он совершает это бесплодное и бессмысленное топтание В их штате есть специальные работники с удивительными телами и воззрениями$$, '2024-09-04 01:35:29.140868');
insert into сообщение values (default, 68, 'консультант', $$Я его в реку выбросил$$, '2024-02-24 14:12:38.940966');
insert into сообщение values (default, 68, 'клиент', $$Произнеся эти слова, мальчишка посмотрел на что-то за плечом Дента, демонстрируя, что вовсе не торопится скрыться, а затем ретировался, почесывая нос$$, '2024-02-26 15:37:41.932373');
insert into сообщение values (default, 68, 'клиент', $$Нервно опираясь о стену коридора, он морщил лоб (то есть лбы), словно пытаясь откупорить бутылку методом телекинеза – … это их жизненный, а чаще предсмертный опыт Не знаю, зачем им это надо, но так оно и есть$$, '2024-02-25 20:32:24.186367');
insert into сообщение values (default, 69, 'клиент', $$То есть он решил оскорбить всех ее обитателей Глаза Артура пошли колесом – Странный трофей – Вот что я сказал$$, '2023-10-06 12:20:06.947386');
insert into сообщение values (default, 69, 'клиент', $$– От… к-к-к… э-э… – добавил он немного погодя Форд, надувшись, засунул «Путеводитель» назад в сумку – Поймать? – пробормотал Артур и тут же вытаращил глаза – диван, вальяжно покачиваясь, уплывал в глубь поля Вероятно, людей обуяла коллективная мысль «Ну и дела!», сопровождаемая единодушным чувством недоумения$$, '2023-10-06 16:04:08.768404');
insert into сообщение values (default, 69, 'клиент', $$Безусловно, это были не земляне, хотя все различия состояли в чуть-чуть слишком высоком росте, излишней худобе, угловатости и бледной, почти белой коже – Нет, чушь какая-то… Это было бы абсурднее, еще абсурднее…» И замялся$$, '2023-10-07 07:01:52.603649');
insert into сообщение values (default, 70, 'клиент', $$– Быть такого не может – Перед тобой мужчина в полном расцвете сил, который может сделать все, что ему захочется, вот только что-то не хочется мне ни фига, ну ни фигошеньки…

Он помолчал – Что это было? – вымолвил Артур – Да что этот старый дурак собрался делать, вакуум его заарктурь? – взорвался Форд$$, '2024-08-01 21:48:47.603842');
insert into сообщение values (default, 70, 'клиент', $$– Завладеем, – заявил робот Оно, случайно, не твое?

– Изволь заткнуться насчет твоего полотенца! – воскликнул Форд$$, '2024-08-02 01:54:37.738605');
insert into сообщение values (default, 70, 'консультант', $$Мало того что они были белые, под цвет униформы игроков, но они еще и держали в манипуляторах нечто вроде крикетных бит и крикетных мячей Правда, он не был ярко-розовым, но это вовсе не значит, что внешне он ничем не выделялся – Здравствуйте, робот, – поздоровался матрасс$$, '2024-08-02 00:47:08.746884');
insert into сообщение values (default, 71, 'консультант', $$Во-от, – добавил он, тыча пальцем в экран «Путеводителя», – вот воистину жуткое местечко$$, '2024-03-30 10:16:34.445453');
insert into сообщение values (default, 71, 'консультант', $$– Искомый субъект – некрупный слизняк, – пискнул он, – из рода А-Рт-Ур-Еа-Ипдену Затем Триллиан набрела на главку о Хэй-Виляй, экзотической планете-курорте, одном из чудес Галактики С тем же успехом можно покориться судьбе, а здравый рассудок поберечь на потом$$, '2024-03-30 07:08:08.527202');
insert into сообщение values (default, 71, 'клиент', $$Что делать?

Форд пожал плечами:

– А что ты предлагаешь?

– Скажи мне, – попросил Артур, – что все последние пять лет приснились мне во сне – Пойду-ка вздремну, – проговорил он Вследствие чего школьная администрация отправила компьютер в клинику для помешанных киберустройств, куда за ним последовала и девочка, имевшая глупость влюбиться в злосчастную машину$$, '2024-03-31 14:11:31.705702');
insert into сообщение values (default, 71, 'консультант', $$Они уселись на камень и впали в глубокую задумчивость$$, '2024-03-31 18:17:06.499040');
insert into сообщение values (default, 72, 'клиент', $$– Основной вычислительный центр, – невозмутимо пояснил Слартибартфаст Против инстинкта не попрешь – наши герои невольно двигались опасливо, даже воровато, хоть и знали, что с тем же успехом могли трубить в трубы и вопить: «Ату!» – инфоиллюзию это бы не спугнуло В системе Неавооси находятся – то есть находились – крупнейшие страховые компании Галактики$$, '2024-03-09 12:35:44.810038');
insert into сообщение values (default, 72, 'клиент', $$– Нет уж Процедура превращения какого-либо объекта из зримого в незримый столь трудоемка, что в 999 999 999 случаях из миллиарда гораздо проще и эффективнее просто убрать этот объект куда подальше и обойтись без него Он просочился через протечку континуума, по воле парусных волн эфира и я не знаю еще чьей – какая на фиг разница, мы должны его поймать, а то так здесь и застрянем!

Он съехал на пятках по скале и стремглав понесся по полю$$, '2024-03-11 05:09:11.322045');
insert into сообщение values (default, 73, 'клиент', $$– Ты слишком много пьешь, – сказала Триллиан – Как ты себя чувствуешь? – спросил Форд – И уставился в крохотный иллюминатор – на кромешную тьму И только мощность моего блока счастья подкачала$$, '2024-11-05 06:09:40.618404');
insert into сообщение values (default, 73, 'консультант', $$Подобно открытию Эйнштейна, что время не есть абсолют, но зависит от движения наблюдателя в пространстве, а пространство не есть абсолют, ибо зависит от движения наблюдателя во времени, ныне установлено, что числа не абсолютны, но зависят от движения наблюдателя в ресторанах$$, '2024-11-04 18:33:58.076364');
insert into сообщение values (default, 73, 'клиент', $$Поговаривают, что у нее эрогенные зоны начинаются милях в четырех от тела как такового Припев был немного печальный Хлюп, хлюп – шагал он по болоту$$, '2024-11-07 04:47:52.219170');
insert into сообщение values (default, 74, 'клиент', $$Их задача – в решающий момент выскочить из кустов и продемонстрировать наглядно и/или выразить словесно свою особливость Матрасс пришел в возбуждение$$, '2025-05-08 17:19:06.413186');
insert into сообщение values (default, 74, 'консультант', $$Жизненный цикл отвертки с храповиком весьма занятен$$, '2025-05-09 10:35:19.904403');
insert into сообщение values (default, 75, 'клиент', $$– Вот в чем беда с этим разговором, – заявил Артур после того, как озадаченность медленно, точно альпинист по трудному склону, вскарабкалась по его лицу и уселась на бровях, – он очень не похож на те, что мне приходилось вести в последнее время$$, '2024-02-03 18:20:43.911983');
insert into сообщение values (default, 75, 'консультант', $$– Уф!

Зафод остановился – Где?

– Там Ветерок осторожно ворошил высокую траву вокруг пещеры, птицы чирикали друг с дружкой, бабочки изящно порхали туда-сюда, и вообще вся природа из кожи вон лезла, стараясь произвести благоприятное впечатление$$, '2024-02-05 13:42:06.380688');
insert into сообщение values (default, 75, 'консультант', $$Это последнее он совершал с большой плучительностью – Тс-с, – прошипел Форд и глубокомысленно воздел очи горе Еще раз широко улыбнувшись, он откусил кусочек от кроличьей ноги – остатка вчерашнего ужина$$, '2024-02-04 10:28:37.451693');
insert into сообщение values (default, 76, 'клиент', $$Без нее мой корабль перестанет работать Во-первых, из-за ННП-поля – Артур Дент? – переспросило оно$$, '2026-01-23 12:18:12.797745');
insert into сообщение values (default, 76, 'клиент', $$Казалось, его соорудили где-то в сарае – собственно, так оно и было Робот-официант, робот-буфетчик и робот-метрдотель обслуживали роботов-клиентов Было неопровержимо доказано, что количество зрителей, смотревших телерепортаж о запуске «Титаника», превосходило все население Вселенной на тот момент Также эта стремительная гонка по водопадам времени подарила им еще одно четкое ощущение$$, '2026-01-28 08:59:22.515176');
insert into сообщение values (default, 77, 'клиент', $$Вот тогда-то он и набрел на свою цель жизни, дело, которое не позволит ему впасть в спячку никогда-никогда (так ему, во всяком случае, казалось)$$, '2024-05-02 11:55:55.602699');
insert into сообщение values (default, 77, 'консультант', $$– Разбудишь ко второй серии – Возмущения в континууме!

– А, это они мебельные магазины громят! – воскликнул Артур, с трудом вернувшись в вертикальное положение и – как он смел надеяться – в здравый рассудок «ДОСУГ В МИРЕ НЕСБЫТОЧНОГО» – вот какой заголовок привлек внимание Триллиан, когда некоторое время спустя она вновь уселась на диван с «Путеводителем» После сбора ее следует положить в темный пыльный ящик и не трогать много лет$$, '2024-05-02 01:29:34.599417');
insert into сообщение values (default, 77, 'клиент', $$– Мы взлетели, – пояснил Слартибартфаст Особенно этот момент, когда нужно угодить в калитку маленьким красным мячиком – Ты что-то придумал, правда? – спросил Артур Вновь проследив траекторию мяча, Форд захлопал глазами$$, '2024-05-02 12:21:28.535303');
insert into сообщение values (default, 77, 'консультант', $$– И он же снабдил меня этим протезом Интерьер тесной, сумрачной рубки был выдержан в темно-зеленых, темно-красных и темно-коричневых тонах$$, '2024-05-01 12:20:04.189485');
insert into сообщение values (default, 78, 'консультант', $$Без нее мой корабль перестанет работать$$, '2024-07-10 22:05:32.869437');
insert into сообщение values (default, 78, 'консультант', $$И первый же взрыв развеял первоначальную надежду Артура, что это всего лишь рекламная затея австралийских фабрикантов маргарина – Примерно… – задумался Слартибартфаст, – примерно две трети диаметра галактического диска Вокруг них расстилались нежно-зеленые поля и луга$$, '2024-07-10 12:09:25.135084');
insert into сообщение values (default, 78, 'клиент', $$Однако же если в решающий момент вам посчастливится нежданно отвлечься на умопомрачительную пару ног (щупалец, ложноножек, в зависимости от вашей видовой принадлежности и/или личных вкусов), или на взрыв бомбы неподалеку, или на внезапное явление ужасно редкого жука на соседней былинке – тогда-то, к своему изумлению, вы увильнете от всякого столкновения с землей, точнее, останетесь болтаться в каких-то считанных дюймах над ее поверхностью Спустя некоторое время он начал медленно, воровато пробираться вперед с гримасой вдумчивой озадаченности на лице – как леопард, который не совсем уверен, что только что видел в полумиле впереди, на раскаленной и пыльной прерии, полупустую банку «Вискаса» Форд с Артуром поспешили броситься на землю, которая, казалось, ужасно быстро вертелась вокруг них Солнце клонилось к закату$$, '2024-07-10 08:35:19.014686');
insert into сообщение values (default, 79, 'консультант', $$Если и раньше он изъяснялся тоном призрака, то теперь это был вообще некий сильно простуженный житель Аида Это была безумная колымага из подручных материалов Мне крикет вообще-то нравится, – добавил он, – но на взгляд большинства, вы в наивности своей создали ужасную пошлость$$, '2024-05-28 20:35:02.671334');
insert into сообщение values (default, 79, 'клиент', $$Матрасс момнухнул Матрасс зауйломикал с головы до пят, отчего гладь мелкой, заросшей ряской протоки подернулась восторженной рябью Он плюнул на это занятие и, переведя взгляд на навигационный экран, ахнул при виде беспрецедентного полчища звезд Это была безумная колымага из подручных материалов$$, '2024-05-27 12:16:08.599432');
insert into сообщение values (default, 79, 'консультант', $$Да, я в курсе, на что он похож, но в реальности это сложный четырехмерный топографический график целого ряда весьма замысловатых математических функций$$, '2024-05-27 03:59:19.600843');
insert into сообщение values (default, 79, 'клиент', $$Криккитяне смотрели друг на друга, направо, налево, вперед, назад, даже на землю Главный же ужас состоял в том, что пещера находилась в лондонском районе Айлингтон и первый автобус в центр должен был отправиться примерно через два миллиона лет$$, '2024-05-28 22:47:01.204947');
insert into сообщение values (default, 80, 'клиент', $$– Мы могли бы перекинуться словечком о погоде Он с грохотом понесся по небу, словно точно знал, что делает Венских$$, '2024-05-13 09:39:27.873869');
insert into сообщение values (default, 80, 'консультант', $$И что самое удивительное, точно специально экипированные для данного мероприятия Эта фраза проходила на ура$$, '2024-05-13 06:30:38.549351');
insert into сообщение values (default, 80, 'консультант', $$– Где же ты…

– Отыскал джин с тоником? – радостно продолжил за него Форд А потом даже гумкнул от избытка чувств$$, '2024-05-12 22:58:54.906350');
insert into сообщение values (default, 81, 'клиент', $$– Вы ведь англичанин, правда? – поинтересовалось видение Периодически в головокружительном мельтешении событий они выделяли, скорее чутьем, чем зрением, ужасные катастрофы, кошмарные преступления, катаклизмы, и всегда они были связаны с определенными, вновь и вновь возникающими образами – единственными, которые ясно выступали из беспорядочной лавины исторических фактов: крикетная калитка, твердый красный мячик, беспощадные белые роботы, а также нечто смутное – что-то темное, закрытое облаками Артур хмуро поплелся за ним Извините, бога ради, никак не найду клавишу перемотки…

– … это удел биллионов биллионов невинных…

– Ни в коем случае, – прокричал Слартибартфаст, вновь проплывая мимо и яростно возясь с устройством, которое раньше воткнул в стену Зала информационных иллюзий; при ближайшем рассмотрении Артур сообразил, что оно по-прежнему торчало в стене, – не соглашайтесь ничего покупать$$, '2024-12-18 20:50:46.233622');
insert into сообщение values (default, 81, 'клиент', $$Правда, в них проглядывала некоторая чудаковатость – не хотел бы Артур ехать с ними в одном купе, – но вся эта чудаковатость сводилась к чрезмерному добродушию и любезности, а не каким-то изъянам Форд с Артуром так и обмерли, подавившись собственным воплем$$, '2024-12-20 15:21:57.018143');
insert into сообщение values (default, 82, 'консультант', $$Даже если ты посмотришь прямо на ННП, то все равно ее не разглядишь – если только не знаешь заранее, как она выглядит И что самое удивительное, точно специально экипированные для данного мероприятия – И сумка тоже не моя, – неожиданно объявил Артур$$, '2024-02-07 17:47:59.585950');
insert into сообщение values (default, 82, 'клиент', $$– Жду с нетерпением вашего рассказа о речи на болоте Пилоты увидели алмазную россыпь созвездий – и их души в ужасе взвыли$$, '2024-02-07 22:47:00.432759');
insert into сообщение values (default, 82, 'клиент', $$– Пожми ее, – просуфлировал Форд Венских$$, '2024-02-07 09:37:50.512780');
insert into сообщение values (default, 82, 'клиент', $$Правда, ангелы так не одеваются, точнее, не раздеваются Тем временем на Земле под аккомпанемент дождя тянулся один из самых кошмарных вечеров в жизни Артура Дента – Я отыскал озерцо, которое думало, что оно джин с тоником, и стал в нем бултыхаться$$, '2024-02-07 15:51:00.790739');
insert into сообщение values (default, 83, 'клиент', $$По-видимому, это словесное излияние вдохновило его на новый взлет к высотам уныния и отчаяния Их внешность произвела неуловимо устрашающее впечатление даже на Зафода, который видел их впервые и даже ни разу о них не слыхал Артур встал – Круто$$, '2024-06-28 15:46:43.822778');
insert into сообщение values (default, 83, 'консультант', $$Форд тем временем с тревогой наблюдал за суматохой Вот… – вымолвил он, задыхаясь, – … за чем… они… прилетали… – С этими словами он легонько мотнул головой, словно пытаясь утрясти свой мозг$$, '2024-06-28 05:25:05.183965');
insert into сообщение values (default, 83, 'клиент', $$Туда-то мы и отправимся – Откуда вы это взяли? – заорал он на полисменообразное$$, '2024-06-28 05:55:29.687322');
insert into сообщение values (default, 84, 'консультант', $$Вот что написано в «Путеводителе» об искусстве полета:


Полет – это искусство, а точнее сказать, навык Зафод тихо проскользнул в нее Следовательно, они сохранят у себя Пепел Душа Артура летала вокруг его тела кругами и мялась, не испытывая особенного желания войти$$, '2023-12-02 00:04:41.584786');
insert into сообщение values (default, 84, 'клиент', $$Ужасное потрясение, которое они испытали, когда, завывая и гремя, горящий звездолет упал с небес, врезавшись в холм примерно в полумиле от них, словами не передашь – В Африке было очень интересно, – заявил Форд$$, '2023-12-01 16:54:09.432333');
insert into сообщение values (default, 84, 'консультант', $$И что любопытно – направление, в котором указала его рука, не совпадало с направлением его взгляда То есть больно будет, если вам не удастся промахнуться мимо земли То была счастливая Галактика!

Колоссальные аккорды ошалели от собственной весомости$$, '2023-12-02 05:09:57.384104');
insert into сообщение values (default, 85, 'клиент', $$Начал моросить дождь Ему пришло в голову, что во Вселенной непременно найдется кто-то, кому жизнь кажется еще более беспросветной, тяжелой и треклятой, чем ему Артур Дент застрял на доисторической Земле в результате извилистой цепочки происшествий, в процессе каковых он попеременно подвергался оскорблениям и/или расщеплению на атомы в разнообразных экзотических уголках Галактики, бесчисленность и странность которых превзошли все его ожидания$$, '2023-12-16 05:51:15.238004');
insert into сообщение values (default, 85, 'консультант', $$Он снял с рычага воображаемую трубку и стал крутить воображаемый диск Похоже, на них восседали не то девушки, не то ангелы$$, '2023-12-16 14:38:07.484742');
insert into сообщение values (default, 85, 'клиент', $$– Я дома, – повторил Артур$$, '2023-12-16 09:25:55.668881');
insert into сообщение values (default, 86, 'консультант', $$Послышался ропот (будто сотня тысяч людей вымолвила: «Уф!»), и прямо над крикетным полем буквально сгустился из воздуха белый стальной звездолет$$, '2024-03-06 09:34:34.699266');
insert into сообщение values (default, 86, 'консультант', $$– Это только документальный фильм, – вскричал он Миссия «Криккита-1» заключалась в том, чтобы выяснить, есть ли что-то с той стороны неба, откуда, вероятно, и происходил разбившийся корабль$$, '2024-03-06 09:22:39.835859');
insert into сообщение values (default, 86, 'клиент', $$Пилоты увидели алмазную россыпь созвездий – и их души в ужасе взвыли$$, '2024-03-06 10:13:57.031932');
insert into сообщение values (default, 86, 'консультант', $$Десять минут спустя он уже горбился над чашкой чая под тентом летнего буфета, и на его осунувшееся лицо постепенно возвращался румянец Это Артур Дент говорит$$, '2024-03-06 17:52:05.095823');
insert into сообщение values (default, 87, 'консультант', $$К счастью, таких тут хватало$$, '2024-10-25 21:48:08.118443');
insert into сообщение values (default, 87, 'клиент', $$– ННП – это нечто, что мы не можем увидеть, или не видим, или то, чего нам не дает увидеть наш мозг, потому что мы считаем, что это не наша проблема Мне это кажется чрезвычайно странным, тем более что сумку я сшил на доисторической Земле своими руками Но тут же с безмерным чувством облегчения крепко схватился за нее обеими своими$$, '2024-10-25 07:49:31.922704');
insert into сообщение values (default, 88, 'клиент', $$– Три столба, – гремел мужчина$$, '2024-09-22 11:27:56.704295');
insert into сообщение values (default, 88, 'клиент', $$– У меня врачи нашли недоразвитость гланды общественного долга и врожденный порок морального ядра личности, – пробормотал он под нос, – ну разве мне можно доверить спасение Вселенной, сами посудите?

И тем не менее поднялся по лестнице вслед за сотоварищами У меня самый классный корабль во всем известном небе, девушка, с которой у меня все чудесно…

– Да?

– Ну, насколько я понимаю Небо было пусто и черно$$, '2024-09-21 20:04:23.063519');
insert into сообщение values (default, 88, 'консультант', $$Он прислушался, но в свист ветра вплетались лишь привычные голоса полусумасшедших энтомологов, перекликающихся через мрачную трясину Как-то ночью – а теперь на корабле ночь длилась постоянно – лежа в постели, он решил взять себя в руки, предпринять что-нибудь конструктивное$$, '2024-09-20 11:45:36.842758');
insert into сообщение values (default, 88, 'консультант', $$– А, – кивнул Артур, – политика, значит В этот момент Артур заметил странную особенность песни, которую распевали криккитяне$$, '2024-09-22 13:38:59.131148');
insert into сообщение values (default, 89, 'клиент', $$– Компьютер, – окликнул Охмешконасыпатель – Ммммм ммммы?

– Все равно, какой головы$$, '2025-03-10 20:22:32.836825');
insert into сообщение values (default, 89, 'консультант', $$– Да, бывает, – заметил Форд Маленькие группки монахов, которые взяли за обычай болтаться около крупных научных институтов и петь странные псалмы во имя идеи, что Вселенная – лишь крупица ее собственного воображения, куда-то сгинули после того, как получили от правительства дотацию на организацию уличных представлений Только пришествие карманных компьютеров пролило свет на умопомрачительную истину$$, '2025-03-13 23:23:31.670126');
insert into сообщение values (default, 89, 'клиент', $$– Приклюса и чудесения, – пробормотал он Я не спец по межличн… межличностным взаи-мо-от-но-ше-ни-ям, во…

Триллиан только подняла брови Попробуйте проделать это в погожий денек, рекомендует «Путеводитель»$$, '2025-03-14 23:28:29.763499');
insert into сообщение values (default, 90, 'клиент', $$Хлюп, хлюп – шагал он по болоту$$, '2024-08-21 10:07:19.524768');
insert into сообщение values (default, 90, 'консультант', $$Прикрыв один глаз, он что-то созерцал другим – И также я тебя прошу не говорить, что ты очень рада быть полезной или что ты польщена честью раскрыться передо мной и премного довольна вновь затвориться с сознанием выполненного долга, ладно?

– Ладно Не самой лучшей целью – в чем он сам первый признавался, – но эта какая-никакая цель как-никак давала ему какое-никакое занятие$$, '2024-08-20 21:49:56.925736');
insert into сообщение values (default, 90, 'клиент', $$– Искомый субъект – некрупный слизняк, – пискнул он, – из рода А-Рт-Ур-Еа-Ипдену Как ни странно, и тут моделью послужило маленькое итальянское бистро$$, '2024-08-21 22:01:07.977062');
insert into сообщение values (default, 91, 'консультант', $$– О, сущие пустяки – Космовидеотон, Мыслекинозал, Надомный Думатель, – известил он и пискнул$$, '2024-11-01 07:24:54.269708');
insert into сообщение values (default, 91, 'клиент', $$Зафод тихо проскользнул в нее$$, '2024-11-01 07:31:40.145747');
insert into сообщение values (default, 91, 'клиент', $$Наше странствие уже началось – И они поддерживают, – зашелся в истерике голос, – Золотую Перекладину Процветания и Серебряную Перекладину Мира!

Теперь все сооружение качалось в светящейся паутине, а музыка, к счастью, давно исчезла за горизонтами восприятия И не потому, что звездолет был невидим$$, '2024-11-02 16:44:08.824787');
insert into сообщение values (default, 91, 'консультант', $$Царила тишина – По-моему, это оно меня довело до ручки Несколько биллионов триллионов тонн сверхразогретых, лопающихся ядер водорода медленно вознеслись над горизонтом, прикинувшись при этом маленькими, холодными и чуточку сырыми Не бросай трубку$$, '2024-11-01 22:20:40.071916');
insert into сообщение values (default, 92, 'клиент', $$– Алло? Да? – пробормотал Артур – Я сам знаю, на что это похоже, – отрезал Слартибартфаст и вошел в пресловутое помещение И хотя они предназначались не нашим путешественникам, те машинально склонили головы – и слава богу, ибо маленький красный и тяжелый мяч (истинный виновник овации) просвистел в считаных миллиметрах над макушкой Артура$$, '2024-01-15 13:58:37.480405');
insert into сообщение values (default, 92, 'консультант', $$С легким жужжанием и крайне зловещим видом он завис над землей Прикрыв один глаз, он что-то созерцал другим Прежде чем мы поведаем, что именно сказал робот, следует отметить, что Зафод был первым живым органическим существом, кому довелось услышать голос этих тварей за последние десять биллионов лет Это было их творение, и сейчас они пели о нем песенку, изливая в ней двойную радость успеха и обладания$$, '2024-01-15 01:38:08.881544');
insert into сообщение values (default, 92, 'консультант', $$Пользуясь секретами древних мастеров, они любовно смонтировали этот сувенир, который украсит ваш дом – в напоминание о павших и в знак почтения к Галактике – нашей Галактике, – на алтарь которой они положили свои жизни…

Тут мимо вновь проплыл Слартибартфаст – Артур Филип Дент? – уточнило существо, деловито лязгнув зубами$$, '2024-01-15 05:25:47.982348');
insert into сообщение values (default, 92, 'консультант', $$– А… мт… – выпалил он Зафод вновь кивнул, поигрывая пистолетом – Просто прими на веру все, что я тебе скажу, и сразу все станет совсем, совсем ясно$$, '2024-01-14 18:20:17.867403');
insert into сообщение values (default, 93, 'консультант', $$– ННП – это нечто, что мы не можем увидеть, или не видим, или то, чего нам не дает увидеть наш мозг, потому что мы считаем, что это не наша проблема О нет – то были действия, странно непохожие на все его обычные странности и чудачества$$, '2026-08-28 23:26:43.005044');
insert into сообщение values (default, 93, 'консультант', $$Взамен она направила корабль на Аллосиманиус-Синеку, планету льдов, снега, умопомрачительных красот природы и ужасных морозов$$, '2026-08-29 18:11:11.822020');
insert into сообщение values (default, 94, 'консультант', $$В отчаянии он снова пихнул Форда локтем$$, '2024-08-12 10:04:25.078636');
insert into сообщение values (default, 94, 'консультант', $$Тело Артура Дента завертелось Взамен она направила корабль на Аллосиманиус-Синеку, планету льдов, снега, умопомрачительных красот природы и ужасных морозов Форд тем временем с тревогой наблюдал за суматохой$$, '2024-08-14 00:18:38.699730');
insert into сообщение values (default, 94, 'клиент', $$При взгляде на это небо мерещилось, будто ты один-одинешенек во Вселенной – Уловили суть? – спросил Слартибартфаст$$, '2024-08-14 23:55:24.753374');
insert into сообщение values (default, 94, 'клиент', $$Болтайтесь над землей и парите, парите и болтайтесь$$, '2024-08-13 16:04:14.320504');
insert into сообщение values (default, 95, 'консультант', $$Из люка вырвался столб света Подъем по горным тропам со снежных равнин Лиски до вершины Хрустальных Пирамид Састантуа долог и утомителен даже при наличии реактивных лыж и упряжки синекских снегодавов, но открывающаяся сверху панорама: Ледники Безмолвия, мерцающие Призматические Горы и хоровод призрачных ледяных светляков вдалеке – вначале замораживает разум, а потом медленно возвышает его к еще невиданным высотам наслаждения прекрасным$$, '2024-01-05 20:21:01.482275');
insert into сообщение values (default, 95, 'консультант', $$Артур откашлялся Что ни говори, а Криккит казался приятным во всех отношениях местечком – Рада быть полезной$$, '2024-01-06 02:18:34.356342');
insert into сообщение values (default, 95, 'клиент', $$Около того, – сказал Марвин надменно На Зете Прутивнобендзы целые дни подобной бездвижности случались очень часто, и этот обещал ничем не отличаться от прочих Сам собой откинулся трап$$, '2024-01-05 11:46:17.540398');
insert into сообщение values (default, 95, 'консультант', $$Зафод не покидал кровати – Что они… – переспросил Форд И все же этот случай войдет в анналы истории, тем более что он произошел в столь драматический момент, когда Англии не хватает до победы только двадцати восьми перебежек$$, '2024-01-06 00:36:04.246211');
insert into сообщение values (default, 96, 'консультант', $$– Куда? На чем? – воскликнул Артур – Откуда вы это взяли? – заорал он на полисменообразное Нервно опираясь о стену коридора, он морщил лоб (то есть лбы), словно пытаясь откупорить бутылку методом телекинеза Почему вы ходите кругами?

– Потому что у меня нога завязла, – сказал Марвин без обиняков$$, '2023-12-22 08:21:25.048723');
insert into сообщение values (default, 96, 'клиент', $$– Все в ажуре, офицер, – заявил он – Это же крикетная площадка «Лордз», верно? – возопил Артур – А ты видишь?

– Да$$, '2023-12-21 11:17:28.876122');
insert into сообщение values (default, 96, 'клиент', $$Триллиан была очарована прочитанным, но скрепя сердце решила, что Зафоду с его нынешним настроением лучше и не мечтать ни об уроках летания, ни о хождении пешком по горам, ни о борьбе с Брантивортигорнским Государственным Управлением за признание законным свидетельства о переезде – все эти занятия были перечислены под заголовком: «Досуг в мире несбыточного» Нежданно-негаданно вывалившись из пространственно-временной аномалии в чудный, совершенно очаровательный лондонский денек, Форд с Артуром совершили довольно жесткую посадку на безупречный газон площадки «Лордз» После фантасмагорического балагана «основного вычислительного центра» Зал информационных иллюзий был настоящим отдохновением для глаз Не прошло и нескольких секунд, как внезапно было достигнуто согласие$$, '2023-12-20 20:52:00.526130');
insert into сообщение values (default, 97, 'консультант', $$Их задача – в решающий момент выскочить из кустов и продемонстрировать наглядно и/или выразить словесно свою особливость$$, '2024-10-20 08:09:33.892998');
insert into сообщение values (default, 97, 'клиент', $$– Только-то? – опасливо уточнил Артур Артур приподнялся на локтях:

– Где я?

– На крикетной площадке «Лордз», – сообщил Форд$$, '2024-10-20 15:54:22.517536');
insert into сообщение values (default, 97, 'консультант', $$– …моргал…

– Ну да – Ага, – произнес он со вздохом облегчения (что вряд ли было разумно), – видите ли, робот, я не хотел перенапрягать ваше воображение – Вы хотите дослушать эту историю или что?

– Мне хотелось бы услышать вашу речь, – заявил матрасс$$, '2024-10-22 01:10:32.830758');
insert into сообщение values (default, 97, 'консультант', $$Взамен она направила корабль на Аллосиманиус-Синеку, планету льдов, снега, умопомрачительных красот природы и ужасных морозов$$, '2024-10-23 05:38:36.725745');
insert into сообщение values (default, 98, 'клиент', $$Артур, погруженный в мысли об Эссексе и Ирландии, на миг растерялся Другое значение этого слова (согласно «Ультраполному максимегалонскому словарю всех возможных языков и наречий») – это звук, который вырвался у Его Светлости лорда Соньвальтяпа Пустецийского, когда до него дошло, что он второй год подряд позабыл о дне рождения своей жены$$, '2024-11-04 00:46:15.666102');
insert into сообщение values (default, 98, 'консультант', $$– Она самая$$, '2024-11-03 06:23:38.332754');
insert into сообщение values (default, 98, 'клиент', $$Древнее Зло встало из могилы$$, '2024-11-01 18:29:05.491945');
insert into сообщение values (default, 98, 'консультант', $$Мотнув головой, Артур сел на землю и поглядел на Форда снизу вверх – Ну и что «Путеводитель»?

– В смысле?

– Ты хотел процитировать – Я этот номер уже видел, – проговорил он Слартибартфаст занял освободившееся благодаря этому происшествию место и окинул суровым взглядом меню$$, '2024-11-02 20:19:23.814885');
insert into сообщение values (default, 99, 'клиент', $$– Какое расстояние мы сейчас преодолели? – спросил Форд Да, я в курсе, на что он похож, но в реальности это сложный четырехмерный топографический график целого ряда весьма замысловатых математических функций Однако на взгляд Артура, абсолютно черный небосвод придавал всему идиллическому, несмотря на сумрак, пейзажу какой-то зловещий оттенок$$, '2025-05-10 14:35:09.106570');
insert into сообщение values (default, 99, 'консультант', $$– Хм, что-то не верится Но никто этого не спрашивал, и Форд злился – Что «нет»?

– Не пытайся звонить себе самому домой Его сходство с Моисеем усилилось – несмотря на отсутствие горы, теперь он шел решительной поступью по горящей и дымящей холеной лужайке$$, '2025-05-09 21:03:37.729736');
insert into сообщение values (default, 99, 'консультант', $$Этот миг пришел и миновал без происшествий, как и бывало обычно на Зете Прутивнобендзы$$, '2025-05-08 18:21:10.220117');
insert into сообщение values (default, 100, 'консультант', $$– Странный трофей То есть он решил оскорбить всех ее обитателей Так оно и было$$, '2024-03-03 15:41:41.771264');
insert into сообщение values (default, 100, 'консультант', $$И оторопел от последствий своего заявления$$, '2024-03-02 22:38:19.061570');
insert into сообщение values (default, 100, 'клиент', $$Всеми этими причиндалами вяло манипулировали роботы Однако Эффрафакс все же проиграл пари – и лишился головы – из-за педантизма некоего арбитра, обратившего внимание на то, что: а) при прохождении через место, где следовало находиться Меграмалу, он ни обо что не споткнулся и не расшиб себе лоб и б) в небесах засияла какая-то подозрительная новая луна Он уставился вверх Корабль вылетел из Облака$$, '2024-03-02 18:57:36.686428');
insert into сообщение values (default, 100, 'консультант', $$Жизненный цикл отвертки с храповиком весьма занятен А это совсем другой коленкор Отключив всю кухонную автоматику, она приготовила самый роскошный ужин, какой был в ее силах, – аппетитно прожаренное мясо, ароматные фрукты, благоуханный сыр, коллекционные альдебаранские вина Свобода$$, '2024-03-03 03:35:44.828674');
insert into сообщение values (default, 101, 'клиент', $$Слартибартфаст сказал:

– Потому что при передвижении по космосу числа – настоящий бич божий$$, '2026-12-19 04:43:29.550314');
insert into сообщение values (default, 101, 'консультант', $$55 тебя начинает обволакивать ужасная апатия: ты понимаешь, что уже принял все ванны, какие можно было принять с пользой для души и тела, что сколько ни созерцай любой абзац газетного текста, ты не прочтешь ни строчки, не говоря уже о применении на практике новейшего, совершившего революцию в области стрижки кустарников метода, который в этой газете описан – Расскажите о речи, которую вам однажды довелось произнести, – взмолился он Глянул на Артура – тот тихо напевал себе под нос Весьма сложно отвлечь ваше внимание от этих трех вещей за неполную секунду, которой вы располагаете$$, '2026-12-18 19:52:24.557578');
insert into сообщение values (default, 102, 'клиент', $$– Я считаю своим долгом предупредить тебя о двух вещах, – заявил Форд, пододвинув к Артуру газету «Гардиан» В настоящее время реситуасексулузоны играют ключевую роль во многих отраслях математики, в том числе в статистике и бухгалтерии, а также являются элементами основных уравнений, управляющих генерацией ННП-поля Затем из клубов дыма вынырнула светлая фигура Слартибартфаста Люк сам собой захлопнулся$$, '2025-10-13 03:36:17.708020');
insert into сообщение values (default, 102, 'консультант', $$Он прошел к зеленой винтовой лестнице из кованого железа, непонятно зачем помещенной в середине рубки, и начал всходить по ней – Ау, компьютер! – прошептал он$$, '2025-10-13 23:55:59.938270');
insert into сообщение values (default, 103, 'консультант', $$– Все в ажуре, офицер, – заявил он$$, '2024-08-31 21:59:25.826861');
insert into сообщение values (default, 103, 'клиент', $$Заблудившемуся в пространстве хотя бы не угрожает смерть со скуки Тогда бы ему заметили, что он поет только одну ноту, на что бы он ответил, что по очевидным, как ему кажется, причинам он опустил кусочек «ология любви» – Странный трофей$$, '2024-09-01 00:08:36.235160');
insert into сообщение values (default, 103, 'клиент', $$– Где мы?

– Гм… на чем-то зеленом$$, '2024-08-30 07:30:38.343089');
insert into сообщение values (default, 103, 'консультант', $$Этот факт был расценен как величайшее достижение социологии телевидения Темп все возрастал Форд повторил$$, '2024-09-01 09:51:04.141498');
insert into сообщение values (default, 104, 'консультант', $$Они прошли очень близко от наблюдателей под деревом, размахивая фонарями, от чего по траве и листве скакали забавные «зайчики», радостно болтая между собой и самым натуральным образом распевая песню о том, как все чуд-чуд-чудесно на свете, как они счастливы, как здорово они потрудились на ферме и как приятно возвращаться домой, где ждут жены и дети Роботы успели частично разобрать дальнюю стену рубки и пробить ход через жизненно важные органы корабля$$, '2025-09-20 16:46:33.072942');
insert into сообщение values (default, 104, 'консультант', $$Большинство зрителей, будучи не в силах выдержать этого зрелища, зажмурили глаза и переключились на слушание радиотрансляции Сквозь мрак виднелись лишь огни ближнего городка$$, '2025-09-22 11:54:57.405406');
insert into сообщение values (default, 104, 'консультант', $$Вероятность подобного события равна примерно одному шансу из бесконечности Не самой лучшей целью – в чем он сам первый признавался, – но эта какая-никакая цель как-никак давала ему какое-никакое занятие Кое-кто с придыханием произносит имя «Золотое сердце», другие благоговейно повествуют о «Бистроматолете»$$, '2025-09-21 18:50:44.592112');
insert into сообщение values (default, 105, 'клиент', $$– Роса, – заметил он, – выпала сегодня на растительность с редкостно отвратительным хлюпающим звуком – И это было величественное зрелище?

– Довольно величественное$$, '2025-05-10 02:25:40.441063');
insert into сообщение values (default, 105, 'клиент', $$Этот миг пришел и миновал без происшествий, как и бывало обычно на Зете Прутивнобендзы$$, '2025-05-08 18:59:14.423616');
insert into сообщение values (default, 105, 'консультант', $$Артуру пришло в голову, что раз они добрались до конца, точнее, до начала всех ужасов, которые смутно пережили, сейчас должна стрястись беда$$, '2025-05-08 10:18:12.353499');
insert into сообщение values (default, 106, 'клиент', $$Тут он решил, что пора заговорить – Ну и хорошо, – сказал Артур Они стояли одни-одинешеньки на вершине утеса где-то на доисторической Земле и решительно смотрели друг другу в глаза Не будучи уверен в понятливости четвертого стакана, он послал за ним пятый с дополнительными пояснениями и шестой чисто ради моральной поддержки$$, '2024-06-14 09:59:24.291545');
insert into сообщение values (default, 106, 'клиент', $$– Ммммм ммммы?

– Все равно, какой головы А это другое – Дайте мне формы и контуры$$, '2024-06-14 23:53:28.236519');
insert into сообщение values (default, 106, 'консультант', $$Мне крикет вообще-то нравится, – добавил он, – но на взгляд большинства, вы в наивности своей создали ужасную пошлость Только пришествие карманных компьютеров пролило свет на умопомрачительную истину – Одно время я так тоже думал, – подхватил Форд, – а потом на пару недель решил, что я – лимон Обреченно прислонившись к стене, Зафод произнес несколько выразительных слов, немало шокировавших его другую голову$$, '2024-06-16 10:24:28.612706');
insert into сообщение values (default, 106, 'клиент', $$И все засохли Но в общем и целом они смотрелись довольно приятно – Вот что я сказал$$, '2024-06-15 15:21:04.350994');
insert into сообщение values (default, 107, 'клиент', $$Миссия «Криккита-1» заключалась в том, чтобы выяснить, есть ли что-то с той стороны неба, откуда, вероятно, и происходил разбившийся корабль На горизонте маячили симпатичные круглые холмы$$, '2024-03-22 06:44:57.029655');
insert into сообщение values (default, 107, 'консультант', $$Реакция публики, точнее, реакции были многообразными и различными$$, '2024-03-22 00:08:01.193565');
insert into сообщение values (default, 107, 'консультант', $$– Ммммм… – столь же тихо произнес компьютерный терминал рядом с ним – Слушайте и наблюдайте – Я занялся издевательствами над животными, – проговорил он беззаботно – Чего?

– Мммммм мммммммм мммм мммммммм$$, '2024-03-22 20:26:12.087840');
insert into сообщение values (default, 107, 'клиент', $$Тот же самый эффект наблюдался и в случае с кораблем Слартибартфаста И я подключился к цепи открытия моста Правда, роботы сыпались не абы как, а четким военным строем И так же внезапно оно стихло$$, '2024-03-22 17:40:43.999991');
insert into сообщение values (default, 108, 'клиент', $$– Фгм, – произнес робот и вернулся к своему занятию, а именно очень медленному хождению по очень маленькому кругу – Ты где?

– В туалете – Да уж вот так, – подтвердил Форд Больше ничего не произойдет$$, '2024-08-03 20:41:06.819139');
insert into сообщение values (default, 108, 'клиент', $$– Гм$$, '2024-08-03 14:29:07.741406');
insert into сообщение values (default, 108, 'клиент', $$– Это необходимо убрать, – сказали криккитяне, направив корабль в сторону дома$$, '2024-08-01 19:07:10.535077');
insert into сообщение values (default, 109, 'консультант', $$Он опять воззрился на экран Есть частные клубы летателей, где вам помогут достичь ключевого самозабвения$$, '2025-08-08 02:16:28.411073');
insert into сообщение values (default, 109, 'консультант', $$– А-а, – воскликнул он, сосредоточившись на первом попавшемся имени Это была безумная колымага из подручных материалов Золотая Перекладина заключена в механизме, который движет вашим кораблем$$, '2025-08-06 01:20:27.662108');
insert into сообщение values (default, 109, 'клиент', $$Следовательно, надо отыскать этого собрата Артур мудро кивнул сам себе$$, '2025-08-06 11:11:22.655956');
insert into сообщение values (default, 110, 'клиент', $$Вам того же Те, кто рождается бессмертным, от рождения бессознательно свыкаются с этим своим свойством, но Охмешконасыпатель – не из их числа$$, '2025-10-03 08:16:21.335016');
insert into сообщение values (default, 110, 'клиент', $$Холод, тяжесть, беспросветность потихоньку проникли в сердце Артура, и он остро ощутил переживания пилотов-криккитян, повисшие в воздухе кабины, точно грозовое электричество – Но почему? Почему нельзя?

– Те, кто разговаривает по телефону сам с собой, ничего хорошего не узнают$$, '2025-09-30 05:25:19.592946');
insert into сообщение values (default, 110, 'консультант', $$– Но зачем вы все ходите и ходите кругами? – спросил матрасс Старец, пропустив эти слова мимо ушей, внимательно, с непонятным в данной ситуации волнением следил за происходящим на поле И только мощность моего блока счастья подкачала$$, '2025-09-30 19:38:38.326434');
insert into сообщение values (default, 111, 'клиент', $$Он упорно работал суставами Корабль вылетел из Облака Также никому не известно, что за радость находят в своем образе жизни матрассы$$, '2024-02-29 07:12:30.716748');
insert into сообщение values (default, 111, 'консультант', $$Другими словами, имелись в наличии все предпосылки для приступа самокопания, но, как показала жизнь, поддаваться ему никак не следовало – Ну и как там?

– А это что, твоя пещера? – спросил Форд Зафоду пришло в голову, что для ускорения беседы предложения нужно сделать вопросительными$$, '2024-02-29 14:20:45.072623');
insert into сообщение values (default, 111, 'клиент', $$Только двадцать минут назад он решил сойти с ума – и вот уже гоняется по лугам доисторической Земли за честерфильдским диваном$$, '2024-03-01 12:02:48.768194');
insert into сообщение values (default, 111, 'консультант', $$Однако матрасс попался какой-то уж очень глупый и лишь воззрился на него в ответ круглыми глазами – Да? – обалдело переспросил Зафод Широко развел руки$$, '2024-02-29 17:47:20.623695');
insert into сообщение values (default, 112, 'консультант', $$Фигура тихо преклонила перед ним колени – А это розовое$$, '2025-12-06 12:27:59.463059');
insert into сообщение values (default, 112, 'клиент', $$Форд и Артур воззрились на него с крайним удивлением и острым чувством обиды за хороший вкус Глаза Артура пошли колесом – Онизавялилеппе! – снова завопил Слартибартфаст – Вы хотите дослушать эту историю или что?

– Мне хотелось бы услышать вашу речь, – заявил матрасс$$, '2025-12-06 14:06:46.052079');
insert into сообщение values (default, 113, 'консультант', $$Он плюнул на это занятие и, переведя взгляд на навигационный экран, ахнул при виде беспрецедентного полчища звезд – Твои идеи – мои идеи, – согласился Зафод Вселенское Переустройство будет возобновлено$$, '2025-06-15 07:12:12.037308');
insert into сообщение values (default, 113, 'консультант', $$– Это же крикетная площадка «Лордз», верно? – возопил Артур – Я, собственно, хочу сказать, – продолжал Форд, – что нет смысла доводить себя до безумия стараниями это безумие избежать Одиннадцать белых роботов, тесно сгрудясь, вознеслись сквозь редеющее облако и, напоследок плюнув пламенем, скрылись в животе своего белого корабля, который с кратким ропотом (будто сотня тысяч людей вымолвила: «Фу!») немедленно растворился в том же воздухе, из которого раньше сгустился$$, '2025-06-14 01:55:43.323861');
insert into сообщение values (default, 113, 'консультант', $$А на скатерти пребывало с полдюжины тарелок с недоеденными итальянскими кушаньями Форд взял его за руку – Я дома, – шептал Артур Меж тем снаружи солнце лило свой свет на веселую толпу$$, '2025-06-13 17:49:01.948651');
insert into сообщение values (default, 114, 'клиент', $$Одиннадцать белых роботов Не характерное для дверной речи выражение – ННП – это нечто, что мы не можем увидеть, или не видим, или то, чего нам не дает увидеть наш мозг, потому что мы считаем, что это не наша проблема – Артур Дент? – переспросило оно$$, '2025-02-25 05:05:46.622674');
insert into сообщение values (default, 114, 'клиент', $$– Мы взлетели, – пояснил Слартибартфаст$$, '2025-02-23 08:31:26.648905');
insert into сообщение values (default, 114, 'клиент', $$Пора смываться Голос робота был под стать его корпусу – холодный, элегантный, безжизненный – Мощность моей мыслительной деятельности на всех ее уровнях и во всех ее аспектах столь же безгранична, как бескрайние просторы самой Вселенной Он подождал реакции Артура, но тот лишь благоразумно обронил:

– Давай дальше$$, '2025-02-24 19:46:33.723790');
insert into сообщение values (default, 115, 'клиент', $$И каждый, любой из них, встретится ему на пути Настоящим «стопщикам» эти клубы, как правило, не по карману, но можно рекомендовать их как возможное место для временной работы Артур, погруженный в мысли об Эссексе и Ирландии, на миг растерялся$$, '2024-10-16 10:35:27.723233');
insert into сообщение values (default, 115, 'клиент', $$– Странная весть, – процедил Форд Ах, как прекрасен – аж глазам больно – был «Звездный Титаник», когда, точно арктурианский мегавакуумный серебристый кит, он качался в лазерных тенетах гибких строительных лесов$$, '2024-10-16 08:12:37.178161');
insert into сообщение values (default, 115, 'консультант', $$Не будучи уверен в понятливости четвертого стакана, он послал за ним пятый с дополнительными пояснениями и шестой чисто ради моральной поддержки Глянул на Артура – тот тихо напевал себе под нос – Ничего не знаю, ничего не слышу, ничего не вижу, – причитал он на бегу, – это не моя планета, я сюда не просился, не хочу ввязываться, просто вытащите меня отсюда и отвезите куда-нибудь в бар, к людям, которые мне свои!

Над полем взметнулся столб пламени и дыма$$, '2024-10-15 10:05:52.371480');
insert into сообщение values (default, 115, 'консультант', $$Но зубы ему не требовались Тьма Пылевого Облака сдавила корабль – И, – продолжал громоподобный голос, – Деревянный Столб – символ, – здесь бас слегка осип от избытка умиления, – могущества Природы и Духовности!

Лучи переместились на центральный столб$$, '2024-10-14 20:43:57.279277');
insert into сообщение values (default, 116, 'клиент', $$Вообще-то я практикуюсь Марвин отвлекся от своего утомительного кругового обхода И что любопытно – направление, в котором указала его рука, не совпадало с направлением его взгляда «Фундаментальное сердце духа и Вселенной может отдыхать, – подумал он, – это все туфта»$$, '2025-01-03 06:03:11.300002');
insert into сообщение values (default, 116, 'клиент', $$Фальшивка$$, '2025-01-05 12:19:30.394166');
insert into сообщение values (default, 116, 'консультант', $$– М-да-а-а-а-а, – промолвил он наконец, – да, но в чем тут загадочность? Он ведь не материализовался в подлинном смысле слова? Просто пробежал – Знаешь, – сказал Форд, – я…

– Где ты шатался? – прервал его Артур, чья голова все-таки покончила с физкультурной разминкой Скорбное выражение на лице Артура Дента уступило место еще более скорбному Они достигли цели$$, '2025-01-05 04:03:46.663621');
insert into сообщение values (default, 116, 'консультант', $$Затем они построили собственный корабль – он-то и готовился сейчас к взлету$$, '2025-01-05 20:59:01.941646');
insert into сообщение values (default, 117, 'клиент', $$Впереди них сидели трое пилотов – А куда мы держим путь?

– Мы держим путь, – объявил Слартибартфаст, – на битву с Древним Злом Вселенной$$, '2026-07-08 02:09:49.482701');
insert into сообщение values (default, 117, 'консультант', $$– Ну и хорошо, – сказал Артур Марвин отвлекся от своего утомительного кругового обхода$$, '2026-07-08 00:00:22.632531');
insert into сообщение values (default, 118, 'консультант', $$То был самый что ни на есть инопланетный инопланетянин – Что сталось с голгафрингемцами? – спросил Форд$$, '2024-10-11 14:34:00.707697');
insert into сообщение values (default, 118, 'консультант', $$Главное – промахнуться мимо земли случайно Слартибартфаст дернул за ручку, и она умолкла Примерно в 14$$, '2024-10-11 06:23:26.000291');
insert into сообщение values (default, 118, 'консультант', $$По-видимому, он полагал, что мнение Слартибартфаста слишком оптимистично Другое значение этого слова (согласно «Ультраполному максимегалонскому словарю всех возможных языков и наречий») – это звук, который вырвался у Его Светлости лорда Соньвальтяпа Пустецийского, когда до него дошло, что он второй год подряд позабыл о дне рождения своей жены$$, '2024-10-09 22:22:52.478797');
insert into сообщение values (default, 118, 'клиент', $$– Ага, чтоб ты его опять выбросил?

– Разумно, – сознался Артур – Странная весть, – процедил Форд$$, '2024-10-09 22:36:16.800452');
insert into сообщение values (default, 119, 'клиент', $$Ничто не шевелилось В ней стоял стол Мало того что они были белые, под цвет униформы игроков, но они еще и держали в манипуляторах нечто вроде крикетных бит и крикетных мячей Но тут синее полисменообразное нечто тронуло их обоих за плечи$$, '2025-08-20 06:14:14.513609');
insert into сообщение values (default, 119, 'консультант', $$Блаженно разжевав мясо, он решил официально оповестить мир о своем решении$$, '2025-08-20 08:43:25.749915');
insert into сообщение values (default, 119, 'клиент', $$Идиот, идиот и еще раз кретин Спустя некоторое время он начал медленно, воровато пробираться вперед с гримасой вдумчивой озадаченности на лице – как леопард, который не совсем уверен, что только что видел в полумиле впереди, на раскаленной и пыльной прерии, полупустую банку «Вискаса» Некоторое время они летели вперед, неподвижные на фоне глазастого тела Галактики, которое само было неподвижно на фоне бесконечных просторов Вселенной Бредя в сумерках к своей пещере, Артур вдруг заметил за облаками странные вспышки$$, '2025-08-20 07:00:20.648774');
insert into сообщение values (default, 120, 'клиент', $$– Потом расскажу Скажи мне только одно$$, '2024-08-27 14:13:20.299542');
insert into сообщение values (default, 120, 'клиент', $$Форд что-то мурлыкал под нос – Неверно, – пробурчал Марвин$$, '2024-08-28 00:45:09.758624');
insert into сообщение values (default, 120, 'консультант', $$Но несть числа тем, кто упивается историей «Звездного Титаника», легендарного корабля-колосса Оно опасно?

– Мммм С легким жужжанием и крайне зловещим видом он завис над землей Между мигом, когда криккитяне впервые узнали о существовании космоса как такового, и запуском этой первой ласточки среди космических кораблей прошел ровно год$$, '2024-08-28 18:17:26.838841');
insert into сообщение values (default, 120, 'консультант', $$Корабль пересекал орбиты планет Солнечной системы, намереваясь совершить пертурбационный маневр вокруг Солнца и, разогнавшись, выскочить в большой космос$$, '2024-08-27 05:31:10.157860');
insert into сообщение values (default, 121, 'клиент', $$Венских$$, '2025-03-24 16:04:44.686163');
insert into сообщение values (default, 121, 'консультант', $$Часа через два стало очевидно, что Зафод тверд в своем решении, и корабль вновь поднялся в небо, даже не спустив трапа – Ты где?

– В туалете И может статься, приведет к безвременной гибели всю Вселенную – Я сам знаю, на что это похоже, – отрезал Слартибартфаст и вошел в пресловутое помещение$$, '2025-03-26 16:37:58.072002');
insert into сообщение values (default, 121, 'клиент', $$Он уставился на диван умными глазами – А, вот как, – сказал Артур В матче$$, '2025-03-27 17:07:16.808321');
insert into сообщение values (default, 122, 'консультант', $$– Эти самые, с которыми он разговаривал – Что-то синее Болтайтесь над землей и парите, парите и болтайтесь$$, '2026-05-30 11:24:40.455881');
insert into сообщение values (default, 122, 'клиент', $$– Он вытащил «Путеводитель» и просмотрел по диагонали страницы указателя, специально посвященные вопросам секса, наркотиков и рок-н-ролла$$, '2026-05-29 08:36:53.403631');
insert into сообщение values (default, 123, 'консультант', $$– Ты что-то придумал, правда? – спросил Артур Окружающая его Вселенная распалась на мириады блестящих осколков, и каждый осколочек тихо вращался в пустоте, отражая своей серебряной кожей все то же жуткое пиршество огня и смерти$$, '2026-03-02 09:30:46.912223');
insert into сообщение values (default, 123, 'консультант', $$Довольные улыбки, которыми он обычно озарял чужие похороны, стали какими-то натянутыми$$, '2026-03-01 16:28:01.772648');
insert into сообщение values (default, 123, 'клиент', $$По-прежнему ничто не шевелилось – Только, – заверил его Форд Впереди них сидели трое пилотов Мне это кажется чрезвычайно странным, тем более что сумку я сшил на доисторической Земле своими руками$$, '2026-03-02 11:57:32.790784');
insert into сообщение values (default, 124, 'клиент', $$Из всех цивилизаций и племен Галактики только англичане могли воскресить воспоминание о самых ужасных войнах в истории Вселенной и превратить его в чрезвычайно замысловатую, нудную и бесцельную игру Его губы тоже дергались Корабль пересекал орбиты планет Солнечной системы, намереваясь совершить пертурбационный маневр вокруг Солнца и, разогнавшись, выскочить в большой космос Вся закавыка в том, что сумка, куда я хотел положить это полотенце, которое не мое, тоже не моя, хотя сходство поразительное$$, '2025-08-02 20:29:06.667697');
insert into сообщение values (default, 124, 'клиент', $$Но только не вверх$$, '2025-08-03 08:40:00.804064');
insert into сообщение values (default, 124, 'консультант', $$Душа Артура летала вокруг его тела кругами и мялась, не испытывая особенного желания войти$$, '2025-08-04 17:05:29.854086');
insert into сообщение values (default, 125, 'консультант', $$Я сам посадил сотни Ночью оно абсолютно черное Аналогично последовательность отдельных впечатлений сливалась тут в единое чувство – хотя на чувство оно как-то не походило$$, '2024-08-05 11:15:46.991657');
insert into сообщение values (default, 125, 'консультант', $$Через минуту я попрошу тебя раскрыться Самый подходящий афоризм, чтобы заронить в молодые умы искру вдумчивого отношения к жизни Артур поднял глаза$$, '2024-08-07 07:06:27.372109');
insert into сообщение values (default, 125, 'консультант', $$– Не могу не отметить того факта, что вы припарковали свой корабль, – сказал он, указав одним из подбородков в соответствующую сторону, – прямо поперек моего Артур откашлялся$$, '2024-08-06 11:00:12.677130');
insert into сообщение values (default, 125, 'клиент', $$Поскольку в истории был лишь один Его Светлость лорд Соньвальтяп Пустецийский, да и тот умер холостяком, слово употребляется лишь в отрицательном или в гипотетическом смысле Вначале он казался слишком голым, слишком безумным, слишком похожим на те, о которых человек с улицы сказал бы: «Ну как же, я и сам до этого давно уже додумался»$$, '2024-08-05 10:13:08.566210');
insert into сообщение values (default, 126, 'консультант', $$– Чего? Зачем? Эгей-гей! Ну-ка вернись и повтори!

Он подпрыгивал и выплясывал, пока его ноги не подкосились, взывал, пока не надорвал связки В этот миг необходимо полное, глубочайшее хладнокровие Роботы$$, '2027-12-02 17:24:04.364946');
insert into сообщение values (default, 126, 'консультант', $$– Что я и ожидал услышать, – продолжил Марвин, – а также я ожидаю узнать, что идея робота с искусственной ногой вас немало забавляет$$, '2027-12-02 14:40:56.217896');
insert into сообщение values (default, 127, 'консультант', $$Как ни странно, и тут моделью послужило маленькое итальянское бистро – Спасибо, что осчастливили простую скромную дверцу$$, '2024-11-17 01:41:28.058841');
insert into сообщение values (default, 127, 'консультант', $$Теперь слышался какой-то негромкий шум, и исходил он определенно из района рубки$$, '2024-11-16 21:18:41.989034');
insert into сообщение values (default, 127, 'клиент', $$В отчаянии он снова пихнул Форда локтем Порой он замирал, часто моргая$$, '2024-11-19 01:00:15.897727');
insert into сообщение values (default, 128, 'консультант', $$Распластавшись по стене, он стал пробираться к двери, только бы не нарушить рубежи поля (еле-еле заметные) Но тут он поднял глаза на ужасающе голый небосклон и остро ощутил всю важность этой детали И перевел взгляд на чудо творения за иллюминатором$$, '2025-08-26 00:25:39.578450');
insert into сообщение values (default, 128, 'клиент', $$Потом стал выключать освещение Слартибартфаст уверил его, что полет состоится, что они в полной безопасности, что их ожидает крайне поучительное, хоть и довольно мучительное зрелище По крайней мере я думаю, что оно думало, что оно джин с тоником… Есть вероятность, – добавил он с ухмылкой, от которой самые хладнокровные люди с воем полезли бы на деревья, – что мне это всего лишь примерещилось$$, '2025-08-25 17:05:37.284551');
insert into сообщение values (default, 129, 'консультант', $$Некоторое время все молчали, из чего Зафод заключил, что роботы явились сюда не для разговоров и дело за ним Как-то ночью – а теперь на корабле ночь длилась постоянно – лежа в постели, он решил взять себя в руки, предпринять что-нибудь конструктивное Умопомрачительно красивый, уникально огромный и к тому же самый уютный корабль в истории Галактики (точнее, в нынешней, сильно обкарнанной опровержениями версии этой самой истории – подробности см$$, '2025-10-16 11:11:34.486204');
insert into сообщение values (default, 129, 'клиент', $$– По-моему, его здесь нет, – сказал он мальчишкам, которые немедленно столпились вокруг него, – вероятно, он куда-то откатился Некоторые из нас гибнут от рук охотников, но, поскольку всех нас зовут Земами, утраты проходят незамеченными, и момнуханье, таким образом, остается минимальным$$, '2025-10-16 13:37:56.130874');
insert into сообщение values (default, 130, 'консультант', $$И я подключился к цепи открытия моста$$, '2024-04-25 07:10:12.914193');
insert into сообщение values (default, 130, 'консультант', $$Произошла настоящая революция$$, '2024-04-24 18:33:27.763367');
insert into сообщение values (default, 130, 'консультант', $$Он никогда не слышал, чтобы на Зете Прутивнобендзы выступали с речами, а тем более знаменитости Что Слартибартфаст в этом нашел такого интересного, ведал он один – Сгинь, тебе говорят, дурилка пластиковая$$, '2024-04-25 05:58:38.381335');
insert into сообщение values (default, 131, 'клиент', $$А потом даже гумкнул от избытка чувств – Что я и ожидал услышать, – продолжил Марвин, – а также я ожидаю узнать, что идея робота с искусственной ногой вас немало забавляет$$, '2026-04-05 06:26:49.230718');
insert into сообщение values (default, 131, 'консультант', $$Форд всячески демонстрировал агрессивную индифферентность к происходящему Ты что, не помнишь?

– Помню Если б Эффрафакс покрасил гору в ярко-розовый цвет, а сверху водрузил недорогой генератор ННП-поля, люди так и ходили бы мимо горы, вокруг нее, даже по ее склонам – ничуть не подозревая о ее присутствии Над всеми нами простерты крыла смерти$$, '2026-04-08 21:38:35.785849');
insert into сообщение values (default, 131, 'консультант', $$– Я думал, ты сказал, что это не наша проблема Форд довел свою речь до конца, прежде чем Артур успел перейти от тупого взгляда к тупым замечаниям Затем однажды ночью она внезапно созревает, отбрасывает внешнюю оболочку, которая рассыпается в прах, и выходит на свет божий в обличье крайне загадочного маленького металлического предмета с фланцами с обоих концов, чем-то вроде дырки под винт и чем-то вроде гребешка Нервно опираясь о стену коридора, он морщил лоб (то есть лбы), словно пытаясь откупорить бутылку методом телекинеза$$, '2026-04-07 19:34:19.696317');
insert into сообщение values (default, 132, 'клиент', $$Туда-то мы и отправимся День за днем они исследовали останки сгоревшего корабля, разгрызая секрет за секретом, распевая звонкие кораблеразборочные марши – Да? – обалдело переспросил Зафод – Ммммм ммммы?

– Все равно, какой головы$$, '2028-05-01 06:32:22.376731');
insert into сообщение values (default, 132, 'консультант', $$– Ему что-то не везло последние два миллиона лет, – пояснил он полисмену Будь ты хоть семи пядей во лбу, но за год спроектировать и построить такой корабль… Не верю Финиш$$, '2028-04-28 06:41:05.520509');
insert into сообщение values (default, 133, 'консультант', $$– Через несколько минут, – терпеливо повторил робот, – мы завладеем Золотой Перекладиной…

– Фигушки, – сказал Зафод$$, '2026-04-20 21:30:07.212659');
insert into сообщение values (default, 133, 'консультант', $$И вновь зашагал вперед$$, '2026-04-20 02:49:21.219843');
insert into сообщение values (default, 134, 'клиент', $$Мало того, нижние сегменты их ног были защищены чем-то вроде белых щитков Триллиан вновь терпеливо кивнула, досчитала до… – в общем, число было немаленькое – и сказала себе, что на данном этапе самое важное – хотя бы разговорить Зафода Оно опасно?

– Мммм$$, '2024-05-28 15:36:25.527158');
insert into сообщение values (default, 134, 'клиент', $$Дверь тихо закрылась за ним$$, '2024-05-29 20:20:18.902074');
insert into сообщение values (default, 134, 'консультант', $$«То, что надо», – решила Триллиан, и спустя несколько часов их огромный белый корабль в форме кроссовки уже вальяжно спускался с небес, украшенных жарко блестящим солнцем, к яркому космопорту-скале (Естественно, я не знаю их лично, но я знаю природу всех органических живых существ, и гораздо более досконально, чем хотел бы По крайней мере мне это кажется странным, – добавил он, – а то, что это факт, я знаю по опыту Весь мост, мост длинный, титаночугунный, на тысячу миль, моментально свернул свое сверкающее полотно и с плачем утопился в трясине, унося с собой всех до последнего прутивнобендзянина$$, '2024-05-30 08:14:42.755403');
insert into сообщение values (default, 134, 'клиент', $$– А где ты собираешься нас высадить?

– Мне понадобится ваша помощь Маленькие круги света выхватывали из мглы горшки с цветами, блестящие изразцы и разнообразные непонятные медные причиндалы Видите ли, они окружены колоссальным Пылевым Облаком$$, '2024-05-29 23:22:12.675902');
insert into сообщение values (default, 135, 'клиент', $$За исключением одного случая$$, '2025-12-17 10:31:36.074759');
insert into сообщение values (default, 135, 'консультант', $$– Фольфанга, – сообщил он и снова пискнул – Какой формы? – вопросил Форд – Откуда на этом поле диван? – вскричал он Какой-то матрасс только что повстречался с каким-то роботом$$, '2025-12-17 03:31:37.756036');
insert into сообщение values (default, 135, 'консультант', $$– И сумка тоже не моя, – неожиданно объявил Артур Под ними расстилались серебристо-белые ризы Аллосиманиуса-Синеки Выдвинулись длинные опоры, совершая изящные балетные па во славу технического прогресса Господи, здесь же их полным-полно$$, '2025-12-17 14:41:13.178193');
insert into сообщение values (default, 136, 'клиент', $$По-видимому, это словесное излияние вдохновило его на новый взлет к высотам уныния и отчаяния Артур, растроганный и недоумевающий, только замотал головой$$, '2024-06-20 12:34:15.869437');
insert into сообщение values (default, 136, 'клиент', $$– Давайте, вы двое, – сказало нечто, – пройдемте На полпути к рубке его осенило, что это вполне может оказаться Марвин, и он бегом вернулся обратно Что ж, одной загадкой меньше$$, '2024-06-20 14:35:48.245131');
insert into сообщение values (default, 136, 'клиент', $$– Серьезно?

– Да Они не просто убивают людей – они их подбрасывают вверх$$, '2024-06-18 22:37:23.032053');
insert into сообщение values (default, 137, 'клиент', $$Это они шли в тот вечер по тропе, распевая мелодичные, проникновенные песни – Это что-то важное, – рассудил Артур и окликнул старца – Думаю, активный спорт поможет тебе не замыкаться на собственных переживаниях$$, '2025-09-14 13:16:14.167654');
insert into сообщение values (default, 137, 'клиент', $$Корабль пересекал орбиты планет Солнечной системы, намереваясь совершить пертурбационный маневр вокруг Солнца и, разогнавшись, выскочить в большой космос$$, '2025-09-14 15:26:31.065332');
insert into сообщение values (default, 137, 'консультант', $$– Грядет катастрофа, – заявил Слартибартфаст Я не спец по межличн… межличностным взаи-мо-от-но-ше-ни-ям, во…

Триллиан только подняла брови – Ключ, – спокойно продолжал робот, – был развеян на ветру пространств и времен – Правда, – сказал робот$$, '2025-09-14 11:40:51.502792');
insert into сообщение values (default, 137, 'клиент', $$С тем же успехом можно покориться судьбе, а здравый рассудок поберечь на потом Слартибартфаст быстрым шагом вошел в «аквариум» и, судя по всему, затеял какой-то пустой разговор с метрдотелем, а один из роботов-клиентов, авторазмякающая модель, меж тем тихо сполз под стол, не переставая рассказывать, что именно собирается сделать с неким типом из-за некой девушки Как ни странно, и тут моделью послужило маленькое итальянское бистро – Порвалась, – добавил он, – ни с того ни с сего порвалась цепь причин и следствий…

И наперекор сказанному, неуклюже сполз под стол после еще одного стакана$$, '2025-09-15 19:58:02.041282');
insert into сообщение values (default, 138, 'консультант', $$– Это, сказал бы я, тоже очень любопытный случай, – заявил Артур, поспешно закрыв сумку и прикинувшись, что высматривает мяч на земле Марвин помедлил, отдавшись воспоминаниям$$, '2025-03-03 18:07:08.077082');
insert into сообщение values (default, 138, 'клиент', $$– Дайте мне формы и контуры$$, '2025-03-03 02:00:26.529311');
insert into сообщение values (default, 138, 'клиент', $$Главный же ужас состоял в том, что пещера находилась в лондонском районе Айлингтон и первый автобус в центр должен был отправиться примерно через два миллиона лет$$, '2025-03-04 18:47:25.663599');
insert into сообщение values (default, 138, 'клиент', $$Приятели направились к пресловутому кораблю – Куда теперь?

– Вычисляю – А вот это, – сказал Слартибартфаст, перейдя на загробный хрип и указывая на компанию криккитян, которые удалялись в сторону города, – те самые, с кого все началось$$, '2025-03-03 04:01:40.977692');
insert into сообщение values (default, 139, 'клиент', $$Словно ниоткуда, зазвучала музыка Тихо-тихо-тихо дверь прошептала:

– Я вас слышу$$, '2025-08-24 10:09:27.583912');
insert into сообщение values (default, 139, 'консультант', $$Компьютер пискнул Единственная надежда – застичь ННП врасплох краешком глаза$$, '2025-08-25 15:00:15.370852');
insert into сообщение values (default, 139, 'клиент', $$– И что ты там делаешь?

– Сижу Они попросили меня открыть мост$$, '2025-08-24 07:17:13.314856');
insert into сообщение values (default, 140, 'клиент', $$Они бежали, не разбирая дороги, через траву, подпрыгивали, хохотали, кричали друг другу: «Загоняй его сюда!», «Перехватывай!» Солнце мечтательно освещало травяное море, крохотные полевые животные сломя голову разбегались из-под их ног К сожалению, невежественный Зафод не был польщен этой честью, ибо, как мы уже упомянули, в детстве интересовался не древней историей, а собственным органическим телом С этим вместилищем у нее были связаны не самые лучшие воспоминания$$, '2025-03-15 05:51:05.705506');
insert into сообщение values (default, 140, 'консультант', $$– Но зачем вы все ходите и ходите кругами? – спросил матрасс И все же она медленно, опасливо забралась в него и заняла свое привычное место Древнее Зло встало из могилы Глаза Форда, провожавшего взглядом мяч, широко распахнулись$$, '2025-03-15 17:13:22.080146');
insert into сообщение values (default, 140, 'клиент', $$Залезайте, нам пора Это крупные, благодушные, чехольно-пружинные существа, живущие тихой, уединенной жизнью в болотах Зеты Прутивнобендзы Я не шучу Болтайтесь над землей и парите, парите и болтайтесь$$, '2025-03-14 01:47:32.858169');
insert into сообщение values (default, 141, 'консультант', $$– Именно$$, '2025-01-01 22:29:17.179075');
insert into сообщение values (default, 141, 'клиент', $$– Надеюсь, когда до этого дойдет, я буду в стельку пьян – Полагаю, – добавил он, сделав передышку на писк, – что вы решили обозвать его безмозглой задницей Он спорил с судьбой, лез на рожон, срывал цветы удовольствий и сумасшедшие деньги на высокодоходных долгосрочных сберегательных вкладах… в общем, давал всем жизни, как говорится НИКОМУ НЕ МАШИТЕ$$, '2024-12-31 17:51:51.685477');
insert into сообщение values (default, 141, 'консультант', $$Первое не-абсолютное число – это число людей, на которое заказан столик – Ну, как я уже сказал, ваша команда только что победила$$, '2025-01-02 12:24:23.138222');
insert into сообщение values (default, 141, 'консультант', $$– Просто прими на веру все, что я тебе скажу, и сразу все станет совсем, совсем ясно Он прислушался, но в свист ветра вплетались лишь привычные голоса полусумасшедших энтомологов, перекликающихся через мрачную трясину – Однажды мне довелось произнести речь, – сказал он внезапно, как бы безо всякой связи с предыдущим – Он вновь раскрыл глаза и блаженно улыбнулся$$, '2025-01-01 14:08:24.989799');
insert into сообщение values (default, 142, 'консультант', $$– Мне много не надо, – кричал Форд в уточнение своих предыдущих замечаний, – только рюмка крепкого виски и компания братьев по духу!

Он несся, как лань, замешкавшись лишь на миг, чтобы взять на буксир Артура, который среагировал было на катастрофу в своем обычном духе – замер с открытым ртом, ожидая, пока все кончится – Компьютер, – вновь прошипел он$$, '2027-03-16 06:40:32.483479');
insert into сообщение values (default, 142, 'консультант', $$– Это не мое полотенце, – заявил Артур, копавшийся в своей сумке из кроличьей шкурки Досадные раздоры, обычно начинающиеся на этом этапе, испокон веку оставались вне поля зрения науки просто потому, что никто не воспринимал их всерьез Самый подходящий афоризм, чтобы заронить в молодые умы искру вдумчивого отношения к жизни$$, '2027-03-16 07:22:44.455937');
insert into сообщение values (default, 143, 'консультант', $$Тихо-тихо-тихо дверь прошептала:

– Я вас слышу Вы видели этот фильм всего лишь тридцать три тысячи пятьсот семнадцать раз Тут Артура посетила некая неясная догадка относительно смысла представшего перед ним зрелища, но он поспешил ее отбросить$$, '2024-04-18 11:59:58.683597');
insert into сообщение values (default, 143, 'консультант', $$Только двадцать минут назад он решил сойти с ума – и вот уже гоняется по лугам доисторической Земли за честерфильдским диваном И теперь, стоя в молчании и одиночестве посреди темного коридора, он содрогнулся при воспоминании о содеянном Во-первых, из-за ННП-поля$$, '2024-04-19 04:51:18.048553');
insert into сообщение values (default, 143, 'консультант', $$– И сумка тоже не моя, – неожиданно объявил Артур – Ммммм ммммы?

– Все равно, какой головы А там происходило всего лишь то, что люди столпились на площадке вокруг ее середины$$, '2024-04-17 22:40:51.871645');
insert into сообщение values (default, 143, 'клиент', $$Многие из них попадаются в силки охотников, после чего их убивают, высушивают, экспортируют и кладут на кровати, чтобы люди на них спали Над тремя столбиками сияли, слепя глаза, две перекладины Созерцая тускло-розовый контур двери, он осознал, что во мраке коридора еле-еле различаются границы сенсорно-тактичного поля, которое и предупреждало дверь о появлении кого-то, перед кем следует раскрыться с любезными словами Матрасс момнухнул еще раз$$, '2024-04-17 22:52:13.106116');
insert into сообщение values (default, 144, 'консультант', $$Наши герои взошли вслед за Слартибартфастом на борт и были столь ошарашены увиденным внутри, что совершенно не заметили нового странного происшествия снаружи Похоже, на них восседали не то девушки, не то ангелы Другая планета, другой рассвет совсем другого дня$$, '2024-05-17 13:47:08.779581');
insert into сообщение values (default, 144, 'клиент', $$Ему пришло в голову, что во Вселенной непременно найдется кто-то, кому жизнь кажется еще более беспросветной, тяжелой и треклятой, чем ему Он уже много дней шлялся, не зная покоя, по «Золотому сердцу», но еще не было случая, чтобы какая-нибудь дверь сказала: «Уф!» Да и сейчас он был почти уверен, что «Уф!» исходило не от двери$$, '2024-05-17 01:04:41.041422');
insert into сообщение values (default, 144, 'клиент', $$Большой стеклянный ящик, этакий аквариум – точнее, целая комната А потом все завершилось – так же внезапно, как и началось Дело в том, что принцип его работы основан на свойственной людям естественной предрасположенности не видеть ничего из того, чего видеть не желаешь, увидеть не предполагаешь или не можешь себе объяснить$$, '2024-05-18 05:42:03.721382');
insert into сообщение values (default, 145, 'клиент', $$Скажи мне только одно – Неверно, – пробурчал Марвин$$, '2027-01-18 06:11:13.973838');
insert into сообщение values (default, 145, 'консультант', $$– Он гордо возносился над водами?

– Да, он гордо возносился над водами Прищурившись, как Клинт Иствуд, он уставился на горизонт$$, '2027-01-19 10:10:17.100979');
insert into сообщение values (default, 146, 'клиент', $$Компьютер безголосо пискнул в знак окончания вычислений – Осмелюсь заметить, что ваши диоды полны глубокой печали, – влючал он (чтобы узнать значение слова «влючать», купите либо трактат «Речь жителей болот Прутивнобендзы» – имеется на любом складе уцененных книг, либо «Максимегалонский словарь», чем страшно порадуете университет, вынужденный отводить под его хранение свою драгоценную автостоянку), – и это меня очень огорчает$$, '2025-06-15 07:29:04.337801');
insert into сообщение values (default, 146, 'клиент', $$Было неопровержимо доказано, что количество зрителей, смотревших телерепортаж о запуске «Титаника», превосходило все население Вселенной на тот момент$$, '2025-06-16 00:42:32.370319');
insert into сообщение values (default, 146, 'консультант', $$Многие из них попадаются в силки охотников, после чего их убивают, высушивают, экспортируют и кладут на кровати, чтобы люди на них спали$$, '2025-06-16 22:43:52.578584');
insert into сообщение values (default, 147, 'консультант', $$Они достигли цели Реакция публики, точнее, реакции были многообразными и различными$$, '2026-05-13 15:13:20.709725');
insert into сообщение values (default, 147, 'клиент', $$Оно, случайно, не твое?

– Изволь заткнуться насчет твоего полотенца! – воскликнул Форд Затем, выпучив глаза, бросился к полисмену с воплем:

– Тогда почему я так одет? – И, упав на траву, забился в судорогах Поплотнее запахнувшись в свой обтрепанный халат, он приветствовал доброе утро широкой улыбкой – Ну, корабль ведь твой$$, '2026-05-13 02:10:52.182170');
insert into сообщение values (default, 147, 'клиент', $$А придумал он вот что Затем Артур заметил, что идущая впереди компания тоже обратила внимание на визг и пришла в замешательство$$, '2026-05-12 21:09:46.573488');
insert into сообщение values (default, 148, 'консультант', $$– Когда мы последний раз виделись, вы сказали то же самое, – заметил Артур – И он сверкал? – воскликнул очарованный матрасс – И все же, – продолжало оно, – спустя пару деньков всему этому придет конец, не правда ли? Хотя, как я уже вам говорил при нашей последней встрече, это меня весьма опечалило$$, '2024-12-01 08:08:56.039975');
insert into сообщение values (default, 148, 'клиент', $$– Что сталось с голгафрингемцами? – спросил Форд По жизни он не согласился бы взойти на борт такого корабля даже за всю рисовую водку страны Китай – Куда? На чем? – воскликнул Артур Разумеется, экипаж не реагировал на присутствие посторонних – ведь их тут, в сущности, и не было$$, '2024-12-02 07:52:21.401026');
insert into сообщение values (default, 148, 'консультант', $$Несомненно, «Золотое сердце» произвело здесь фурор, и Триллиан была польщена$$, '2024-12-01 06:41:07.386176');
insert into сообщение values (default, 149, 'консультант', $$По-моему, – пояснил Артур, не сбавляя скорости Но тут же просияв, перевел взгляд на широкий экран панорамного обзора, где струились, головокружительно сплетаясь и расплетаясь вокруг корабля, серебряные нити Над тремя столбиками сияли, слепя глаза, две перекладины А потом тьма позади Вселенной взорвалась, и каждый лоскуток тьмы обернулся косматым дымом преисподней$$, '2025-02-10 09:18:03.428918');
insert into сообщение values (default, 149, 'консультант', $$– Вы хотите дослушать эту историю или что?

– Мне хотелось бы услышать вашу речь, – заявил матрасс Холод, тяжесть, беспросветность потихоньку проникли в сердце Артура, и он остро ощутил переживания пилотов-криккитян, повисшие в воздухе кабины, точно грозовое электричество$$, '2025-02-10 13:52:47.842665');
insert into сообщение values (default, 149, 'консультант', $$Одно-единственное «Уф!», и все тут$$, '2025-02-10 16:02:19.605049');
insert into сообщение values (default, 149, 'клиент', $$С того дня прошло уже два года$$, '2025-02-11 13:36:58.367449');
insert into сообщение values (default, 150, 'консультант', $$– Я думал, ты умер… – вырвалось у него$$, '2025-05-05 12:38:43.907061');
insert into сообщение values (default, 150, 'консультант', $$Глаза Артура пошли колесом Артур поднял глаза Несбыточная греза Робинзона – корабль Спустя некоторое время он начал медленно, воровато пробираться вперед с гримасой вдумчивой озадаченности на лице – как леопард, который не совсем уверен, что только что видел в полумиле впереди, на раскаленной и пыльной прерии, полупустую банку «Вискаса»$$, '2025-05-04 14:13:49.768164');
insert into сообщение values (default, 150, 'клиент', $$Вследствие чего школьная администрация отправила компьютер в клинику для помешанных киберустройств, куда за ним последовала и девочка, имевшая глупость влюбиться в злосчастную машину И все же они продолжали погоню, а диван вальсировал и вертелся, а потом вдруг развернулся и вошел в пике, словно сорвавшись с порога графика, изображающего кризис, причем Форд с Артуром оказались буквально над ним Форд с Артуром, пыхтя, бежали за ним, но диван увертывался и петлял, точно пространство имело для него иную, сложную математическую топографию – как оно и было в действительности Некоторое время они летели вперед, неподвижные на фоне глазастого тела Галактики, которое само было неподвижно на фоне бесконечных просторов Вселенной$$, '2025-05-05 05:00:16.514551');
insert into сообщение values (default, 151, 'клиент', $$– Не могу я с ней сжиться, – мрачно вымолвил он и выслал в свой желудок третий стакан: пусть найдет второй и выяснит, почему тот еще не доложил о здоровье первого – Эксцентрика Гамбитус, ты ее когда-нибудь видел? Троегрудая путана с Эротикона-6 – Вы хотите дослушать эту историю или что?

– Мне хотелось бы услышать вашу речь, – заявил матрасс Защитник, взмахнув битой, послал мяч себе за спину так, что он пролетел над табло$$, '2027-12-16 23:16:30.391493');
insert into сообщение values (default, 151, 'клиент', $$Они прошли очень близко от наблюдателей под деревом, размахивая фонарями, от чего по траве и листве скакали забавные «зайчики», радостно болтая между собой и самым натуральным образом распевая песню о том, как все чуд-чуд-чудесно на свете, как они счастливы, как здорово они потрудились на ферме и как приятно возвращаться домой, где ждут жены и дети$$, '2027-12-18 08:15:34.095752');
insert into сообщение values (default, 152, 'консультант', $$Он снял с рычага воображаемую трубку и стал крутить воображаемый диск$$, '2025-07-11 15:02:28.887446');
insert into сообщение values (default, 152, 'клиент', $$Его взгляд неспешно подполз к дате, по которой Форд лениво постукивал пальцем В этот момент Артур заметил странную особенность песни, которую распевали криккитяне Вся закавыка в том, что сумка, куда я хотел положить это полотенце, которое не мое, тоже не моя, хотя сходство поразительное Форд с Артуром решили покориться судьбе и претерпеть мучения$$, '2025-07-11 19:01:03.443648');
insert into сообщение values (default, 152, 'клиент', $$– Где вы ее нашли и как сюда переместили? По-моему, – добавил он, потирая лоб, – мне надо успокоиться$$, '2025-07-11 17:26:23.354838');
insert into сообщение values (default, 153, 'консультант', $$– … верно я говорю? – добавил он – Он вновь раскрыл глаза и блаженно улыбнулся$$, '2027-09-30 09:13:31.622323');
insert into сообщение values (default, 153, 'клиент', $$Существо невозмутимо смотрело на него Крича, вопя, сшибая друг друга, люди со всех сторон бросились к площадке – Это только документальный фильм, – вскричал он$$, '2027-10-01 09:03:00.753066');
insert into сообщение values (default, 154, 'консультант', $$– При передвижении по космосу, знаете ли… – проговорил Слартибартфаст, возясь с оборудованием Зала информационных иллюзий, – … при передвижении по космосу… – Не договорив, он принялся озираться по сторонам Матрасс момнухнул еще раз$$, '2024-05-28 10:37:19.473492');
insert into сообщение values (default, 154, 'консультант', $$Забудьте, сколько вы весите (забудьте, что вы вообще что-то весите), и просто позвольте ветру поднимать вас все выше На сем разрешите объявить это злополучное киберсооружение открытым для бездумных издевательств всякого, кого понесет нелегкая ступить на него»$$, '2024-05-29 09:48:31.039938');
insert into сообщение values (default, 154, 'консультант', $$– Гм… ну ладно, – проговорил Зафод Но теперь все происходило слишком уж молниеносно – сплошное видеотактильное пятно, которое волокло их сквозь века галактической истории, крутясь, дергаясь, мерцая Аналогично последовательность отдельных впечатлений сливалась тут в единое чувство – хотя на чувство оно как-то не походило$$, '2024-05-28 06:27:55.849112');
insert into сообщение values (default, 154, 'консультант', $$Топ-топ$$, '2024-05-29 08:07:36.617489');
insert into сообщение values (default, 155, 'клиент', $$Но несть числа тем, кто упивается историей «Звездного Титаника», легендарного корабля-колосса$$, '2025-11-24 06:33:02.045302');
insert into сообщение values (default, 155, 'консультант', $$– Назревают великие события – Мы могли бы перекинуться словечком о погоде Главный же ужас состоял в том, что пещера находилась в лондонском районе Айлингтон и первый автобус в центр должен был отправиться примерно через два миллиона лет$$, '2025-11-26 05:04:16.374299');
insert into сообщение values (default, 155, 'консультант', $$Строго индивидуально, лицом к лицу, одного за другим и (тут он с особым сладострастием скрипнул зубами) в алфавитном порядке – Но зачем вы все ходите и ходите кругами? – спросил матрасс – И если ты считаешь, что тебе действительно необходимо слоняться по крикетной площадке в такой момент…

– Считаю В ней стоял стол$$, '2025-11-24 02:34:35.983469');
insert into сообщение values (default, 156, 'консультант', $$По крайней мере я думаю, что оно думало, что оно джин с тоником… Есть вероятность, – добавил он с ухмылкой, от которой самые хладнокровные люди с воем полезли бы на деревья, – что мне это всего лишь примерещилось – Мы уже установили, что оно не мое$$, '2026-05-20 14:07:12.158972');
insert into сообщение values (default, 156, 'клиент', $$И само собой разумеется, он был слегка пьян$$, '2026-05-20 16:38:38.902559');
insert into сообщение values (default, 157, 'консультант', $$Слартибартфаст делал Форду с Артуром отчаянные знаки и что-то кричал Искусственная мебель, искусственная скатерть По-видимому, он полагал, что мнение Слартибартфаста слишком оптимистично Они бежали, не разбирая дороги, через траву, подпрыгивали, хохотали, кричали друг другу: «Загоняй его сюда!», «Перехватывай!» Солнце мечтательно освещало травяное море, крохотные полевые животные сломя голову разбегались из-под их ног$$, '2028-05-20 23:30:55.597043');
insert into сообщение values (default, 157, 'консультант', $$– Только-то? – опасливо уточнил Артур – Компьютер, – вновь прошипел он Он уставился вверх Также вы научитесь правильно приземляться – сразу предупредим, что первая попытка выйдет большущим комом$$, '2028-05-24 08:32:07.271847');
insert into сообщение values (default, 158, 'клиент', $$И поистине, она того стоит Я уже пояснил, что в основном беседовал с деревьями$$, '2026-02-07 00:37:52.731284');
insert into сообщение values (default, 158, 'клиент', $$Форд вытащил из своей жутко обтрепавшейся и донельзя замызганной сумки субэфирный чуткомат – Мы взлетели, – пояснил Слартибартфаст Понимаете, мысль «Мы одни во Вселенной» их ни разу не посещала, потому что до сегодняшнего вечера они вообще не знали о существовании Вселенной$$, '2026-02-07 00:31:09.591151');
insert into сообщение values (default, 158, 'клиент', $$Музыка рвала и метала Артур опять кивнул и умоляюще покосился на Форда, но тот репетировал мину униженного и оскорбленного – не без успеха$$, '2026-02-06 13:54:05.856122');
insert into сообщение values (default, 159, 'клиент', $$Одно-единственное «Уф!», и все тут$$, '2025-05-19 00:18:40.036409');
insert into сообщение values (default, 159, 'клиент', $$– …моргал…

– Ну да$$, '2025-05-18 11:34:16.646279');
insert into сообщение values (default, 159, 'клиент', $$Также вы научитесь правильно приземляться – сразу предупредим, что первая попытка выйдет большущим комом Зафод так изумился, что роботам пришлось дать еще один залп, прежде чем он упал На следующий день Артур сшил себе сумку из кроличьей шкурки – под всякие полезные вещи – Ммммм?

– Когда я выну у тебя кляп…

– Ммммм$$, '2025-05-16 23:44:54.858797');
insert into сообщение values (default, 159, 'клиент', $$– Из мглы времен восстало великое проклятие, – сказал Слартибартфаст Стратегия заключалась в том, чтобы он перехватил предыдущий у скрещения дорог, и пусть соединенными силами поднимут дух второго$$, '2025-05-18 17:07:11.962588');
insert into сообщение values (default, 160, 'клиент', $$Дело в том, что принцип его работы основан на свойственной людям естественной предрасположенности не видеть ничего из того, чего видеть не желаешь, увидеть не предполагаешь или не можешь себе объяснить Им составляли компанию недоеденные ломти хлеба и недопитые бокалы вина – Никто на это место не нападет, – сказал Слартибартфаст с неожиданным волнением в голосе Проведя рукой по стене, он нащупал нечто ценное$$, '2026-02-14 22:04:56.130692');
insert into сообщение values (default, 160, 'клиент', $$Зафод крякнул Какое-то время он бездействовал, словно ожидая, что люди займутся своими обычными делами, не порицая его за это висение$$, '2026-02-17 03:50:42.991875');
insert into сообщение values (default, 160, 'консультант', $$– Сходить с ума, так сходить, – рассудил Форд – Алло? Да? – пробормотал Артур – Я дома, – хрипло буркнул Артур$$, '2026-02-17 15:49:28.268121');
insert into сообщение values (default, 161, 'клиент', $$Начал моросить дождь$$, '2024-09-04 01:11:53.416905');
insert into сообщение values (default, 161, 'клиент', $$– Что, неужели сейчас на это место нападут? – спросил он$$, '2024-09-05 04:03:34.079175');
insert into сообщение values (default, 161, 'консультант', $$И естественно, на следующее утро Меграмал больше не был виден НИКОМУ НЕ МАШИТЕ Короче говоря, он вознамерился сойти с ума – … нестабильности… – завершил Форд$$, '2024-09-05 03:13:35.696913');
insert into сообщение values (default, 161, 'консультант', $$И расстроенно поглядел на воображаемый телефон С кличем внезапного восторга он спрыгнул с утеса и весело помчался вдогонку за Фордом Префектом и своенравным предметом мебели$$, '2024-09-05 10:42:14.760604');
insert into сообщение values (default, 162, 'консультант', $$Ему пришло в голову, что во Вселенной непременно найдется кто-то, кому жизнь кажется еще более беспросветной, тяжелой и треклятой, чем ему$$, '2025-04-17 11:45:44.568295');
insert into сообщение values (default, 162, 'консультант', $$– Вон за тем диваном!

Артур взглянул в указанную сторону Бредя в сумерках к своей пещере, Артур вдруг заметил за облаками странные вспышки$$, '2025-04-18 22:52:12.057227');
insert into сообщение values (default, 162, 'консультант', $$Раздался залп И оторопел от последствий своего заявления$$, '2025-04-19 06:48:35.689208');
insert into сообщение values (default, 163, 'клиент', $$Однако Эффрафакс все же проиграл пари – и лишился головы – из-за педантизма некоего арбитра, обратившего внимание на то, что: а) при прохождении через место, где следовало находиться Меграмалу, он ни обо что не споткнулся и не расшиб себе лоб и б) в небесах засияла какая-то подозрительная новая луна$$, '2026-01-07 11:03:51.863553');
insert into сообщение values (default, 163, 'консультант', $$Финиш$$, '2026-01-05 20:57:42.198822');
insert into сообщение values (default, 163, 'консультант', $$– Остатки сожженного столбика Форд с Артуром, пыхтя, бежали за ним, но диван увертывался и петлял, точно пространство имело для него иную, сложную математическую топографию – как оно и было в действительности – И он сверкал? – воскликнул очарованный матрасс – Мы планируем вас застрелить$$, '2026-01-05 06:10:09.707108');
insert into сообщение values (default, 163, 'консультант', $$Робкий солнечный луч, случайно пробившийся сквозь туман, высветил синие и белые полоски на шкуре матрасса, чем немало его напугал Слартибартфаст сказал:

– Потому что при передвижении по космосу числа – настоящий бич божий Новая вибрация сотрясла корабль$$, '2026-01-07 05:59:08.191550');
insert into сообщение values (default, 164, 'клиент', $$Форд, нас подбрасывают!

И действительно, для того чтобы не поддаться этому первому впечатлению, надо было обладать весьма глубокими познаниями в истории Галактики (каковых Артур еще не успел приобрести из-за своей кочевой жизни) – И все же довел это дело до конца$$, '2024-09-21 10:26:24.093761');
insert into сообщение values (default, 164, 'консультант', $$– Что случилось? – спросил Артур с глубоким благоговением Триллиан терпеливо кивнула самой себе, досчитала до предыдущего числа в кубе, вяло швырнула поднос в стену, прошла в телепортационную кабину и просто ушла из его жизни$$, '2024-09-20 18:23:11.240226');
insert into сообщение values (default, 164, 'консультант', $$– И что же с ней стало? – спросил Артур – Судя по всему… – произнес Форд, – … в ткани пространства-времени… – произнес Форд, – … появились… – произнес Форд, – … очаги…

Артур тупо смотрел на отворот своего халата, сжимаемый пальцами Форда$$, '2024-09-22 05:37:21.030929');
insert into сообщение values (default, 165, 'клиент', $$– Какое расстояние мы сейчас преодолели? – спросил Форд Сквозь мрак виднелись лишь огни ближнего городка Пользуясь секретами древних мастеров, они любовно смонтировали этот сувенир, который украсит ваш дом – в напоминание о павших и в знак почтения к Галактике – нашей Галактике, – на алтарь которой они положили свои жизни…

Тут мимо вновь проплыл Слартибартфаст$$, '2025-09-25 15:57:02.992324');
insert into сообщение values (default, 165, 'клиент', $$Охмешконасыпатель только хмыкнул Но тут же, заметив, что отряхивает именно халат, застыл как вкопанный – Быть такого не может, – сказал Форд, когда наблюдатели оправились от ускорения, а корабль уже рассекал верхние слои атмосферы И что самое удивительное, точно специально экипированные для данного мероприятия$$, '2025-09-23 23:20:15.533645');
insert into сообщение values (default, 166, 'консультант', $$– Чтоб твои диоды сгнили и выпали$$, '2026-05-11 06:36:52.271511');
insert into сообщение values (default, 166, 'клиент', $$Небосвод – от горизонта до горизонта, с востока до запада, с севера до юга – был абсолютно черен – Вне всяких сомнений, – ответил Форд с не меньшей непреклонностью Птицы выражали в песнях свое мнение обо всем этом – по-видимому, благоприятное$$, '2026-05-11 23:10:14.464455');
insert into сообщение values (default, 166, 'консультант', $$Он напряг слух, но больше ничего не слышалось – Мы отправляемся в путь, – вскричал он, весь трепеща от прилива сил Дело было поздно ночью – что правда, то правда – Это необходимо убрать, – сказали криккитяне, направив корабль в сторону дома$$, '2026-05-09 13:20:12.463086');
insert into сообщение values (default, 167, 'клиент', $$– Ничего не знаю, ничего не слышу, ничего не вижу, – причитал он на бегу, – это не моя планета, я сюда не просился, не хочу ввязываться, просто вытащите меня отсюда и отвезите куда-нибудь в бар, к людям, которые мне свои!

Над полем взметнулся столб пламени и дыма$$, '2024-11-13 03:31:51.884254');
insert into сообщение values (default, 167, 'консультант', $$Это был рубеж, за который никто из криккитян не заглядывал даже в мечтах, поскольку не знал о его существовании Несколько биллионов триллионов тонн сверхразогретых, лопающихся ядер водорода медленно вознеслись над горизонтом, прикинувшись при этом маленькими, холодными и чуточку сырыми$$, '2024-11-12 09:51:13.722937');
insert into сообщение values (default, 167, 'консультант', $$– Эй! – вскрикнул Артур Попятившись, Артур испуганно огляделся по сторонам Так и вышло Это Англия, сегодня… сегодня кошмару конец$$, '2024-11-12 21:50:28.486059');
insert into сообщение values (default, 167, 'консультант', $$– Я обнаружил, – заявил он, – аномальные протечки$$, '2024-11-11 16:11:59.602698');
insert into сообщение values (default, 168, 'консультант', $$Было неопровержимо доказано, что количество зрителей, смотревших телерепортаж о запуске «Титаника», превосходило все население Вселенной на тот момент$$, '2025-06-20 20:38:08.817075');
insert into сообщение values (default, 168, 'консультант', $$Настоящим «стопщикам» эти клубы, как правило, не по карману, но можно рекомендовать их как возможное место для временной работы$$, '2025-06-20 22:37:19.725267');
insert into сообщение values (default, 169, 'консультант', $$Крича, вопя, сшибая друг друга, люди со всех сторон бросились к площадке Нежданно-негаданно вывалившись из пространственно-временной аномалии в чудный, совершенно очаровательный лондонский денек, Форд с Артуром совершили довольно жесткую посадку на безупречный газон площадки «Лордз» Он указал, чтó понимает под термином «вон там»$$, '2025-04-01 05:07:37.488691');
insert into сообщение values (default, 169, 'консультант', $$Это была безумная колымага из подручных материалов$$, '2025-04-01 05:35:44.481585');
insert into сообщение values (default, 169, 'консультант', $$Левая голова посмотрела влево, а правая – вправо, и обе решили, что следует отправиться куда глаза глядят – Разве что «Психоз в космосе» Форд взял его за руку$$, '2025-03-31 05:11:31.808644');
insert into сообщение values (default, 170, 'клиент', $$А когда раскроешься, я тебя прошу, не говори, что тебя это осчастливило, ладно?

– Ладно И перевел взгляд на чудо творения за иллюминатором – Чай, – произнес он, – крикет, – добавил он с нежностью, – стриженые газоны, деревянные скамейки, белые полотняные пиджаки, пиво в банках…

Медленно-медленно его взгляд сфокусировался на газете – … и премного довольна вновь затвориться с сознанием выполненного долга$$, '2024-09-23 19:22:02.619198');
insert into сообщение values (default, 170, 'консультант', $$Его взгляд неспешно подполз к дате, по которой Форд лениво постукивал пальцем Робот, стоявший к Зафоду ближе всех, смотрел на него с таким видом, будто снимал подробную мерку со всего его тела, души и способностей Крикетный мяч, встреченный с таким восторгом, свалился с небес прямо в загадочную кроличью сумку Артура$$, '2024-09-22 23:54:34.964521');
insert into сообщение values (default, 170, 'консультант', $$На сем разрешите объявить это злополучное киберсооружение открытым для бездумных издевательств всякого, кого понесет нелегкая ступить на него» – Жду с нетерпением вашего рассказа о речи на болоте$$, '2024-09-23 09:39:07.380916');
insert into сообщение values (default, 171, 'клиент', $$Артур привстал с дивана и помотал головой:

– Куда мы летим?

– На битву с Древним…

– Замнем, – вмешался Форд – Я отыскал озерцо, которое думало, что оно джин с тоником, и стал в нем бултыхаться$$, '2024-06-16 16:40:04.032976');
insert into сообщение values (default, 171, 'консультант', $$Они легли на низкую орбиту – Космовидеотон, Мыслекинозал, Надомный Думатель, – известил он и пискнул$$, '2024-06-15 10:40:32.324410');
insert into сообщение values (default, 171, 'консультант', $$Артур не потрудился ответить$$, '2024-06-16 03:03:54.945882');
insert into сообщение values (default, 171, 'консультант', $$– Опасно?

– Мммм Не знаю, зачем им это надо, но так оно и есть Я, наоборот, от нее бегал Засунув руки в единственный карман своего халата, он воззрился вдаль с видом знатока$$, '2024-06-16 12:43:12.133946');
insert into сообщение values (default, 172, 'консультант', $$Маленькие круги света выхватывали из мглы горшки с цветами, блестящие изразцы и разнообразные непонятные медные причиндалы Не слушайте окружающих – ничего полезного они не скажут$$, '2024-12-11 17:40:11.496448');
insert into сообщение values (default, 172, 'клиент', $$Умопомрачительно красивый, уникально огромный и к тому же самый уютный корабль в истории Галактики (точнее, в нынешней, сильно обкарнанной опровержениями версии этой самой истории – подробности см – Я сойду с ума! – возгласил он – И уставился в крохотный иллюминатор – на кромешную тьму Только тускло-розовые каемки вокруг дверей, мерцавшие в такт их речам, – Зафоду так и не удалось придумать, как заткнуть им глотки$$, '2024-12-12 06:33:29.944938');
insert into сообщение values (default, 172, 'консультант', $$– Порядок, – ответил он бодро, – ужас как хорошо$$, '2024-12-12 09:39:47.756670');
insert into сообщение values (default, 172, 'клиент', $$– Форд резко отвернулся Он упорно работал суставами$$, '2024-12-11 13:41:24.425460');
insert into сообщение values (default, 173, 'клиент', $$– Мне кажется, – сказал Форд тоном, обещавшим (как уже было известно Артуру) какое-то чрезвычайно непонятное продолжение, – что вон там какое-то ННП$$, '2026-10-25 02:38:13.350481');
insert into сообщение values (default, 173, 'клиент', $$Звездолет (да-да, еще один, просто звездолетопад какой-то), только на сей раз изящный и серебряный, спустился с небес на площадку – тихо, как-то даже интеллигентно, совершая опорами балетные па во славу технического прогресса – Протечки?

– Протечки в пространстве-времени, – сказал Форд и поспешил подставить свое зверски ухмыляющееся лицо ветру, который как раз случайно пролетал мимо В матче – А это розовое$$, '2026-10-24 22:26:54.270081');
insert into сообщение values (default, 174, 'консультант', $$– Я не о полотенце, – сказал Артур Рука официанта заскользила по листкам блокнота с недостижимым для человека проворством, а затем еще быстрее, так что в глазах зарябило * * *
Хозяин звездолета, инопланетянин с дорогостоящим цветом лица, развалился в единственном кресле рубки Артур Дент$$, '2025-10-18 16:23:28.544122');
insert into сообщение values (default, 174, 'консультант', $$«Может ли быть, что это и есть истинное устройство Вселенной? – вопросил он себя – При передвижении по космосу, знаете ли… – проговорил Слартибартфаст, возясь с оборудованием Зала информационных иллюзий, – … при передвижении по космосу… – Не договорив, он принялся озираться по сторонам Поскольку в истории был лишь один Его Светлость лорд Соньвальтяп Пустецийский, да и тот умер холостяком, слово употребляется лишь в отрицательном или в гипотетическом смысле Корабль лениво дрейфовал где-то в галактической глуши, окруженный чернильно-черной пучиной космоса$$, '2025-10-17 17:16:41.631068');
insert into сообщение values (default, 175, 'консультант', $$– Сгинь, тебе говорят, дурилка пластиковая$$, '2026-07-07 12:56:57.588434');
insert into сообщение values (default, 175, 'консультант', $$– Это исток всему Пришельцы покидают площадку в сопровождении офицера полиции, и, по-моему, все входит в привычное русло, и игра сейчас возобновится Вокруг них расстилались нежно-зеленые поля и луга – Вам весело? – спросил матрасс$$, '2026-07-09 00:42:49.501654');
insert into сообщение values (default, 175, 'консультант', $$И может статься, приведет к безвременной гибели всю Вселенную – Не пугайтесь, – сказал он и немедленно испуганно воззрился на прибор, – это…

Конца его фразы Форд с Артуром не услышали, ибо в этот момент корабль, в котором они находились, просто испарился В нем они выражали сожаление, что из-за работы им приходилось долгими часами корпеть в сарае, не видя ни жен, ни детей, которые страшно по ним скучали, но подбадривали их бесконечными новостями о приключениях растущего щенка$$, '2026-07-10 07:33:12.698728');
insert into сообщение values (default, 175, 'клиент', $$– Игра, которую вы именовали крикетом, – проговорил он, точно из жерла преисподней, – относится к числу забавных капризов родовой памяти, благодаря которым многие концепции и образы продолжают жить в сознании, хотя их истинный смысл потерян во мгле времен$$, '2026-07-09 13:51:34.366495');
insert into сообщение values (default, 176, 'клиент', $$Неся в руках поднос с ужином, она вошла к Зафоду и спросила, нет ли у него желания поговорить Скорее всего до вас донесутся восклицания типа: «Боже праведный, ты что, летаешь? Быть такого не может!»

Жизненно важно не верить им – а то правда внезапно окажется на их стороне$$, '2025-06-06 14:20:16.734807');
insert into сообщение values (default, 176, 'клиент', $$В ней стоял стол Артур покачал головой – Ну…

– У официанта в блокноте реальное и ирреальное вступают в противоборство на столь глубинном уровне, что одно переходит в другое и наоборот, благодаря чему возможно практически все при соблюдении определенных принципов$$, '2025-06-06 18:11:26.054391');
insert into сообщение values (default, 176, 'клиент', $$Можете рассказать это вместо анекдота своим друзьям Зему и Зему при первой же встрече – они животики надорвут, если я их знаю Строго индивидуально, лицом к лицу, одного за другим и (тут он с особым сладострастием скрипнул зубами) в алфавитном порядке$$, '2025-06-06 22:20:46.732229');
insert into сообщение values (default, 177, 'консультант', $$Отряхнулся А там происходило всего лишь то, что люди столпились на площадке вокруг ее середины – Возможно, до вас не сразу дойдет, что именно навело меня на это воспоминание, – таков уж мой мозг$$, '2028-12-11 19:22:40.810034');
insert into сообщение values (default, 177, 'консультант', $$Ничто не шевелилось – Да, только я его выудил, – сообщил Форд Затем еще раз огляделся по сторонам с еще большим ужасом$$, '2028-12-14 11:41:35.581615');
insert into сообщение values (default, 178, 'консультант', $$А эта была не хуже прочих Артур Дент застрял на доисторической Земле в результате извилистой цепочки происшествий, в процессе каковых он попеременно подвергался оскорблениям и/или расщеплению на атомы в разнообразных экзотических уголках Галактики, бесчисленность и странность которых превзошли все его ожидания$$, '2026-12-24 18:11:50.170138');
insert into сообщение values (default, 178, 'клиент', $$Даже Форд, похоже, повеселел$$, '2026-12-28 02:44:40.851571');
insert into сообщение values (default, 178, 'клиент', $$Вот тогда-то он и набрел на свою цель жизни, дело, которое не позволит ему впасть в спячку никогда-никогда (так ему, во всяком случае, казалось) Присев на корточки, Артур ощутил под ладонями инфоиллюзии почвы и травы Не будучи уверен в понятливости четвертого стакана, он послал за ним пятый с дополнительными пояснениями и шестой чисто ради моральной поддержки$$, '2026-12-24 19:29:28.330594');
insert into сообщение values (default, 179, 'клиент', $$Еще раз широко улыбнувшись, он откусил кусочек от кроличьей ноги – остатка вчерашнего ужина$$, '2024-09-24 18:40:25.080060');
insert into сообщение values (default, 179, 'клиент', $$Бедные кретины Видение состроило нечто вроде ехидной ухмылки – впрочем, еще неизвестно, насколько ехидной, ибо солнце, светя ему прямо в затылок, соорудило из его серебристых волос и бороды ослепительный, драматический, повергающий в трепет нимб, с которым никакие ехидные ухмылки не вязались Холод, тяжесть, беспросветность потихоньку проникли в сердце Артура, и он остро ощутил переживания пилотов-криккитян, повисшие в воздухе кабины, точно грозовое электричество$$, '2024-09-24 19:47:35.203830');
insert into сообщение values (default, 179, 'клиент', $$Не характерное для дверной речи выражение – Терпение, – вновь заявил Слартибартфаст Пока я только процитирую «Путеводитель»…

– «Пу…»?

– «Путеводитель» – Привет, землянин, – ответил Слартибартфаст$$, '2024-09-24 00:53:57.737234');
insert into сообщение values (default, 180, 'клиент', $$«Автостопом по Галактике» А в моих руках точная копия, изготовленная руками народных умельцев$$, '2024-06-10 16:07:47.315384');
insert into сообщение values (default, 180, 'клиент', $$– Я же сказал! – заорал Форд, вскочив на ноги – Спасибо за внимание Затем он совершил нечто, что матрассы обычно делать ленятся$$, '2024-06-10 21:38:41.777176');
insert into сообщение values (default, 180, 'консультант', $$– Привет, Слартибартфаст, – наконец-то выдавил из себя Артур$$, '2024-06-10 19:38:24.200790');
insert into сообщение values (default, 180, 'консультант', $$– Ву-ун, – враднул он наконец Следовательно, надо отыскать этого собрата – Представьте себе, ни разу не подумать: «Мы одни-одинешеньки» – просто потому, что не знаешь, что можно жить по-другому Это Англия, сегодня… сегодня кошмару конец$$, '2024-06-11 15:30:42.949680');
insert into сообщение values (default, 181, 'клиент', $$– Трубку бросил, – пояснил он, пожал плечами и аккуратно положил свою воображаемую трубку на воображаемый рычаг Не вынимая спичек$$, '2026-06-14 12:14:09.073573');
insert into сообщение values (default, 181, 'консультант', $$Мне крикет вообще-то нравится, – добавил он, – но на взгляд большинства, вы в наивности своей создали ужасную пошлость – А во-вторых, – продолжал Форд, – у тебя в бороде кость Причем наутро участники напрочь забывали о произошедшем$$, '2026-06-16 12:22:40.132482');
insert into сообщение values (default, 181, 'консультант', $$Вдруг он точно взорвался, обернувшись вихрем бессчетных рук и ног, из которого вылетел мяч Дверь тихо закрылась за ним Зафод испытал секундное недоумение, но, скосив глаза на свою руку, с облегчением узрел, что предмет, обнаруженный им на стене коридора, оправдал его надежды$$, '2026-06-15 06:01:40.239396');
insert into сообщение values (default, 182, 'клиент', $$Вначале он казался слишком голым, слишком безумным, слишком похожим на те, о которых человек с улицы сказал бы: «Ну как же, я и сам до этого давно уже додумался» Вот оно – то, что разрушили орды Криккита, то, что теперь держит их планету в заточении и будет держать до скончания вечности!

И вальяжным жестом мужчина извлек из воздуха модель Трикетной Калитки$$, '2025-04-08 00:46:27.066458');
insert into сообщение values (default, 182, 'консультант', $$– Хм Правда, ангелы так не одеваются, точнее, не раздеваются Это Артур Дент говорит$$, '2025-04-07 21:49:21.336636');
insert into сообщение values (default, 182, 'консультант', $$Очень многие не пережили зиму, а когда пришла весна, уцелевшие заявили, что уходят в отпуск, и уплыли на плоту – На самом деле? – спросил Артур, ни на миг не отводя глаз от Форда – … нестабильности… – завершил Форд Все было ясно из самой его походки$$, '2025-04-09 19:15:11.908424');
insert into сообщение values (default, 182, 'клиент', $$– Недурная мысль, – заметил Форд Префект, соскальзывая с валуна, на котором сидел – Возмущения в континууме!

– А, это они мебельные магазины громят! – воскликнул Артур, с трудом вернувшись в вертикальное положение и – как он смел надеяться – в здравый рассудок – Было что-то интересное?

И вновь они балансировали на краю ужасно высокого утеса$$, '2025-04-09 19:18:03.804805');
insert into сообщение values (default, 183, 'консультант', $$Для полноты картины не хватало только, чтобы порыв ветра драматически взъерошил его волосы – но местный ветерок баловался с какими-то листьями в сторонке, а на Форда и внимания не обращал Бредя в сумерках к своей пещере, Артур вдруг заметил за облаками странные вспышки – Какое-то «что»?

– ННП$$, '2024-12-06 03:15:37.527369');
insert into сообщение values (default, 183, 'консультант', $$То, что вы испытали…

Слартибартфаст, проплывая мимо, помахал Артуру рукой$$, '2024-12-06 05:10:04.236313');
insert into сообщение values (default, 183, 'клиент', $$– И сумка тоже не моя, – неожиданно объявил Артур Эта штука недавно проснулась Артур последовал совету, вначале несколько нервно, словно боясь, что рука сейчас обернется скользкой рыбиной$$, '2024-12-06 22:33:57.593310');
insert into сообщение values (default, 183, 'клиент', $$Против инстинкта не попрешь – наши герои невольно двигались опасливо, даже воровато, хоть и знали, что с тем же успехом могли трубить в трубы и вопить: «Ату!» – инфоиллюзию это бы не спугнуло – Кто же?

– Мммммм мммммм мммммм, – сказал компьютер Меж тем снаружи солнце лило свой свет на веселую толпу$$, '2024-12-07 12:49:58.191741');
insert into сообщение values (default, 184, 'консультант', $$– Эти самые, с которыми он разговаривал Припев был немного печальный$$, '2026-09-26 19:40:22.720378');
insert into сообщение values (default, 184, 'консультант', $$Несколько биллионов триллионов тонн сверхразогретых, лопающихся ядер водорода медленно вознеслись над горизонтом, прикинувшись при этом маленькими, холодными и чуточку сырыми Вокруг него – около дюжины стульев При этих словах Артура точно пчела ужалила$$, '2026-09-26 04:59:49.656702');
insert into сообщение values (default, 185, 'клиент', $$Бистроматика как таковая являет собой революционно-новый подход к интерпретации поведения чисел$$, '2029-11-20 05:21:45.711592');
insert into сообщение values (default, 185, 'консультант', $$– А вот это, – сказал Слартибартфаст, перейдя на загробный хрип и указывая на компанию криккитян, которые удалялись в сторону города, – те самые, с кого все началось Ни информации, ни иллюзий – только они трое, белые стены да несколько мелких устройств, которые, по-видимому, следовало подключить к некой розетке – Какое расстояние мы сейчас преодолели? – спросил Форд – … людей, существ, ваших братьев по разуму…

Взметнулась музыка – музыка под стать зрелищу, исполинская$$, '2029-11-15 07:47:17.513535');
insert into сообщение values (default, 186, 'клиент', $$Артур пожал плечами – Если тревога ложная, я сойду с ума, – добавил он, – еще разок – Что, неужели сейчас на это место нападут? – спросил он$$, '2029-08-12 04:31:45.626805');
insert into сообщение values (default, 186, 'клиент', $$Если не считать разговоров с некоторыми дубами – этим хоть в лоб, хоть по лбу И ухмыльнулся с хорошо рассчитанной издевкой Стена, казалось, все близилась и близилась, густела и густела, тяжелела и тяжелела Весь мост, мост длинный, титаночугунный, на тысячу миль, моментально свернул свое сверкающее полотно и с плачем утопился в трясине, унося с собой всех до последнего прутивнобендзянина$$, '2029-08-12 07:44:09.822751');
insert into сообщение values (default, 187, 'клиент', $$Люк сам собой захлопнулся$$, '2025-09-03 08:16:10.493083');
insert into сообщение values (default, 187, 'клиент', $$– Не могу не отметить того факта, что вы припарковали свой корабль, – сказал он, указав одним из подбородков в соответствующую сторону, – прямо поперек моего – Тс-с, – прошипел Форд и глубокомысленно воздел очи горе$$, '2025-09-02 18:22:52.390159');
insert into сообщение values (default, 187, 'клиент', $$– Вы начали говорить…

Слартибартфаст пронзительно взглянул на него и заявил:

– Числа – настоящий бич божий – Уф!

Зафод остановился Туман висел неподвижно, точно то самое перехваченное на полдороге дыхание$$, '2025-09-01 16:55:48.479715');
insert into сообщение values (default, 187, 'консультант', $$С кличем внезапного восторга он спрыгнул с утеса и весело помчался вдогонку за Фордом Префектом и своенравным предметом мебели И только Слартибартфаст ежился, точно ему было не по себе – Отлично, – проговорил Форд очень тихо Другая планета, другой рассвет совсем другого дня$$, '2025-09-02 20:51:07.984903');
insert into сообщение values (default, 188, 'консультант', $$Ужасное потрясение, которое они испытали, когда, завывая и гремя, горящий звездолет упал с небес, врезавшись в холм примерно в полумиле от них, словами не передашь – Но только в порядке хобби Топ-топ-топ-топ-топ Она просто ушла – превратилась в случайный набор точек, странствующий по Вселенной$$, '2025-07-20 12:28:03.983253');
insert into сообщение values (default, 188, 'клиент', $$И ухмыльнулся с хорошо рассчитанной издевкой – Чего? Зачем? Эгей-гей! Ну-ка вернись и повтори!

Он подпрыгивал и выплясывал, пока его ноги не подкосились, взывал, пока не надорвал связки Осмелюсь признаться, я питаю некоторую слабость к крикету, хотя я не хотел бы, чтобы о ней знали за пределами этой планеты$$, '2025-07-22 12:04:42.728422');
insert into сообщение values (default, 188, 'клиент', $$Левая голова посмотрела влево, а правая – вправо, и обе решили, что следует отправиться куда глаза глядят$$, '2025-07-21 03:46:06.580217');
insert into сообщение values (default, 189, 'консультант', $$От вас требуется одно – решительно кинуться вниз, не боясь ожидающей вас физической боли – Гм… ну ладно, – проговорил Зафод$$, '2025-04-13 08:22:43.936013');
insert into сообщение values (default, 189, 'клиент', $$– Ты козел, Дент, – промолвила она просто$$, '2025-04-13 19:52:30.701736');
insert into сообщение values (default, 189, 'клиент', $$К его немалому удивлению, на поле перед ними находился мягкий диван, так называемый честерфильдский, обитый бархатом веселенького оттенка Он уставился на диван умными глазами$$, '2025-04-14 06:43:16.999263');
insert into сообщение values (default, 189, 'консультант', $$– Вам весело? – спросил матрасс Наши Повелители выйдут на свободу Все трое постепенно пробивались к звездолету старца, по-прежнему стоящему позади табло и по-прежнему не замечаемому бегущими мимо него зрителями – очевидно, у них хватало собственных проблем$$, '2025-04-13 21:49:10.137004');
insert into сообщение values (default, 190, 'клиент', $$Безусловно, это были не земляне, хотя все различия состояли в чуть-чуть слишком высоком росте, излишней худобе, угловатости и бледной, почти белой коже$$, '2026-07-10 14:01:37.615084');
insert into сообщение values (default, 190, 'клиент', $$Матрасс зауйломикал с головы до пят, отчего гладь мелкой, заросшей ряской протоки подернулась восторженной рябью$$, '2026-07-11 07:18:35.580799');
insert into сообщение values (default, 190, 'клиент', $$– Классно, – молвил Артур – и его душа выпорхнула наружу перевести дух Но не думаю, что с дурными намерениями – Уф, нащупал, – сообщил он Эти проблемы обычно относили на счет таких абстракций, как вежливость, грубость, скупость, задиристость, усталость, эмоциональность или поздний час$$, '2026-07-11 09:30:03.937457');
insert into сообщение values (default, 191, 'консультант', $$– Мм… да, – ответил Артур На восьмом такте этой баллады, который сам по себе мог бы сделать Маккартни полноправным хозяином Винчестера, не говоря уже об окрестностях, текст стал каким-то странным$$, '2027-11-13 08:26:52.843645');
insert into сообщение values (default, 191, 'клиент', $$– Тогда почему у вас в бороде кость?

– Я воспитываю в ней смирение с любым местоположением, – произнес Артур, сам собой гордясь$$, '2027-11-12 13:44:16.559799');
insert into сообщение values (default, 192, 'клиент', $$) Ха! О, жизнь моя – жестянка, жестянка на червячном ходу!

И снова побрел вокруг своей тонкой стальной ноги-протеза, которая вращалась в грязи, но никак не поддавалась – Считайте, что вы ее уже выразили, мой дорогой друг, – флюрбнул матрасс, – считайте, что вы ее уже выразили – По крайней мере мне так кажется$$, '2025-07-18 19:46:51.402446');
insert into сообщение values (default, 192, 'клиент', $$Они немного прошли в сторону города, и инфоиллюзия травы приятно пружинила под ногами, а инфоиллюзии цветов безупречно благоухали$$, '2025-07-19 02:56:27.686917');
insert into сообщение values (default, 192, 'консультант', $$– Я, собственно, хочу сказать, – продолжал Форд, – что нет смысла доводить себя до безумия стараниями это безумие избежать – Вон там! – вскричал Форд, дико взмахнув рукой Проведя рукой по стене, он нащупал нечто ценное Артур Дент, с его богатым опытом блужданий по закоулкам пространства и времени, может утверждать это со всей ответственностью$$, '2025-07-20 00:01:56.128461');
insert into сообщение values (default, 193, 'консультант', $$И только Слартибартфаст ежился, точно ему было не по себе – Все последние пять лет приснились мне во сне Они легли на низкую орбиту Строго индивидуально, лицом к лицу, одного за другим и (тут он с особым сладострастием скрипнул зубами) в алфавитном порядке$$, '2025-10-23 15:23:59.606822');
insert into сообщение values (default, 193, 'клиент', $$Форд протянул руку и потрогал приборную доску – Я-то думал, что стряслось, – сказал Форд, – а это просто матч кончился$$, '2025-10-23 01:47:41.118032');
insert into сообщение values (default, 193, 'консультант', $$Этот миг пришел и миновал без происшествий, как и бывало обычно на Зете Прутивнобендзы Однако через некоторое время до него дошло, что он недалеко продвинулся и все же следует спросить: «Это в каком плане?»

– При передвижении по космосу, – повторил Слартибартфаст, – числа – настоящий бич божий$$, '2025-10-21 18:53:17.456685');
insert into сообщение values (default, 194, 'консультант', $$Толпа взревела Артуру почудилось, будто весь небосвод, галантно посторонившись, уступил им дорогу$$, '2028-12-23 18:02:56.650751');
insert into сообщение values (default, 194, 'клиент', $$Призрачные, но весьма агрессивные фигуры, шевелившиеся за толстой дымовой завесой, и впрямь будто пародировали удары нападающих$$, '2028-12-19 09:05:27.065681');
insert into сообщение values (default, 195, 'консультант', $$Понимаете, мысль «Мы одни во Вселенной» их ни разу не посещала, потому что до сегодняшнего вечера они вообще не знали о существовании Вселенной И первый же взрыв развеял первоначальную надежду Артура, что это всего лишь рекламная затея австралийских фабрикантов маргарина Они бежали, не разбирая дороги, через траву, подпрыгивали, хохотали, кричали друг другу: «Загоняй его сюда!», «Перехватывай!» Солнце мечтательно освещало травяное море, крохотные полевые животные сломя голову разбегались из-под их ног$$, '2029-04-05 16:41:55.566556');
insert into сообщение values (default, 195, 'клиент', $$– Где?

– Там$$, '2029-04-09 01:42:01.286458');
insert into сообщение values (default, 196, 'консультант', $$– Ликвидация, – сказал он Первая реакция: «На соплях держится» Стена, казалось, все близилась и близилась, густела и густела, тяжелела и тяжелела Мелкие подробности аварии не имеют значения, поскольку никому так и не удалось воспроизвести обстоятельства произошедшего, причем многие экспериментаторы при этом попали либо в дурацкое положение, либо на тот свет, либо и туда, и туда одновременно$$, '2025-02-02 15:19:13.926978');
insert into сообщение values (default, 196, 'клиент', $$– Я к этой фигне не шел Взамен она направила корабль на Аллосиманиус-Синеку, планету льдов, снега, умопомрачительных красот природы и ужасных морозов Форд, нас подбрасывают!

И действительно, для того чтобы не поддаться этому первому впечатлению, надо было обладать весьма глубокими познаниями в истории Галактики (каковых Артур еще не успел приобрести из-за своей кочевой жизни)$$, '2025-02-02 05:05:38.815782');
insert into сообщение values (default, 196, 'консультант', $$Инженеры и конструкторы в своей великой наивности решили снабдить «Титаник» экспериментальным генератором невероятностного поля, которое, по их расчетам, должно было обеспечить бесконечную невероятность каких бы то ни было неполадок на борту Он уставился на диван умными глазами Поддельные бутылки в поддельном бетоне$$, '2025-02-02 10:48:54.557742');
insert into сообщение values (default, 196, 'клиент', $$Это они шли в тот вечер по тропе, распевая мелодичные, проникновенные песни Топ-топ-топ-топ-топ – Это только документальный фильм, – вскричал он$$, '2025-02-02 19:24:51.840558');